      player.vel.x *= 0.5;
      if (player.weaponAmmo['TASER'] <= 0) { player.isTasing = false; player.taserTargetId = null; } 
      if (player.taserTargetId) {
        const target = (enemies.find(e => e.id === player.taserTargetId) || projectiles.find(p => p.id === player.taserTargetId)) as (Enemy | Projectile | undefined); 
        if (target && target.health > 0) { 
          const dx = (target.pos.x + target.width/2) - (player.pos.x + (player.facing === 1 ? player.width : 0)), dy = (target.pos.y + target.height/2) - (player.pos.y + 25), dist = Math.sqrt(dx*dx + dy*dy); 
          if (dist > TASER_RANGE + 100) { player.taserTargetId = null; } 
