              if (!b.hitCooldown || b.hitCooldown <= 0) { 
                const dmg = BossLogic.getBossDamage(b, stageId, currentWeapon); const isW = BossLogic.checkIsWeakness(stageId, currentWeapon); 
                b.health -= dmg; b.hitCooldown = ENEMY_HIT_COOLDOWN; spawnDamageNumber(b.pos, dmg, isW); 
