                  if (target.type === 'enemy') { const e = target as Enemy; e.isBlownAway = true; e.vel = { x: (Math.random()-0.5)*10, y: -15 }; spawnDeathShower(e.pos, 0); spawnPickup(e.pos); speakVulgarity('taser_kill'); } 
