        if (state.frame % 2 === 0) { state.particles.push({ pos: { x: p.pos.x + Math.random() * p.width, y: p.pos.y + Math.random() * p.height }, vel: { x: (Math.random()-0.5)*9, y: -Math.random()*15 }, life: 45, color: '#FF4500', size: 10 + Math.random()*12 }); } 
