    });

    enemies.forEach(e => {
      if (e.health > 0 && e.isOnFire) {
        if (!e.fireTimer) e.fireTimer = 0; e.fireTimer++;
        if (e.fireTimer >= FIRE_TICK_RATE) { e.health -= FIRE_DOT_DAMAGE; spawnDamageNumber(e.pos, FIRE_DOT_DAMAGE); e.fireTimer = 0; }
        if (state.frame % 3 === 0) { state.particles.push({ pos: { x: e.pos.x + Math.random() * e.width, y: e.pos.y + Math.random() * e.height }, vel: { x: (Math.random()-0.5)*4, y: -Math.random()*8 }, life: 30, color: '#FF4500', size: 6 + Math.random()*8 }); }
