    });

    state.enemies = enemies.filter(e => {
      if (e.isBlownAway) { e.pos.x += e.vel.x; e.pos.y += e.vel.y; e.vel.y += GRAVITY * 0.5; e.rotation = (e.rotation || 0) + 0.3; return e.pos.y < 1000; }
      if (e.health <= 0) return false;
