      const enemyOnScreen = e.pos.x + e.width > state.camera.x && e.pos.x < state.camera.x + CANVAS_WIDTH, enemyIsStunned = (e.pauseTimer || 0) > 0;
      if (e.enemyType === 'flyer' && !enemyIsStunned && !((e.frozenTimer && e.frozenTimer > 0) || e.isTased)) e.pos.y += Math.sin((state.frame + (e.initialX || 0)) / 25) * 1.2;

      if (e.isOiled && e.oiledTimer && e.oiledTimer > 0) { e.oiledTimer--; if (e.oiledTimer <= 0) e.isOiled = false; }

