        for (const other of state.enemies) if (other.id !== e.id && other.health > 0 && !other.isBlownAway && e.pos.x < other.pos.x + other.width && e.pos.x + e.width > other.pos.x && e.pos.y < other.pos.y + other.height && e.pos.y + e.height > other.pos.y) { other.health -= OILED_KNOCKBACK_IMPACT_DAMAGE; e.health -= OILED_KNOCKBACK_IMPACT_DAMAGE; other.vel.x = Math.sign(e.vel.x) * 5; e.isKnockedBack = false; e.vel.x = 0; break; }
        for (const b of blocks) if ((b.type === 'wall' || b.type === 'door' || b.type === 'ground') && e.pos.x < b.x + b.w && e.pos.x + e.width > b.x && e.pos.y < b.y + b.h && e.pos.y + e.height > b.y) { e.isKnockedBack = false; e.vel.x = 0; e.health -= OILED_KNOCKBACK_IMPACT_DAMAGE; break; }
