          if (enemyIsStunned) { e.pauseTimer!--; if (e.id.startsWith('rusher') || e.isOiled) { e.vel.x *= 0.92; e.pos.x += e.vel.x; } } 
          else if (!e.isKnockedBack) {
            e.shootTimer++;
            if (e.id.startsWith('rusher')) { if (enemyOnScreen && player.invincibilityTimer <= 0 && Math.abs((player.pos.y + player.height/2) - (e.pos.y + e.height/2)) < 80) e.vel.x = (player.pos.x < e.pos.x ? -1 : 1) * 6; else e.vel.x = 0; } 
            else if (e.behavior === 'patrol' || e.behavior === 'fly') { if (e.pos.x > (e.initialX + e.patrolRange) || e.pos.x < e.initialX) e.vel.x *= -1; } 
            else if (e.behavior === 'shoot' && enemyOnScreen) { e.isShieldActive = e.shootTimer < 80; if (e.shootTimer > 120) { state.projectiles.push({ id: `ep-${Date.now()}`, pos: { x: e.pos.x, y: e.pos.y + 15 }, vel: { x: -6, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy' }); e.shootTimer = 0; } } 
            else if (e.shootTimer > 60 && enemyOnScreen) { state.projectiles.push({ id: `ep-${Date.now()}`, pos: { x: e.pos.x + e.width/2, y: e.pos.y + 10 }, vel: { x: player.pos.x < e.pos.x ? -7 : 7, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy' }); e.shootTimer = 0; }
            e.pos.x += e.vel.x;
