      const hasShield = player.filthShieldTimer && player.filthShieldTimer > 0;
      const chargeHit = (player.isCharging || player.isUppercutting || hasShield) && player.pos.x < e.pos.x + e.width && player.pos.x + player.width > e.pos.x && player.pos.y < e.pos.y + e.height && player.pos.y + player.height > e.pos.y;

      if (chargeHit && enemyOnScreen && (!e.hitCooldown || e.hitCooldown <= 0)) {
        if (e.type === 'boss' && !state.arenaLocked) { player.vel = { x: (player.pos.x + player.width/2 < e.pos.x + e.width/2 ? -1 : 1) * 18, y: -4 }; player.pushbackTimer = 20; return true; }
        let damage = player.isCharging ? BOSS_CHARGE_DAMAGE : (player.isUppercutting ? (e.type === 'boss' ? BOSS_UPPERCUT_DAMAGE : ENEMY_UPPERCUT_DAMAGE) : 0);
        if (hasShield) { damage = e.type === 'boss' ? (stageId === 'Drug Trade Dale' ? 100 : 50) : damage + FILTH_SHIELD_CONTACT_DAMAGE; player.filthShieldTimer = 0; }
