        e.health -= damage; e.hitCooldown = ENEMY_HIT_COOLDOWN; spawnDamageNumber(e.pos, damage, true);
        if (e.health > 0) { player.vel = { x: (player.pos.x < e.pos.x ? -1 : 1) * PLAYER_PUSHBACK_VEL_X, y: PLAYER_PUSHBACK_VEL_Y }; player.pushbackTimer = 20; } 
        else { if (e.type === 'boss') BossLogic.triggerBossDeath(e, player.facing, false, stageId, currentWeapon, state, bossHelpers); else { e.isBlownAway = true; e.vel = { x: player.facing * 30, y: -15 }; spawnDeathShower(e.pos, player.facing); spawnPickup(e.pos); speakVulgarity('charge_kill'); } return false; }
      }
