        if (moveLeft) { player.facing = -1; player.vel.x = -PLAYER_SPEED; } else if (moveRight) { player.facing = 1; player.vel.x = PLAYER_SPEED; } else if (player.isGrounded) player.vel.x = 0; 
      }
    } 
    player.vel.y += GRAVITY; player.pos.x += player.vel.x; player.pos.y += player.vel.y;

    player.isGrounded = false;
    blocks.forEach(b => { if (player.pos.x < b.x + b.w && player.pos.x + player.width > b.x && player.pos.y < b.y + b.h && player.pos.y + player.height > b.y) { if (b.type === 'door' && state.doorState === 'closed') { onBossTransition(); state.doorState = 'opening'; return; } if (b.type === 'pit') return; const ovY = Math.min(player.pos.y + player.height - b.y, b.y + b.h - player.pos.y); if (ovY < 15) { player.pos.y = b.y - player.height; player.vel.y = 0; player.isGrounded = true; } } });

    state.projectiles = projectiles.filter(p => { 
      if (p.health <= 0) return false; p.pos.x += p.vel.x; p.pos.y += p.vel.y;
      if (p.owner === 'player') { for (const e of state.enemies) if (e.health > 0 && !e.isBlownAway && p.pos.x < e.pos.x + e.width && p.pos.x + p.width > e.pos.x && p.pos.y < e.pos.y + e.height && p.pos.y + e.height > e.pos.y) { e.health -= p.damage; spawnDamageNumber(e.pos, p.damage); if (e.health <= 0) { e.isBlownAway = true; e.vel = { x: 20, y: -10 }; } return false; } } 
      else if (player.invincibilityTimer <= 0 && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) { if (!invincibilityEnabled) player.health -= p.damage; player.invincibilityTimer = 60; return false; }
      return p.pos.x > state.camera.x - 200 && p.pos.x < state.camera.x + CANVAS_WIDTH + 200;
    });

    state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });
    state.damageNumbers = damageNumbers.filter(d => { d.pos.y += d.vel.y; d.life--; return d.life > 0; });

    if (!state.arenaLocked) state.camera.x = Math.max(0, Math.min(BOSS_DOOR_X - CANVAS_WIDTH + 100, player.pos.x - CANVAS_WIDTH / 2));
    onPlayerUpdate(player.health, player.specialCharges, player.specialChargeTimer, player.weaponAmmo);
  }, [status, stageId, onBossDefeated, currentWeapon, respawn, invincibilityEnabled, infiniteAmmoEnabled, infinitePowerEnabled, jumpToBossEnabled, onPlayerUpdate]);

  const drawPlayer = useCallback((ctx: CanvasRenderingContext2D, p: Player & { killSatisfactionTimer: number, bossKillSatisfactionTimer: number }) => {
    const state = gameStateRef.current;
    if (state.deathTimer > 0) return;
    ctx.save();
    let dX = p.pos.x, dY = p.pos.y, dW = p.width, dH = p.height;
    if (p.isDucking) { dY += 28; dH -= 28; }
    const isF = (p.invincibilityTimer > 0 || invincibilityEnabled) && Math.floor(state.frame / 5) % 2 === 0;
    if (!isF) { ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(dX, dY, dW, dH * 0.6); ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(dX, dY + dH * 0.6, dW, dH * 0.4); }
    ctx.fillStyle = 'black'; ctx.fillRect(dX + (p.facing === 1 ? dW - 12 : 4), dY + 12, 4, 4); ctx.fillRect(dX + (p.facing === 1 ? dW - 24 : 16), dY + 12, 4, 4);
    ctx.restore();
  }, [invincibilityEnabled]);

  const draw = useCallback(() => {
    const canvas = canvasRef.current; if (!canvas) return; const ctx = canvas.getContext('2d'); if (!ctx) return; const state = gameStateRef.current;
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) { ctx.fillStyle = 'black'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT); return; }
    const { player, enemies, projectiles, particles, blocks, camera, damageNumbers } = state;
    const colors = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_DARK, accent: '#fff' };
    ctx.fillStyle = colors.bg; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.save(); ctx.translate(-camera.x, -camera.y);
    blocks.forEach(b => { ctx.fillStyle = colors.ground; ctx.fillRect(b.x, b.y, b.w, b.h); });
    enemies.forEach(e => { if (e.health > 0 || e.isBlownAway) { ctx.fillStyle = e.type === 'boss' ? 'red' : 'purple'; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); } });
    drawPlayer(ctx, player);

    if (player.isTasing && player.currentWeapon === 'TASER') {
      ctx.save(); ctx.strokeStyle = COLORS.TASER_BOLT; ctx.lineWidth = 3; ctx.shadowBlur = 10; ctx.shadowColor = COLORS.TASER_BOLT;
      const startX = player.pos.x + (player.facing === 1 ? player.width : 0), startY = player.pos.y + 25;
      let endX, endY;
      const target = player.taserTargetId ? ((enemies.find(en => en.id === player.taserTargetId) || projectiles.find(pr => pr.id === player.taserTargetId)) as (Enemy | Projectile | undefined)) : null;
      if (target) { endX = target.pos.x + target.width/2; endY = target.pos.y + target.height/2; } 
      else { endX = startX + (player.facing * 400); endY = startY + (Math.sin(state.frame * 0.2) * 40); }
      ctx.beginPath(); ctx.moveTo(startX, startY);
      const segments = 12; for (let i = 1; i <= segments; i++) { const t = i / segments, px = startX + (endX - startX) * t + (Math.random() - 0.5) * 40, py = startY + (endY - startY) * t + (Math.random() - 0.5) * 40; ctx.lineTo(px, py); }
      ctx.stroke(); ctx.strokeStyle = 'white'; ctx.lineWidth = 1; ctx.stroke(); ctx.restore();
    }

    projectiles.forEach(p => { ctx.fillStyle = 'yellow'; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); });
    particles.forEach(p => { ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });
    damageNumbers.forEach(d => { ctx.fillStyle = 'white'; ctx.font = '12px "Press Start 2P"'; ctx.fillText(d.value.toString(), d.pos.x, d.pos.y); });
    ctx.restore();
  }, [status, stageId, drawPlayer]);

  useEffect(() => {
    let frameId: number; 
    const loop = () => { update(); draw(); frameId = window.requestAnimationFrame(loop); };
    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) frameId = window.requestAnimationFrame(loop); 
    return () => window.cancelAnimationFrame(frameId);
  }, [status, update, draw]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

