    const moveLeft = !playerIsStunned && player.pushbackTimer <= 0 && (km['a'] || km['arrowleft'] || km['keya']);
    const moveRight = !playerIsStunned && player.pushbackTimer <= 0 && (km['d'] || km['arrowright'] || km['keyd']);
    const jumpRequested = !playerIsStunned && player.pushbackTimer <= 0 && (km[' '] || km['space'] || km['z'] || km['j']);
    const chargeRequested = !playerIsStunned && player.pushbackTimer <= 0 && (km['shift'] || km['c']);
    const shootRequested = !playerIsStunned && player.pushbackTimer <= 0 && (mouse.current.down);

    const bossHelpers: BossLogic.BossHelpers = {
      spawnDamageNumber, spawnDeathShower, onBossDeath, speakVulgarity, playGunSound, spawnExplosion, spawnSteamExplosionParticles, spawnPoopExplosion, spawnPowderExplosion, spawnMethExplosion, spawnGlassShatter: (p) => PARTICLE_PALETTES.GLASS.forEach(c => spawnExplosion(p, c, 5, 0, 25, true)),
      setBossVulgarity: (t, d) => { state.bossLastVulgarity = t; state.bossVulgarityTimer = d; },
      setScreenShake: (d) => { state.screenShakeTimer = d; },
      setErnieVibration: (d) => { state.ernieVibrationTimer = d; },
      setPlayerStun: (d) => { state.playerStunTimer = d; },
      addProjectile: (p) => state.projectiles.push(p),
      addVolcano: (v) => state.bossVolcanoes.push(v),
      clearVolcanoes: () => state.bossVolcanoes = [],
      addVolcanoTelegraph: (v) => state.bossVolcanoTelegraphs.push(v),
      clearVolcanoTelegraphs: () => state.bossVolcanoTelegraphs = [],
      addPoopTelegraph: (t) => state.bossPoopTelegraphs.push(t),
      clearPoopTelegraphs: () => state.bossPoopTelegraphs = [],
      setVictorWallSide: (side: number) => state.victorWallSide = side,
      setTsunamiActive: (active: boolean) => state.tsunamiActive = active
    };

    const weaponHelpers: WeaponLogic.WeaponHelpers = {
      addProjectile: (p) => state.projectiles.push(p),
      addParticle: (p) => state.particles.push(p),
      playGunSound, spawnExplosion, spawnDamageNumber,
      spawnGlassShatter: (p) => PARTICLE_PALETTES.GLASS.forEach(c => spawnExplosion(p, c, 5, 0, 25, true)),
      setScreenShake: (d) => state.screenShakeTimer = d,
      triggerBossDeath: (b, f, w) => BossLogic.triggerBossDeath(b, f, w, stageId, currentWeapon, state, bossHelpers)
    };

    // TASER LOGIC: Continuous Burn & Hard Stun AI Bypass
    if (currentWeapon === 'TASER' && shootRequested && (infiniteAmmoEnabled || player.weaponAmmo['TASER'] > 0)) {
      if (!player.isTasing) WeaponLogic.fireWeapon(player, state, weaponHelpers, moveUp, moveDown, infiniteAmmoEnabled);
      if (player.isTasing) {
        player.taserTimer = (player.taserTimer || 0) + 1;
        if (!infiniteAmmoEnabled && state.frame % TASER_AMMO_CONSUMPTION_RATE === 0) player.weaponAmmo['TASER']--;
        player.vel.x = 0;
        const target = (enemies.find(e => e.id === player.taserTargetId) || projectiles.find(p => p.id === player.taserTargetId)) as (Enemy | Projectile | undefined);
        if (target && target.health > 0) {
          const dx = (target.pos.x + target.width/2) - (player.pos.x + player.width/2);
          const dy = (target.pos.y + target.height/2) - (player.pos.y + player.height/2);
          const dist = Math.sqrt(dx*dx + dy*dy);
          if (dist > TASER_RANGE + 100) { player.taserTargetId = null; }
          else {
            target.isTased = true; // Flag for stun lock
            if (state.frame % TASER_TICK_RATE === 0) {
              const dmg = target.type === 'boss' ? BossLogic.getBossDamage(target as Enemy, stageId, currentWeapon) : TASER_DOT_DAMAGE;
              target.health -= dmg; spawnDamageNumber(target.pos, dmg);
              if (target.health <= 0) { if (target.type === 'enemy') { const e = target as Enemy; e.isBlownAway = true; e.vel = { x: 0, y: -15 }; spawnDeathShower(e.pos, 0); speakVulgarity('taser_kill'); } player.taserTargetId = null; }
            }
            if (player.taserTimer! >= TASER_FIRE_THRESHOLD && !target.isOnFire) { target.isOnFire = true; playGunSound('ignite'); }
          }
        }
      }
    } else { player.isTasing = false; player.taserTargetId = null; player.taserTimer = 0; }

    // BOSS AI Logic with Taser Stun Bypass
    enemies.forEach(e => {
       if (e.health <= 0) return;
       if (e.isOnFire) {
         if (!e.fireTimer) e.fireTimer = 0; e.fireTimer++;
         if (e.fireTimer >= FIRE_TICK_RATE) { e.health -= FIRE_DOT_DAMAGE; spawnDamageNumber(e.pos, FIRE_DOT_DAMAGE); e.fireTimer = 0; }
         if (state.frame % 3 === 0) spawnExplosion(e.pos, '#FF4500', 1, 0, 10);
       }
       const isActuallyTased = e.isTased && player.isTasing && player.taserTargetId === e.id;
       if (e.type === 'boss' && state.arenaLocked) {
         if (!isActuallyTased && !(e.frozenTimer && e.frozenTimer > 0)) BossLogic.updateBossAI(e, stageId, player, currentWeapon, invincibilityEnabled, state, bossHelpers);
       } else if (e.type === 'enemy') {
         if (!isActuallyTased && !(e.frozenTimer && e.frozenTimer > 0)) {
           // Normal Enemy Update
           e.shootTimer++; e.pos.x += e.vel.x;
         }
       }
    });

    if (player.invincibilityTimer > 0) player.invincibilityTimer--;
    if (player.pushbackTimer > 0) { player.pushbackTimer--; player.vel.x *= 0.9; }
    player.vel.y += GRAVITY; player.pos.x += player.vel.x; player.pos.y += player.vel.y;
    player.isGrounded = false;
    blocks.forEach(b => { if (player.pos.x < b.x + b.w && player.pos.x + player.width > b.x && player.pos.y < b.y + b.h && player.pos.y + player.height > b.y) { if (b.type === 'pit') return; const ovY = Math.min(player.pos.y + player.height - b.y, b.y + b.h - player.pos.y); if (ovY < 15) { player.pos.y = b.y - player.height; player.vel.y = 0; player.isGrounded = true; } } });
    if (!state.arenaLocked) state.camera.x = Math.max(0, Math.min(BOSS_DOOR_X - CANVAS_WIDTH + 100, player.pos.x - CANVAS_WIDTH / 2));
    onPlayerUpdate(player.health, player.specialCharges, player.specialChargeTimer, player.weaponAmmo);
  }, [status, stageId, onBossDefeated, currentWeapon, respawn, invincibilityEnabled, infiniteAmmoEnabled, infinitePowerEnabled, jumpToBossEnabled, onPlayerUpdate, spawnDamageNumber, spawnDeathShower, speakVulgarity, playGunSound, spawnExplosion, spawnSteamExplosionParticles, spawnPoopExplosion, spawnPowderExplosion, spawnMethExplosion, onBossDeath, onIntroComplete, onBossEncounter, onBossTransition]);

  const drawPlayer = useCallback((ctx: CanvasRenderingContext2D, p: Player & { killSatisfactionTimer: number, bossKillSatisfactionTimer: number }) => {
    const state = gameStateRef.current; if (state.deathTimer > 0) return;
    ctx.save(); let dX = p.pos.x, dY = p.pos.y, dW = p.width, dH = p.height;
    if (p.isDucking) { dY += 28; dH -= 28; }
    const isFlicker = (p.invincibilityTimer > 0 || invincibilityEnabled) && Math.floor(state.frame / 5) % 2 === 0;
    if (!isFlicker) {
      // BEEFY MEATHEAD BODY
      ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(dX, dY, dW, dH * 0.65);
      ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(dX, dY + dH * 0.65, dW, dH * 0.35);
      // GLOWING RED EYES
      ctx.fillStyle = 'red'; const eyeSize = 4, eyeY = dY + 14;
      const lEX = dX + (p.facing === 1 ? dW - 14 : 6), rEX = dX + (p.facing === 1 ? dW - 24 : 16);
      ctx.fillRect(lEX, eyeY, eyeSize, eyeSize); ctx.fillRect(rEX, eyeY, eyeSize, eyeSize);
      // ANGRY EYEBROWS
      ctx.strokeStyle = 'black'; ctx.lineWidth = 2; ctx.beginPath();
      ctx.moveTo(lEX - 2, eyeY - 2); ctx.lineTo(lEX + 6, eyeY + 1);
      ctx.moveTo(rEX - 2, eyeY - 2); ctx.lineTo(rEX + 6, eyeY + 1); ctx.stroke();
      // FACIAL EXPRESSIONS
      if (p.killSatisfactionTimer > 0) { ctx.fillStyle = '#900'; ctx.fillRect(dX + (p.facing === 1 ? dW - 20 : 12), dY + 24, 10, 4); } // Blood smirk
      else { ctx.fillStyle = 'black'; ctx.fillRect(dX + (p.facing === 1 ? dW - 18 : 10), dY + 24, 8, 2); } // Determined line
      // MUSCLE DEFINITION LINES
      ctx.strokeStyle = 'rgba(0,0,0,0.3)'; ctx.lineWidth = 1;
      ctx.strokeRect(dX + 4, dY + dH * 0.1, dW - 8, dH * 0.4); // Deltoid/Chest
    }
    ctx.restore();
  }, [invincibilityEnabled]);

  const draw = useCallback(() => {
    const canvas = canvasRef.current; if (!canvas) return; const ctx = canvas.getContext('2d'); if (!ctx) return; const state = gameStateRef.current;
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) { ctx.fillStyle = 'black'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT); return; }
    const { player, camera, blocks, enemies, projectiles, particles, damageNumbers } = state;
    const colors = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_DARK, accent: '#fff' };
    // BACKGROUND & PARALLAX
    ctx.fillStyle = colors.bg; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.save(); ctx.translate(-camera.x * 0.5, 0); ctx.fillStyle = 'rgba(255,255,255,0.05)';
    for(let i=0; i<50; i++) ctx.fillRect((i*300) % 8000, (i*150) % 600, 2, 2);
    ctx.restore();
    // SCENE TRANSLATION
    ctx.save(); ctx.translate(-camera.x, -camera.y);
    // TEXTURED BLOCKS
    blocks.forEach(b => {
      ctx.fillStyle = colors.ground; ctx.fillRect(b.x, b.y, b.w, b.h);
      ctx.strokeStyle = colors.accent; ctx.lineWidth = 2; ctx.strokeRect(b.x, b.y, b.w, b.h);
      ctx.fillStyle = 'rgba(0,0,0,0.15)'; for(let x=b.x; x<b.x+b.w; x+=20) ctx.fillRect(x, b.y, 1, b.h);
    });
    // ENEMIES / BOSSES
    enemies.forEach(e => {
       if (e.health > 0) {
         if (e.type === 'boss') BossLogic.drawBoss(ctx, e, stageId, state.frame);
         else { ctx.fillStyle = 'purple'; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); }
       }
    });
    drawPlayer(ctx, player);
    // TASER BOLT RENDERER (TARGETED OR WASTED STREAM)
    if (player.isTasing && player.currentWeapon === 'TASER') {
      ctx.save(); ctx.strokeStyle = COLORS.TASER_BOLT; ctx.lineWidth = 3; ctx.shadowBlur = 10; ctx.shadowColor = COLORS.TASER_BOLT;
      const startX = player.pos.x + (player.facing === 1 ? player.width : 0), startY = player.pos.y + 25;
      let endX, endY;
      const target = player.taserTargetId ? ((enemies.find(en => en.id === player.taserTargetId) || projectiles.find(pr => pr.id === player.taserTargetId)) as (Enemy | Projectile | undefined)) : null;
      if (target) { endX = target.pos.x + target.width/2; endY = target.pos.y + target.height/2; } 
      else { endX = startX + (player.facing * 400); endY = startY + (Math.sin(state.frame * 0.4) * 60); }
      ctx.beginPath(); ctx.moveTo(startX, startY);
      const segs = 15; for(let i=1; i<=segs; i++) { const t = i/segs, px = startX + (endX-startX)*t + (Math.random()-0.5)*50, py = startY + (endY-startY)*t + (Math.random()-0.5)*50; ctx.lineTo(px, py); }
      ctx.stroke(); ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; ctx.stroke(); ctx.restore();
    }
    // PARTICLES / FX
    projectiles.forEach(p => { ctx.fillStyle = 'yellow'; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); });
    particles.forEach(p => { ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });
    damageNumbers.forEach(d => { ctx.fillStyle = 'white'; ctx.font = '12px "Press Start 2P"'; ctx.fillText(d.value.toString(), d.pos.x, d.pos.y); });
    ctx.restore();
  }, [status, stageId, drawPlayer]);

  useEffect(() => {
    let frameId: number; const loop = () => { update(); draw(); frameId = window.requestAnimationFrame(loop); };
    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) frameId = window.requestAnimationFrame(loop); 
    return () => window.cancelAnimationFrame(frameId);
  }, [status, update, draw]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

import React, { useRef, useEffect, useCallback } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, Vector2, Pickup, PickupType, WeaponType, DamageNumber, Volcano, SteamExplosion, VulgarityType 
} from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, GRAVITY, 
  PLAYER_SPEED, PLAYER_JUMP_FORCE, CHARGE_SPEED, CHARGE_DURATION, 
