                        en.health -= OIL_ROCKET_SPLASH_DAMAGE; spawnDamageNumber(en.pos, OIL_ROCKET_SPLASH_DAMAGE);
                        if (en.health <= 0) {
                          if (en.type === 'boss') BossLogic.triggerBossDeath(en, p.vel.x > 0 ? 1 : -1, false, stageId, currentWeapon, state, bossHelpers);
                          else { en.isBlownAway = true; en.vel = { x: (dx > 0 ? 1 : -1) * 15, y: -10 }; spawnDeathShower(en.pos, 0); spawnPickup(en.pos); speakVulgarity('oil_rocket_kill'); }
                        }
                      }
                    }
                  }
                });
              }
              if (enemy.health <= 0) { spawnDeathShower(enemy.pos, 0, 1.2); spawnPickup(enemy.pos); speakVulgarity(p.isBoulder ? 'boulder_kill' : (p.isIce ? 'shotgun_kill' : (p.isSludge ? 'sludge_kill' : (p.isOilRocket ? 'oil_rocket_kill' : 'gun_kill')))); player.killSatisfactionTimer = 60; } 
            } 
            if (p.isBoulder) { spawnRockShatter(p.pos); spawnBoulderShrapnel(p.pos, BOULDER_SHRAPNEL_COUNT, p.vel.x > 0 ? 1 : -1); } 
            if (p.isOilRocket) { spawnExplosion(p.pos, COLORS.PROJECTILE_OIL, 10); }
            if (p.isSludge) { p.health = 0; return false; } 
            return false; 
          } 
        } 
        for (const barrel of state.projectiles.filter((pr: Projectile) => pr.isMethBarrel)) if (p.pos.x < barrel.pos.x + barrel.width && p.pos.x + p.width > barrel.pos.x && p.pos.y < barrel.pos.y + barrel.height && p.pos.y + p.height > barrel.pos.y) { if (p.isDart) continue; barrel.health -= p.damage; spawnDamageNumber(barrel.pos, p.damage); if (barrel.health <= 0) barrel.health = 0; if (p.isBoulder) { spawnRockShatter(p.pos); spawnBoulderShrapnel(p.pos, BOULDER_SHRAPNEL_COUNT, p.vel.x > 0 ? 1 : -1); } if (p.isOilRocket) { 
          // IMPACT ON METH BARREL
          spawnOilSplash(p.pos); spawnExplosion(p.pos, COLORS.PROJECTILE_OIL, 10); state.screenShakeTimer = 20; 
          state.enemies.forEach((en: Enemy) => {
            if (en.health > 0 && !en.isBlownAway) {
              const dx = (en.pos.x + en.width/2) - (p.pos.x + p.width/2);
              const dy = (en.pos.y + en.height/2) - (p.pos.y + p.height/2);
              const dist = Math.sqrt(dx*dx + dy*dy);
              if (dist < OIL_ROCKET_SPLASH_RADIUS) {
                en.isOiled = true; en.oiledTimer = OILED_DURATION;
                en.health -= OIL_ROCKET_SPLASH_DAMAGE; spawnDamageNumber(en.pos, OIL_ROCKET_SPLASH_DAMAGE);
                if (en.health <= 0) {
                  if (en.type === 'boss') BossLogic.triggerBossDeath(en, p.vel.x > 0 ? 1 : -1, false, stageId, currentWeapon, state, bossHelpers);
                  else { en.isBlownAway = true; en.vel = { x: (dx > 0 ? 1 : -1) * 15, y: -10 }; spawnDeathShower(en.pos, 0); spawnPickup(en.pos); speakVulgarity('oil_rocket_kill'); }
                }
              }
            }
          });
        } if (p.isSludge) { p.health = 0; return false; } return false; } 
      } else if (player.invincibilityTimer <= 0 && p.pos.x < pInX + pInW && p.pos.x + p.width > pInX && p.pos.y < pInY + pInH && p.pos.y + p.height > pInY) { 
        if (!invincibilityEnabled) { player.health -= (p.damage / 2); if (player.health > 0) { player.invincibilityTimer = PLAYER_INVINCIBILITY_FRAMES; speakVulgarity('hurt'); player.pushbackTimer = 20; player.isCharging = false; player.isUppercutting = false; } } 
        if (p.isBoulder) spawnRockShatter(p.pos); if (p.isPoop) spawnPoopExplosion(p.pos, 25); if (p.isCocaine) spawnPowderExplosion(p.pos, 25); if (p.isMethBarrel) p.health = 0; return false; 
      } 
      return true; 
    });

    if (player.isCharging || player.isUppercutting) { 
      let pInnerX = player.pos.x, pInnerY = player.pos.y, pInnerW = player.width, pInnerH = player.height; 
      if (player.isCharging) { pInnerW += 10; pInnerH -= 10; } 
      else if (player.isUppercutting) { pInnerW -= 15; pInnerH += 40; pInnerY -= 30; pInnerX += 7.5; } 
      state.projectiles.forEach((p: Projectile) => { if (p.isMethBarrel && p.health > 0 && pInnerX < p.pos.x + p.width && pInnerX + pInnerW > p.pos.x && pInnerY < p.pos.y + p.height && pInnerY + pInnerH > p.pos.y) { const dmg = player.isUppercutting ? 100 : 50; p.health -= dmg; spawnDamageNumber(p.pos, dmg, player.isUppercutting); if (p.health <= 0) p.health = 0; else { p.vel.x = player.facing * 10; p.vel.y = -6; } } }); 
    }

    state.pickups = pickups.filter(p => { p.vel.y += GRAVITY; p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.vel.x *= 0.9; p.life--; blocks.forEach(b => { if (b.type !== 'pit' && p.pos.x < b.x + b.w && p.pos.x + p.width > b.x && p.pos.y < b.y + b.h && p.pos.y + p.height > b.y) { p.pos.y = b.y - p.height; p.vel.y = 0; } }); if (p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) { if (p.type.includes('health')) player.health = Math.min(player.maxHealth, player.health + (p.type === 'large_health' ? HEALTH_PICKUP_LARGE : HEALTH_PICKUP_SMALL)); else { const target = (player.currentWeapon === 'GUN' ? 'BOULDER' : player.currentWeapon) as WeaponType; player.weaponAmmo[target] = Math.min(MAX_AMMO[target], player.weaponAmmo[target] + MAX_AMMO[target] * (p.type === 'large_ammo' ? AMMO_PICKUP_PCT.LARGE : AMMO_PICKUP_PCT.SMALL)); } return false; } return p.life > 0; });
    state.particles = state.particles.filter(p => { if (!p.isStuck) { p.pos.x += p.vel.x; p.pos.y += p.vel.y; if (p.isGlass || (p.color && PARTICLE_PALETTES.FIRE.includes(p.color))) { p.vel.y += 0.25; if (p.pos.y > 548) { p.pos.y = 548; p.vel.y = -p.vel.y * 0.3; p.vel.x *= 0.8; } } p.life--; } return p.life > 0; });
    state.damageNumbers = damageNumbers.filter(d => { d.pos.x += d.vel.x; d.pos.y += d.vel.y; d.vel.y += 0.15; d.life--; return d.life > 0; });

    if (!state.arenaLocked && state.victoryString === "" && state.bossExplosionTimer <= 0) state.camera.x = Math.max(0, Math.min(state.doorState === 'closed' ? BOSS_DOOR_X + DOOR_WIDTH - CANVAS_WIDTH : 8000 - CANVAS_WIDTH, player.pos.x - CANVAS_WIDTH / 2 + player.width / 2));
    if (player.health <= 0 || player.pos.y > 1000) if (state.deathTimer <= 0) { state.deathTimer = 180; state.deathString = "YOU DIED"; spawnDeathShower(player.pos, player.facing, 3); speakVulgarity('death'); }

    const forced = state.shouldSyncWeapon ? 'GUN' as WeaponType : undefined; if (state.shouldSyncWeapon) state.shouldSyncWeapon = false;
    onPlayerUpdate(player.health, player.specialCharges, player.specialChargeTimer, player.weaponAmmo, forced);
  }, [status, stageId, onBossDefeated, currentWeapon, respawn, invincibilityEnabled, infiniteAmmoEnabled, infinitePowerEnabled, jumpToBossEnabled, bossTauntText, onPlayerUpdate, spawnDamageNumber, spawnDeathShower, speakVulgarity, playGunSound, spawnExplosion, spawnSteamExplosionParticles, spawnPoopExplosion, spawnPowderExplosion, spawnMethExplosion, spawnGlassShatter, onBossDeath, onIntroComplete, onBossEncounter, onBossTransition, drawPlayer]);

  useEffect(() => {
    let frameId: number; 
    const loop = () => { update(); draw(); frameId = window.requestAnimationFrame(loop); };
    const state = gameStateRef.current;
    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) { 
      if (state.frame === 0 && status === GameStatus.LEVEL_INTRO) { 
        state.frame = 1;
        createLevel(); 
      }
      frameId = window.requestAnimationFrame(loop); 
    } else { 
      state.victoryString = ""; state.postVictoryTimer = 0; state.bossExplosionTimer = 0; state.introTimer = 0; state.enemies = []; state.particles = []; state.projectiles = []; state.blocks = []; state.camera = { x: 0, y: 0 }; state.frame = 0; draw(); 
    }
    return () => window.cancelAnimationFrame(frameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

