    playerLastVulgarity: "",
    playerVulgarityTimer: 0,
    bossLastVulgarity: "",
    bossVulgarityTimer: 0,
    voiceLineCooldown: 0,
    victoryString: "",
    deathString: "",
    deathTimer: 0,
    postVictoryTimer: 0,
