        vel: { x: Math.cos(ang) * speed, y: Math.sin(ang) * speed },
        width: 6, height: 6, 
        health: 1, maxHealth: 1, type: 'projectile',
        damage: 0, owner: 'player', life: 60, isOilSplash: true
