export interface WeaponHelpers {
  addProjectile: (p: Projectile) => void;
  addParticle: (p: Particle) => void;
  playGunSound: (type: 'gun' | 'ice' | 'flame' | 'tsunami' | 'dart' | 'horn' | 'ignite' | 'barf') => void;
  spawnExplosion: (pos: Vec2, color: string, count: number, baseVelX?: number, spread?: number) => void;
  spawnDamageNumber: (pos: Vec2, value: number | string, isCritical?: boolean) => void;
  spawnGlassShatter: (pos: Vec2) => void;
  spawnDeathShower: (pos: Vector2, facing: number, multiplier?: number) => void;
  spawnPickup: (pos: Vector2) => void;
  speakVulgarity: (category: any) => void;
  setScreenShake: (duration: number) => void;
  triggerBossDeath: (boss: Enemy, facing: number, wasWeakness: boolean) => void;
}

export const fireWeapon = (player: Player, state: any, helpers: WeaponHelpers, isMoveUp: boolean, isMoveDown: boolean, infiniteAmmo: boolean) => {
  const { currentWeapon, facing, pos, width, isDucking } = player;
  const shootX = pos.x + (facing === 1 ? width : -10);
  const shootY = isDucking ? pos.y + 45 : pos.y + 25;

  if (currentWeapon === 'GUN') {
    helpers.addProjectile({ id: `p-${Date.now()}`, pos: { x: shootX, y: shootY }, vel: { x: facing * GUN_VELOCITY, y: 0 }, width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'player' });
    player.shootCooldown = GUN_COOLDOWN; helpers.playGunSound('gun');
  } else if (currentWeapon === 'BOULDER') {
    if (!state.projectiles.some((p: Projectile) => p.owner === 'player' && p.isBoulder)) {
      const vy = isMoveUp ? -18 : 0; const vx = isMoveUp ? facing * (BOULDER_SPEED * 0.9) : facing * BOULDER_SPEED;
      helpers.addProjectile({ id: `b-${Date.now()}`, pos: { x: player.pos.x + (facing === 1 ? width : -40), y: pos.y + 20 }, vel: { x: vx, y: vy }, width: 48, height: 48, health: 1, maxHealth: 1, type: 'projectile', damage: BOULDER_DAMAGE, owner: 'player', isBoulder: true });
      player.shootCooldown = BOULDER_COOLDOWN; if (!infiniteAmmo) player.weaponAmmo['BOULDER']--;
    }
  } else if (currentWeapon === 'SHOTGUN') {
    for (let i = 0; i < SHOTGUN_PELLET_COUNT; i++) {
      const angle = (i - Math.floor(SHOTGUN_PELLET_COUNT/2)) * 0.15; const speed = 11 + Math.random() * 6;
      helpers.addProjectile({ id: `pellet-${Date.now()}-${i}`, pos: { x: shootX, y: shootY }, vel: { x: Math.cos(angle) * facing * speed, y: Math.sin(angle) * speed }, width: 10, height: 10, health: 1, maxHealth: 1, type: 'projectile', damage: SHOTGUN_DAMAGE, owner: 'player', isIce: true });
    }
    player.shootCooldown = SHOTGUN_COOLDOWN; helpers.playGunSound('ice'); if (!infiniteAmmo) player.weaponAmmo['SHOTGUN']--;
  } else if (currentWeapon === 'NEEDLES') {
    helpers.addProjectile({ id: `dart-${Date.now()}`, pos: { x: shootX, y: shootY }, vel: { x: facing * 24, y: (Math.random() - 0.5) * 5 }, width: 20, height: 4, health: 1, maxHealth: 1, type: 'projectile', damage: NEEDLE_DAMAGE, owner: 'player', isDart: true });
    player.shootCooldown = NEEDLE_COOLDOWN; helpers.playGunSound('dart'); if (!infiniteAmmo) player.weaponAmmo['NEEDLES']--;
  } else if (currentWeapon === 'OIL_ROCKET') {
    helpers.addProjectile({ 
      id: `oil-rocket-${Date.now()}`, 
      pos: { x: shootX, y: shootY - 10 }, 
      vel: { x: facing * OIL_ROCKET_VELOCITY, y: 0 }, 
      width: 50, height: 18, 
      health: 1, maxHealth: 1, 
      type: 'projectile', 
      damage: OIL_ROCKET_DAMAGE, 
      owner: 'player', 
      isOilRocket: true 
    });
    player.shootCooldown = OIL_ROCKET_COOLDOWN; 
    helpers.playGunSound('gun'); 
    if (!infiniteAmmo) player.weaponAmmo['OIL_ROCKET']--;
  } else if (currentWeapon === 'FLAMETHROWER') {
    let targetAngle = 0; if (isMoveUp) targetAngle = -Math.PI / 4; else if (isMoveDown) targetAngle = Math.PI / 4; player.flameAngle = targetAngle;
    player.flameTimer = (player.flameTimer || 0) + 1;
    const rampPct = Math.min(1.0, player.flameTimer / FLAMETHROWER_RAMP_FRAMES);
    const currentRange = FLAMETHROWER_RANGE + (FLAMETHROWER_MAX_RANGE - FLAMETHROWER_RANGE) * rampPct;
    if (state.frame % 2 === 0) {
      if (!infiniteAmmo) player.weaponAmmo['FLAMETHROWER']--; helpers.playGunSound('flame');
      const spawnX = pos.x + (facing === 1 ? width - 5 : 5), spawnY = isDucking ? pos.y + 45 : pos.y + 30;
      for (let i = 0; i < 6; i++) {
        const jitter = (Math.random() - 0.5) * 0.4; const speed = (8 + Math.random() * 8) * (1 + rampPct * 1.5); const finalAngle = targetAngle + jitter;
        helpers.addParticle({ pos: { x: spawnX, y: spawnY }, vel: { x: Math.cos(finalAngle) * facing * speed + player.vel.x, y: Math.sin(finalAngle) * speed }, life: 15 + Math.random() * 20, color: PARTICLE_PALETTES.FIRE[Math.floor(PARTICLE_PALETTES.FIRE.length * Math.random())], size: 8 + Math.random() * 12 });
      }
      const checkHit = (entity: Enemy | Projectile) => {
        const entMidX = entity.pos.x + entity.width / 2, entMidY = entity.pos.y + entity.height / 2, dx = entMidX - spawnX, dy = entMidY - spawnY, distSq = dx * dx + dy * dy;
        if (distSq > currentRange * currentRange) return false;
        const angleToEntity = Math.atan2(dy, dx * facing); return Math.abs(angleToEntity - targetAngle) < 0.35;
      };
      state.projectiles.forEach((p: Projectile) => { if (p.owner === 'enemy' && checkHit(p)) { if ((p.isIce && p.width > 30) || !(p.id.startsWith('debris-') || p.id.startsWith('magma-') || (p.isBoulder && p.owner === 'enemy') || (p.isIce && p.width <= 20))) { p.health = 0; helpers.spawnExplosion({ x: p.pos.x + p.width/2, y: p.pos.y + p.height/2 }, p.isIce ? COLORS.PROJECTILE_ICE : (p.id.startsWith('magma') ? '#FF4500' : COLORS.PROJECTILE_ENEMY), Math.min(10, Math.ceil(p.width / 5)), 0, 10); } } });
      state.enemies.forEach((e: Enemy) => {
        if (e.health > 0 && !e.isBlownAway && checkHit(e)) {
          if (e.isOiled) {
            e.isOiled = false;
            e.oiledTimer = 0;
            helpers.setScreenShake(35);
            helpers.playGunSound('ignite');
            const nukePos = { x: e.pos.x + e.width / 2, y: e.pos.y + e.height / 2 };
            for (let j = 0; j < 40; j++) {
              helpers.addParticle({
                pos: { x: nukePos.x + (Math.random()-0.5)*15, y: nukePos.y - j * 1.8 },
                vel: { x: (Math.random()-0.5)*2, y: -4 - Math.random()*3 },
                life: 40 + Math.random()*25, color: j < 20 ? '#FFFFFF' : '#FFD700', size: 8 + Math.random()*10
              });
            }
            for (let j = 0; j < 120; j++) {
              const ang = Math.random() * Math.PI;
              const dist = Math.random() * 140;
              helpers.addParticle({
                pos: { x: nukePos.x + Math.cos(ang) * dist, y: nukePos.y - 85 + Math.sin(ang) * dist * 0.45 },
                vel: { x: Math.cos(ang) * 3, y: Math.sin(ang) * 1.2 - 2 },
                life: 60 + Math.random()*60, 
                color: j % 3 === 0 ? '#FFFFFF' : (j % 3 === 1 ? '#FF4500' : '#FFD700'), 
                size: 15 + Math.random()*20
              });
            }
            helpers.spawnExplosion(nukePos, '#FFFFFF', 60, 0, 110);
            helpers.spawnExplosion(nukePos, '#1A110F', 40, 0, 50); 
            state.enemies.forEach((other: Enemy) => {
               if (other.health > 0 && !other.isBlownAway) {
                 const dx = other.pos.x - e.pos.x, dy = other.pos.y - e.pos.y;
                 const dist = Math.sqrt(dx*dx + dy*dy);
                 if (dist < OIL_EXPLOSION_RADIUS) {
                   const proxDmg = OIL_EXPLOSION_DAMAGE;
                   other.health -= proxDmg;
                   helpers.spawnDamageNumber(other.pos, proxDmg, true);
                   if (other.health <= 0) {
                     if (other.type === 'boss') helpers.triggerBossDeath(other, 0, false);
                     else { other.isBlownAway = true; other.vel = { x: (dx > 0 ? 1 : -1) * 20, y: -25 }; }
                   }
                 }
               }
            });
            e.health -= OIL_EXPLOSION_DAMAGE;
            helpers.spawnDamageNumber(e.pos, OIL_EXPLOSION_DAMAGE, true);
          }
          if (e.type === 'boss') {
            if (state.arenaLocked && (!e.hitCooldown || e.hitCooldown <= 0)) {
              const dmg = BossLogic.getBossDamage(e, state.stageId, currentWeapon);
              const isW = BossLogic.checkIsWeakness(state.stageId, currentWeapon);
              e.health -= dmg; e.hitCooldown = 60; helpers.spawnDamageNumber(e.pos, dmg, isW);
              if (state.stageId === 'Artie Avalanche' && isW && e.health > 0) { const tx = e.pos.x < 7560 ? 7850 : 7250; e.vel.y = -22; e.vel.x = (tx - e.pos.x) / 50; e.bossState = 'jumping'; e.stateTimer = 60; }
              if (e.health <= 0) helpers.triggerBossDeath(e, facing, isW);
            }
          } else {
            if (!e.hitCooldown || e.hitCooldown <= 0) {
              e.health -= FLAMETHROWER_DAMAGE; helpers.spawnDamageNumber(e.pos, FLAMETHROWER_DAMAGE); e.hitCooldown = 12;
              if (e.health <= 0) { e.isBlownAway = true; e.vel = { x: (3 + rampPct * 10) * facing, y: -5 }; player.killSatisfactionTimer = 60; }
            }
          }
        }
      });
    }
  } else if (currentWeapon === 'SLUDGE') { player.barfTimer = 24; player.shootCooldown = SLUDGE_COOLDOWN; player.filthShieldTimer = FILTH_SHIELD_DURATION; if (!infiniteAmmo) player.weaponAmmo['SLUDGE']--; helpers.playGunSound('barf'); } else if (currentWeapon === 'TSUNAMI') { if (!state.tsunamiActive) { state.tsunamiActive = true; state.tsunamiDir = facing; state.tsunamiStartX = facing === 1 ? state.camera.x : state.camera.x + 800; state.tsunamiX = state.tsunamiStartX; player.shootCooldown = TSUNAMI_COOLDOWN; helpers.playGunSound('tsunami'); if (!infiniteAmmo) player.weaponAmmo['TSUNAMI']--; } } else if (currentWeapon === 'TASER') { 
    if (!player.isTasing) { 
      let nearest: (Enemy | Projectile) | null = null, minDist = TASER_RANGE; 
      const playerMidX = player.pos.x + player.width/2, playerMidY = player.pos.y + player.height/2; 
      state.enemies.forEach((e: Enemy) => { 
        if (e.health > 0 && !e.isBlownAway) { 
          const ex = e.pos.x + e.width/2, ey = e.pos.y + e.height/2; 
          if (ex > state.camera.x && ex < state.camera.x + CANVAS_WIDTH) { 
            if ((facing === 1 && ex > playerMidX) || (facing === -1 && ex < playerMidX)) { 
              const dx = ex - playerMidX, dy = ey - playerMidY, dist = Math.sqrt(dx*dx + dy*dy); 
              if (dist < minDist) { minDist = dist; nearest = e; } 
            } 
          } 
        } 
      }); 
      state.projectiles.forEach((p: Projectile) => { 
        if (p.isMethBarrel && p.health > 0) { 
          const px = p.pos.x + p.width/2, py = p.pos.y + p.height/2; 
          if (px > state.camera.x && px < state.camera.x + CANVAS_WIDTH) { 
            if ((facing === 1 && px > playerMidX) || (facing === -1 && px < playerMidX)) { 
              const dx = px - playerMidX, dy = py - playerMidY, dist = Math.sqrt(dx*dx + dy*dy); 
              if (dist < minDist) { minDist = dist; nearest = p; } 
            } 
          } 
        } 
      }); 

      // ALWAYS ACTIVATE TASER, EVEN IF MISSING TARGET (WASTED STREAM)
      player.isTasing = true; 
      player.taserTimer = 0; 
      player.taserTargetId = nearest ? (nearest as (Enemy | Projectile)).id : null; 
    } 
  }
};

export const updateWeaponMechanics = (
  player: Player,
  state: any,
  helpers: WeaponHelpers,
  inputs: { shootRequested: boolean; moveUp: boolean; moveDown: boolean; infiniteAmmo: boolean },
  stageId: string | null
) => {
  const { currentWeapon } = player;

  // 1. ROCKET STEERING
  if (currentWeapon === 'OIL_ROCKET') {
    const steeringForce = 0.5;
    state.projectiles.forEach((p: Projectile) => {
      if (p.isOilRocket && p.owner === 'player') {
        if (inputs.moveUp) p.vel.y -= steeringForce;
        if (inputs.moveDown) p.vel.y += steeringForce;
        p.vel.y *= 0.96; 
      }
    });
  }

  // 2. SLUDGE BARF
  if (player.barfTimer && player.barfTimer > 0) {
    player.barfTimer--;
    if (player.barfTimer % 2 === 0) { 
       const shootX = player.pos.x + (player.facing === 1 ? player.width : -10);
       const shootY = player.isDucking ? player.pos.y + 45 : player.pos.y + 25;
       helpers.addProjectile({ 
         id: `sludge-part-${Date.now()}-${player.barfTimer}`, 
         pos: { x: shootX, y: shootY }, 
         vel: { 
           x: player.facing * (11 + Math.random() * 8), 
           y: -3 - Math.random() * 9 
         }, 
         width: SLUDGE_PROJ_SIZE_MIN + Math.random() * SLUDGE_PROJ_SIZE_RAND, 
         height: SLUDGE_PROJ_SIZE_MIN + Math.random() * SLUDGE_PROJ_SIZE_RAND, 
         health: 1, maxHealth: 1, 
         type: 'projectile', damage: SLUDGE_DAMAGE, owner: 'player', isSludge: true, life: 150 
       });
    }
  }

  // 3. TSUNAMI
  if (state.tsunamiActive) {
    state.tsunamiX += TSUNAMI_WAVE_SPEED * state.tsunamiDir; 
    const dist = Math.abs(state.tsunamiX - state.tsunamiStartX);
    const totalDist = CANVAS_WIDTH * 1.5;
    const progress = dist / totalDist;
    const tsunamiTopY = Math.pow(Math.min(1.0, dist / (CANVAS_WIDTH * 1.25)), 0.6) * 560;
    const waveHeight = 600 - tsunamiTopY;
    const bendMult = 120;
    const dir = state.tsunamiDir;
    const density = 35;

    for (let i = 0; i <= density; i++) {
      const yPct = i / density;
      const yPos = tsunamiTopY + (yPct * waveHeight);
      const normalizedY = (yPct - 0.5) * 2;
      const xOffset = (normalizedY * normalizedY) * bendMult * dir;
      const px = state.tsunamiX + xOffset;
      const py = yPos;
      helpers.addParticle({ pos: { x: px + (Math.random() - 0.5) * 40, y: py + (Math.random() - 0.5) * 15 }, vel: { x: (TSUNAMI_WAVE_SPEED * 0.4 + Math.random() * 8) * dir, y: (Math.random() - 0.5) * 4 }, life: 12 + Math.random() * 18, color: PARTICLE_PALETTES.WATER[Math.floor(PARTICLE_PALETTES.WATER.length * Math.random())], size: 8 + Math.random() * 12, isWater: true });
      if (i < 3 && Math.random() > 0.4) helpers.addParticle({ pos: { x: px, y: py }, vel: { x: (TSUNAMI_WAVE_SPEED * 0.9) * dir, y: (Math.random() - 0.5) * 10 }, life: 20 + Math.random() * 10, color: '#FFFFFF', size: 5 + Math.random() * 5, isWater: true });
    }

    if (stageId === 'Victor Volcano') state.bossVolcanoes = state.bossVolcanoes.filter((v: any) => { if (Math.abs(v.pos.x - state.tsunamiX) < 60) { state.bossSteamExplosions.push({ pos: { ...v.pos }, life: 45, radius: 100 }); (helpers as any).spawnSteamExplosionParticles(v.pos, 40); helpers.setScreenShake(12); return false; } return true; });

    state.projectiles.forEach((p: Projectile) => { 
      if (p.isMethBarrel && p.health > 0) { 
        if (Math.abs(p.pos.x + p.width / 2 - state.tsunamiX) < 120) { 
          p.vel = { x: state.tsunamiDir * 20, y: -10 }; 
          p.rotation = (p.rotation || 0) + 0.5; 
          p.health -= TSUNAMI_DAMAGE_BOSS; 
          helpers.spawnDamageNumber(p.pos, TSUNAMI_DAMAGE_BOSS); 
        } 
      } 
    });

    state.enemies.forEach((e: Enemy) => { 
      if (e.health > 0 && !e.isBlownAway) { 
        const ebY = e.pos.y + e.height; 
        if (Math.abs(e.pos.x + e.width / 2 - state.tsunamiX) < 120 && ebY > tsunamiTopY) { 
          if (e.type === 'boss') { 
            if (state.arenaLocked && (!e.hitCooldown || e.hitCooldown <= 0)) { 
              const isW = BossLogic.checkIsWeakness(stageId, currentWeapon); 
              const dmg = isW ? TSUNAMI_DAMAGE_WEAKNESS : TSUNAMI_DAMAGE_BOSS; 
              e.health -= dmg; 
              e.hitCooldown = ENEMY_HIT_COOLDOWN; 
              helpers.spawnDamageNumber(e.pos, dmg, isW); 
              if (e.health <= 0) helpers.triggerBossDeath(e, state.tsunamiDir, isW); 
            } 
          } else { 
            e.health = 0; 
            e.isBlownAway = true; 
            e.vel = { x: state.tsunamiDir * 20, y: -10 }; 
            helpers.spawnDeathShower(e.pos, state.tsunamiDir); 
            helpers.spawnPickup(e.pos); 
            helpers.speakVulgarity('tsunami_kill'); 
            player.killSatisfactionTimer = 60; 
          } 
        } 
      } 
    });
    if (progress >= 1.0) state.tsunamiActive = false;
  }

  // 4. TASER
  const hasAmmo = (wpn: WeaponType) => wpn === 'GUN' || player.weaponAmmo[wpn] >= 1;
  if (currentWeapon === 'TASER' && inputs.shootRequested && (hasAmmo('TASER') || inputs.infiniteAmmo)) { 
    if (!player.isTasing) fireWeapon(player, state, helpers, inputs.moveUp, inputs.moveDown, inputs.infiniteAmmo); 
    if (player.isTasing) { 
      player.taserTimer = (player.taserTimer || 0) + 1; 
      if (!inputs.infiniteAmmo && state.frame % TASER_AMMO_CONSUMPTION_RATE === 0) player.weaponAmmo['TASER'] -= 1; 
      player.vel.x = 0; 
      if (player.weaponAmmo['TASER'] <= 0) { player.isTasing = false; player.taserTargetId = null; } 
      const target = (state.enemies.find((e: Enemy) => e.id === player.taserTargetId) || state.projectiles.find((p: Projectile) => p.id === player.taserTargetId)) as (Enemy | Projectile | undefined); 

      if (target && (target.pos.x + target.width < state.camera.x || target.pos.x > state.camera.x + CANVAS_WIDTH || target.health <= 0)) { 
         player.taserTargetId = null; 
      } 

      if (target && target.health > 0) { 
        const dx = (target.pos.x + target.width/2) - (player.pos.x + player.width/2); 
        const dy = (target.pos.y + target.height/2) - (player.pos.y + player.height/2); 
        const dist = Math.sqrt(dx*dx + dy*dy); 
        if (dist > TASER_RANGE + 100) { player.taserTargetId = null; } 
        else { 
          if (target.type === 'boss') { 
            const b = target as Enemy; 
            if (!b.hitCooldown || b.hitCooldown <= 0) { 
              const dmg = BossLogic.getBossDamage(b, stageId, currentWeapon); 
              const isW = BossLogic.checkIsWeakness(stageId, currentWeapon); 
              b.health -= dmg; b.hitCooldown = ENEMY_HIT_COOLDOWN; helpers.spawnDamageNumber(b.pos, dmg, isW); 
              if (b.health <= 0) helpers.triggerBossDeath(b, player.facing, isW); 
            } 
          } else { 
            target.isTased = true; 
            if (state.frame % TASER_TICK_RATE === 0) { 
              target.health -= TASER_DOT_DAMAGE; helpers.spawnDamageNumber(target.pos, TASER_DOT_DAMAGE); 
              if (target.health <= 0) { 
                if (target.type === 'enemy') { 
                  const e = target as Enemy; e.isBlownAway = true; e.vel = { x: (Math.random()-0.5)*10, y: -15 }; helpers.spawnDeathShower(e.pos, 0); helpers.spawnPickup(e.pos); helpers.speakVulgarity('taser_kill'); 
                } 
                player.taserTargetId = null; 
              } 
            } 
            if (player.taserTimer! >= TASER_FIRE_THRESHOLD && !target.isOnFire) { target.isOnFire = true; helpers.playGunSound('ignite'); } 
          } 
        } 
      } 
    } 
  } else { player.isTasing = false; player.taserTargetId = null; player.taserTimer = 0; }
};

import { 
  Enemy, Projectile, Vector2, WeaponType, Player, Volcano, SteamExplosion, VulgarityType 
} from './types';
import { 
  BOSS_DIALOGUE, BULLET_DAMAGE, BOULDER_SPEED, BOSS_DOOR_X, 
  HECTOR_PULL_STRENGTH, GRAVITY, COLORS, PARTICLE_PALETTES, 
  BOSS_CHARGE_DAMAGE, BOSS_UPPERCUT_DAMAGE, ENEMY_UPPERCUT_DAMAGE,
  DALE_TRUCK_SPEED, METH_BARREL_DAMAGE, HECTOR_PULL_STRENGTH_ULT,
  TASER_BOSS_DAMAGE_REDUCTION, DALE_TRUCK_DAMAGE, DALE_PUSHBACK_VEL,
  BOSS_VULGARITY_DURATION, ERNIE_STOMP_VIBRATION_DURATION, ENEMY_HIT_COOLDOWN
} from './constants';

export interface BossHelpers {
  spawnDamageNumber: (pos: Vector2, value: number | string, isCritical?: boolean) => void;
  spawnDeathShower: (pos: Vector2, facing: number, multiplier?: number, isBossDeath?: boolean, spreadOverride?: number) => void;
  onBossDeath: () => void;
  speakVulgarity: (category: VulgarityType) => void;
  playGunSound: (type?: 'gun' | 'ice' | 'flame' | 'tsunami' | 'dart' | 'horn' | 'ignite' | 'barf') => void;
  spawnExplosion: (pos: Vector2, color: string, count: number, baseVelX?: number, spread?: number, isGlass?: boolean, isBossGore?: boolean) => void;
  spawnSteamExplosionParticles: (pos: Vector2, count?: number) => void;
  spawnPoopExplosion: (pos: Vector2, count?: number) => void;
  spawnPowderExplosion: (pos: Vector2, count?: number) => void;
  spawnMethExplosion: (pos: Vector2, count?: number) => void;
  spawnGlassShatter: (pos: Vector2) => void;
  setBossVulgarity: (text: string, duration: number) => void;
  setScreenShake: (duration: number) => void;
  setErnieVibration: (duration: number) => void;
  setPlayerStun: (duration: number) => void;
  addProjectile: (p: Projectile) => void;
  addVolcano: (v: Volcano) => void;
  clearVolcanoes: () => void;
  addVolcanoTelegraph: (v: Volcano) => void;
  clearVolcanoTelegraphs: () => void;
  addPoopTelegraph: (t: { pos: Vector2, life: number, spawnX: number }) => void;
  clearPoopTelegraphs: () => void;
  setVictorWallSide: (side: number) => void;
  setTsunamiActive: (active: boolean) => void;
}

export const speakAsBoss = (bossId: string, text: string, helpers: BossHelpers) => {
  if ('speechSynthesis' in window) {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    switch (bossId) {
      case 'Artie Avalanche': utterance.pitch = 1.6; utterance.rate = 0.85; break;
      case 'Victor Volcano': utterance.pitch = 0.7; utterance.rate = 0.85; break;
      case 'Ernie Earthquake': utterance.pitch = 0.1; utterance.rate = 0.55; break;
      case 'Hector Hurricane': utterance.pitch = 1.2; utterance.rate = 1.5; break;
      case 'Drug Trade Dale': utterance.pitch = 1.8; utterance.rate = 1.1; break;
      default: utterance.pitch = 1.0; utterance.rate = 1.0;
    }
    utterance.volume = 1.0;
    window.speechSynthesis.speak(utterance);
    helpers.setBossVulgarity(text, BOSS_VULGARITY_DURATION);
  }
};

export const checkIsWeakness = (stageId: string | null, currentWeapon: WeaponType, p?: Partial<Projectile>) => {
  if (!p) {
    if (stageId === 'Artie Avalanche' && currentWeapon === 'FLAMETHROWER') return true;
    if (stageId === 'Victor Volcano' && currentWeapon === 'TSUNAMI') return true;
    if (stageId === 'Ernie Earthquake' && currentWeapon === 'SHOTGUN') return true;
    if (stageId === 'Hector Hurricane' && currentWeapon === 'BOULDER') return true;
    if (stageId === 'Drug Trade Dale' && currentWeapon === 'SLUDGE') return true;
    return false;
  }
  if (stageId === 'Hector Hurricane' && p.isBoulder) return true;
  if (stageId === 'Victor Volcano' && p.isTsunami) return true;
  if (stageId === 'Artie Avalanche' && (p.owner === 'player' && currentWeapon === 'FLAMETHROWER')) return true;
  if (stageId === 'Ernie Earthquake' && p.isIce) return true;
  if (stageId === 'Drug Trade Dale' && p.isSludge) return true;
  return false;
};

export const getBossDamage = (boss: Enemy, stageId: string | null, currentWeapon: WeaponType, p?: Partial<Projectile>) => {
  if (stageId === 'Victor Volcano' && (p?.isTsunami || (!p && currentWeapon === 'TSUNAMI'))) return 150;

  if (currentWeapon === 'SLUDGE' || (p && p.isSludge)) {
    if (stageId === 'Drug Trade Dale') return 100;
    return 25;
  }

  const isWeak = checkIsWeakness(stageId, currentWeapon, p);
  if (isWeak) return 100;
  if (currentWeapon === 'TASER') return Math.floor(BULLET_DAMAGE * TASER_BOSS_DAMAGE_REDUCTION);
  return BULLET_DAMAGE;
};

export const triggerBossDeath = (boss: Enemy, playerFacing: number, wasWeakness: boolean, stageId: string | null, currentWeapon: WeaponType, state: any, helpers: BossHelpers) => {
  if (state.bossExplosionTimer > 0) return;
  const pos = { x: boss.pos.x + boss.width / 2, y: boss.pos.y + boss.height / 2 };
  if (stageId && BOSS_DIALOGUE.THRESHOLDS[stageId]) speakAsBoss(stageId, BOSS_DIALOGUE.THRESHOLDS[stageId][0], helpers);
  state.bossVolcanoes = []; state.bossVolcanoTelegraphs = []; state.bossPoopTelegraphs = []; state.bossSteamExplosions = []; state.ernieVibrationTimer = 0; state.projectiles = []; state.tsunamiActive = false; state.tsunamiX = -1;
  if (wasWeakness) { state.bossExplosionTimer = 180; state.bossExplosionPos = pos; helpers.spawnDeathShower(state.bossExplosionPos, playerFacing, 35, true, 120); } else { helpers.spawnDeathShower(pos, playerFacing, 6, true, 45); helpers.onBossDeath(); state.victoryString = "V"; state.postVictoryTimer = 0; }
  state.player.killSatisfactionTimer = 0; state.player.bossKillSatisfactionTimer = 240; state.arenaLocked = false;
  let cat: VulgarityType = 'gun_kill'; if (currentWeapon === 'BOULDER') cat = 'boulder_kill'; else if (currentWeapon === 'SHOTGUN') cat = 'shotgun_kill'; else if (currentWeapon === 'FLAMETHROWER') cat = 'flamethrower_kill'; else if (currentWeapon === 'TSUNAMI') cat = 'tsunami_kill'; else if (currentWeapon === 'SLUDGE') cat = 'sludge_kill'; helpers.speakVulgarity(cat);
};

export const updateBossHazards = (state: any, player: Player, invincibilityEnabled: boolean, helpers: BossHelpers) => {
  state.bossSteamExplosions = state.bossSteamExplosions.filter((exp: any) => { 
    exp.life--; 
    const pMidX = player.pos.x + player.width/2;
    const pMidY = player.pos.y + player.height/2;
    const dx = pMidX - exp.pos.x;
    const dy = pMidY - exp.pos.y; 
    if (dx*dx + dy*dy < exp.radius * exp.radius && player.invincibilityTimer <= 0 && !invincibilityEnabled) { 
      player.health -= 12; 
      if (player.health > 0) { 
        player.invincibilityTimer = 45; 
        player.pushbackTimer = 20; 
        player.vel.x = dx > 0 ? 18 : -18; 
        player.vel.y = -6; 
        helpers.speakVulgarity('hurt'); 
      } 
    } 
    if (state.frame % 3 === 0) helpers.spawnSteamExplosionParticles(exp.pos, 6); 
    return exp.life > 0; 
  });

  state.bossVolcanoes = state.bossVolcanoes.filter((v: any) => { 
    v.life--; 
    if (state.frame % 12 === 0) { 
      const magVelX = v.type === 'wall' ? (v.pos.x < 7600 ? 9 : -9) : (Math.random()-0.5)*4;
      const magVelY = v.type === 'ground' ? -9 : (Math.random()-0.5)*7; 
      helpers.addProjectile({ id: `magma-${Date.now()}`, pos: { x: v.pos.x, y: v.pos.y }, vel: { x: magVelX, y: magVelY }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 45, owner: 'enemy' }); 
    } 
    return v.life > 0; 
  });
};

export const updateBossAI = (boss: Enemy, stageId: string | null, player: Player, currentWeapon: WeaponType, invincibilityEnabled: boolean, state: any, helpers: BossHelpers) => {
  boss.stateTimer = (boss.stateTimer || 0) - 1;
  const dirToPlayer = player.pos.x + player.width/2 < boss.pos.x + boss.width/2 ? -1 : 1;
  const healthPct = (boss.health / boss.maxHealth) * 100;
  if (stageId && BOSS_DIALOGUE.THRESHOLDS[stageId]) { if (healthPct <= 75 && !boss.said75) { boss.said75 = true; speakAsBoss(stageId, BOSS_DIALOGUE.THRESHOLDS[stageId][75], helpers); } if (healthPct <= 50 && !boss.said50) { boss.said50 = true; speakAsBoss(stageId, BOSS_DIALOGUE.THRESHOLDS[stageId][50], helpers); } if (healthPct <= 25 && !boss.said25) { boss.said25 = true; speakAsBoss(stageId, BOSS_DIALOGUE.THRESHOLDS[stageId][25], helpers); } }
  if (stageId === 'Drug Trade Dale') handleDaleAI(boss, player, invincibilityEnabled, state, helpers); else if (stageId === 'Hector Hurricane') handleHectorAI(boss, player, invincibilityEnabled, state, helpers); else if (stageId === 'Artie Avalanche') handleArtieAI(boss, player, state, helpers); else if (stageId === 'Ernie Earthquake') handleErnieAI(boss, player, state, helpers); else if (stageId === 'Victor Volcano') handleVictorAI(boss, player, healthPct, state, helpers);
  if (boss.bossState !== 'stunned_drop' && stageId !== 'Drug Trade Dale') { const gravityMult = (stageId === 'Artie Avalanche' || (stageId === 'Ernie Earthquake' && !boss.isGroundedBoss)) ? 0.5 : 1.0; boss.vel.y += GRAVITY * gravityMult; boss.pos.x += boss.vel.x; const prevY = boss.pos.y; boss.pos.y += boss.vel.y; boss.pos.x = Math.max(BOSS_DOOR_X + 10, Math.min(8000 - boss.width - 10, boss.pos.x)); if (boss.pos.y < 100) { boss.pos.y = 100; boss.vel.y = 0; } let bossGroundedOnBlock = false; if (boss.vel.y >= 0) { for (const b of state.blocks) { if (b.type === 'platform' || b.type === 'ground') { if (boss.pos.x < b.x + b.w && boss.pos.x + boss.width > b.x && prevY + boss.height <= b.y && boss.pos.y + boss.height >= b.y) { boss.pos.y = b.y - boss.height; if (stageId === 'Ernie Earthquake' && prevY < b.y - boss.height) { helpers.setScreenShake(30); helpers.setErnieVibration(ERNIE_STOMP_VIBRATION_DURATION); } boss.vel.y = 0; boss.vel.x = 0; boss.isGroundedBoss = true; bossGroundedOnBlock = true; if (boss.bossState === 'jumping' && stageId !== 'Victor Volcano' && stageId !== 'Hector Hurricane') boss.bossState = 'idle'; break; } } } } if (!bossGroundedOnBlock) { if (boss.pos.y > 470) { boss.pos.y = 470; if (prevY < 470 && boss.vel.y > 0 && stageId === 'Ernie Earthquake') { helpers.setScreenShake(30); helpers.setErnieVibration(ERNIE_STOMP_VIBRATION_DURATION); helpers.addProjectile({ id: `b-ernie-land-${Date.now()}`, pos: { x: boss.pos.x + boss.width/2, y: boss.pos.y + 20 }, vel: { x: dirToPlayer * (BOULDER_SPEED + 1), y: 0 }, width: 48, height: 48, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isBoulder: true }); } boss.vel.y = 0; boss.vel.x = 0; boss.isGroundedBoss = true; if (boss.bossState === 'jumping' && stageId !== 'Victor Volcano' && stageId !== 'Hector Hurricane') boss.bossState = 'idle'; } else boss.isGroundedBoss = false; } } else if (boss.bossState === 'stunned_drop') { boss.vel.y += GRAVITY * 1.5; boss.pos.y += boss.vel.y; if (boss.pos.y > 470) { boss.pos.y = 470; boss.vel.y = 0; boss.isGroundedBoss = true; if (boss.stateTimer! > 30) boss.stateTimer = 30; } }
};

const handleDaleAI = (boss: Enemy, player: Player, invincibilityEnabled: boolean, state: any, helpers: BossHelpers) => {
  if (boss.bossState === 'idle' && boss.stateTimer! <= 0) { boss.bossState = 'truck_incoming'; boss.stateTimer = 120; boss.truckX = BOSS_DOOR_X - 600; boss.truckActive = false; helpers.playGunSound('horn'); } else if (boss.bossState === 'truck_incoming') { if (boss.stateTimer! < 40) { boss.truckActive = true; boss.truckX! += DALE_TRUCK_SPEED; } const tx = boss.truckX!, ty = 400, tw = 350, th = 150; if (boss.truckActive && player.pos.x < tx + tw && player.pos.x + player.width > tx && player.pos.y < ty + th && player.pos.y + player.height > ty && player.invincibilityTimer <= 0 && !invincibilityEnabled) { player.health -= DALE_TRUCK_DAMAGE; player.invincibilityTimer = 60; player.pushbackTimer = 40; player.vel = DALE_PUSHBACK_VEL; helpers.speakVulgarity('hurt'); } state.projectiles.forEach((p: Projectile) => { if (boss.truckActive && p.isMethBarrel && p.health > 0) { if (p.pos.x < tx + tw && p.pos.x + p.width > tx && p.pos.y < ty + th && p.pos.y + p.height > ty) p.health = -1; } }); if (boss.truckX! > 8200) { boss.truckActive = false; boss.bossState = 'using_shipment'; const drugs: ('cocaine' | 'speed' | 'meth')[] = ['cocaine', 'speed', 'meth']; boss.shipmentType = drugs[Math.floor(Math.random() * drugs.length)]; boss.shipmentCount = boss.shipmentType === 'cocaine' ? 10 : (boss.shipmentType === 'meth' ? 5 : 1); boss.stateTimer = 30; } } else if (boss.bossState === 'using_shipment') { if (boss.stateTimer! <= 0) { if (boss.shipmentType === 'cocaine') { const rangeRoll = Math.random(); let vx, vy; if (rangeRoll < 0.3) { vx = -2 - Math.random() * 3; vy = -18 - Math.random() * 6; } else if (rangeRoll < 0.75) { vx = -10 - Math.random() * 5; vy = -14 - Math.random() * 5; } else { vx = -20 - Math.random() * 8; vy = -8 - Math.random() * 4; } helpers.addProjectile({ id: `coke-${Date.now()}`, pos: { x: boss.pos.x, y: boss.pos.y + 20 }, vel: { x: vx, y: vy }, width: 25, height: 25, health: 1, maxHealth: 1, type: 'projectile', damage: 30, owner: 'enemy', isCocaine: true }); boss.shipmentCount!--; boss.stateTimer = 20; if (boss.shipmentCount! <= 0) { boss.bossState = 'idle'; boss.stateTimer = 80; } } else if (boss.shipmentType === 'meth') { helpers.addProjectile({ id: `meth-${Date.now()}`, pos: { x: boss.pos.x, y: boss.pos.y }, vel: { x: -4 - Math.random() * 3, y: -12 }, width: 40, height: 50, health: 100, maxHealth: 100, type: 'projectile', damage: METH_BARREL_DAMAGE, owner: 'enemy', isMethBarrel: true, bounces: 15 }); boss.shipmentCount!--; boss.stateTimer = 45; if (boss.shipmentCount! <= 0) { boss.bossState = 'idle'; boss.stateTimer = 100; } } else if (boss.shipmentType === 'speed') { boss.bossState = 'speed_dash'; boss.dashCount = 8; boss.vel.x = -25; boss.stateTimer = 0; helpers.playGunSound('ice'); } } } else if (boss.bossState === 'speed_dash') { boss.pos.x += boss.vel.x; if (boss.pos.x < BOSS_DOOR_X + 20 || boss.pos.x + boss.width > 7980) { boss.vel.x *= -1; boss.dashCount!--; helpers.setScreenShake(10); if (boss.dashCount! <= 0) { boss.pos.x = 7840; boss.vel.x = 0; boss.bossState = 'idle'; boss.stateTimer = 150; } } }
};

const handleHectorAI = (boss: Enemy, player: Player, invincibilityEnabled: boolean, state: any, helpers: BossHelpers) => {
  if (boss.bossState === 'hurricane') { 
    const forceDir = (boss.pos.x + boss.width/2 - (player.pos.x + player.width/2)) > 0 ? 1 : -1; 
    state.totalPullForceX += forceDir * HECTOR_PULL_STRENGTH_ULT; 
    state.projectiles.forEach((p: Projectile) => { 
      if (p.owner === 'player' && p.isBoulder) { 
        const pullDir = (boss.pos.x + boss.width/2 - (p.pos.x + p.width/2)) > 0 ? 1 : -1; 
        p.vel.x += pullDir * 1.5; 
      } 
      if (p.isPoop) {
        p.vel.x += forceDir * HECTOR_PULL_STRENGTH; 
        // DESTROY POOP NEAR STORM EYE
        const dx = (p.pos.x + p.width/2) - (boss.pos.x + boss.width/2);
        const dy = (p.pos.y + p.height/2) - (boss.pos.y + boss.height/2);
        if (Math.sqrt(dx*dx + dy*dy) < 180) {
          p.health = 0; 
          helpers.spawnPoopExplosion(p.pos, 15);
        }
      }
    }); 
    state.bossPoopTelegraphs = state.bossPoopTelegraphs.filter((t: any) => { 
      t.life--; 
      if (t.life <= 0) { 
        const spawnLeft = t.spawnX === BOSS_DOOR_X; 
        const velX = spawnLeft ? 12 : -12; 
        helpers.addProjectile({ id: `poop-${Date.now()}`, pos: { x: t.spawnX, y: t.pos.y }, vel: { x: velX, y: (Math.random()-0.5)*3 }, width: 45, height: 25, health: 1, maxHealth: 1, type: 'projectile', damage: 12, owner: 'enemy', isPoop: true, spawnX: t.spawnX }); 
        return false; 
      } 
      return true; 
    }); 
    if (state.frame % 90 === 0) { 
      const spawnLeft = forceDir > 0, spawnX = spawnLeft ? BOSS_DOOR_X : 8000; 
      const r = Math.random(); 
      let spawnY; 
      if (r < 0.33) spawnY = 510; else if (r < 0.66) spawnY = 498; else spawnY = 440; 
      helpers.addPoopTelegraph({ pos: { x: spawnX, y: spawnY }, life: 60, spawnX: spawnX }); 
    } 
    if (Math.abs((boss.pos.x + boss.width/2) - (player.pos.x + player.width/2)) < 300 && player.invincibilityTimer <= 0 && !invincibilityEnabled) { 
      player.health -= 4; 
      if (player.health > 0) { 
        player.invincibilityTimer = 25; 
        player.pushbackTimer = 2; 
        helpers.speakVulgarity('hurt'); 
      } 
    } 
    if (boss.stateTimer! <= 0) { boss.bossState = 'idle'; boss.stateTimer = 40; helpers.clearPoopTelegraphs(); } 
  } else if (boss.bossState === 'jumping') { 
    if (boss.isGroundedBoss) { boss.bossState = 'hurricane'; boss.stateTimer = 300; boss.vel.x = 0; } 
  } else if (boss.stateTimer! <= 0) { boss.bossState = 'jumping'; boss.vel.y = -22 - Math.random() * 4; const targetX = boss.pos.x > 7600 ? 7300 : 7900; boss.vel.x = (targetX - boss.pos.x) * 0.035; }
};

const handleArtieAI = (boss: Enemy, player: Player, state: any, helpers: BossHelpers) => {
  if (boss.shootTimer > 0) boss.shootTimer--; if (boss.isGroundedBoss && Math.abs(boss.vel.x) < 0.5) boss.sideTimer = (boss.sideTimer || 0) + 1; else boss.sideTimer = 0; if ((boss.stateTimer! <= 0 || (boss.sideTimer || 0) > 175) && boss.isGroundedBoss) { const r = Math.random(); const mustMove = (boss.sideTimer || 0) > 120; if (r < 0.35 || (mustMove && r < 0.6)) { boss.vel.y = -13 - Math.random() * 3; boss.vel.x = (player.pos.x < boss.pos.x ? -1 : 1) * (4 + Math.random() * 2); boss.stateTimer = 70; boss.bossState = 'jumping'; boss.sideTimer = 0; } else if (r < 0.70 && boss.shootTimer <= 0 && !mustMove) { const targetDir = player.pos.x < (boss.pos.x + boss.width/2) ? -1 : 1, projW = 60; helpers.addProjectile({ id: `ice-big-${Date.now()}`, pos: { x: targetDir === 1 ? boss.pos.x + boss.width + 5 : boss.pos.x - projW - 5, y: boss.pos.y + 10 }, vel: { x: targetDir * 11, y: 0 }, width: projW, height: 60, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isIce: true }); boss.shootTimer = 60; boss.stateTimer = 80; boss.bossState = 'attacking'; } else { boss.vel.x = (player.pos.x + player.width/2 < boss.pos.x + boss.width/2 ? -1 : 1) * 7.5; boss.stateTimer = 65; boss.bossState = 'attacking'; boss.sideTimer = 0; } } if (boss.bossState === 'jumping' && !boss.isGroundedBoss && boss.shootTimer <= 0) { if (Math.abs(boss.vel.y) < 2 && boss.stateTimer! > 20 && Math.random() < 0.08) { const targetDir = player.pos.x < (boss.pos.x + boss.width/2) ? -1 : 1, projW = 60; helpers.addProjectile({ id: `ice-big-air-${Date.now()}`, pos: { x: targetDir === 1 ? boss.pos.x + boss.width + 5 : boss.pos.x - projW - 5, y: boss.pos.y + 10 }, vel: { x: targetDir * 11, y: 0 }, width: projW, height: 60, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isIce: true }); boss.shootTimer = 60; boss.stateTimer = 50; } } if (boss.isGroundedBoss) boss.vel.x *= 0.95;
};

export const handleErnieAI = (boss: Enemy, player: Player, state: any, helpers: BossHelpers) => {
  if (boss.bossState === 'stunned_drop') { if (boss.isGroundedBoss && boss.stateTimer! <= 0) { boss.bossState = 'idle'; boss.stateTimer = 40; boss.rotation = 0; } } else if (boss.stateTimer! <= 0) { const dirToPlayer = player.pos.x + player.width/2 < boss.pos.x + boss.width/2 ? -1 : 1; boss.vel.y = -12; boss.vel.x = (player.pos.x - boss.pos.x) * 0.03; boss.stateTimer = 180; helpers.addProjectile({ id: `b-ernie-jump-${Date.now()}`, pos: { x: boss.pos.x + boss.width/2, y: boss.pos.y + 20 }, vel: { x: dirToPlayer * (BOULDER_SPEED + 1), y: 0 }, width: 48, height: 48, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isBoulder: true }); }
};

const handleVictorAI = (boss: Enemy, player: Player, healthPct: number, state: any, helpers: BossHelpers) => {
  const victorMidX = boss.pos.x + boss.width / 2;
  if (boss.bossState === 'attacking') { boss.vel.x = 0; if (state.bossVolcanoes.length === 0 && boss.stateTimer! <= 0) { boss.bossState = 'idle'; boss.stateTimer = 40; } } else if (boss.bossState === 'telegraphing') { boss.vel.x = 0; if (boss.stateTimer! <= 0) { boss.bossState = 'attacking'; boss.stateTimer = 180; state.bossVolcanoTelegraphs.forEach((t: Volcano) => helpers.addVolcano({ pos: t.pos, life: 180, type: t.type })); helpers.clearVolcanoTelegraphs(); } } else if (boss.bossState === 'jumping') { if (boss.isGroundedBoss) { boss.bossState = 'telegraphing'; boss.stateTimer = 60; helpers.clearVolcanoTelegraphs(); const newSide = (state.victorWallSide + 1) % 2; helpers.setVictorWallSide(newSide); helpers.addVolcanoTelegraph({ pos: { x: newSide === 0 ? BOSS_DOOR_X : 8000, y: 250 + Math.random() * 200 }, life: 60, type: 'wall' }); const groundCount = healthPct > 50 ? 1 : 2; const groundXs: number[] = []; for(let i=0; i<groundCount; i++) { let tx = 0, attempts = 0, valid = false; while(!valid && attempts < 20) { tx = BOSS_DOOR_X + 150 + Math.random() * 500; valid = Math.abs(tx - victorMidX) > 150; if (valid) for (const existingX of groundXs) if (Math.abs(tx - existingX) < 100) { valid = false; break; } attempts++; } groundXs.push(tx); helpers.addVolcanoTelegraph({ pos: { x: Math.max(BOSS_DOOR_X + 50, Math.min(7900, tx)), y: 550 }, life: 60, type: 'ground' }); } } } else if (boss.stateTimer! <= 0) { boss.vel.y = -20 - Math.random() * 5; const platforms = state.blocks.filter((b: any) => b.type === 'platform' && b.x > BOSS_DOOR_X); if (platforms.length > 0) { const targetPlate = platforms[Math.floor(Math.random() * platforms.length)]; boss.vel.x = (targetPlate.x + targetPlate.w / 2 - victorMidX) * 0.04; } else { boss.vel.x = (player.pos.x < boss.pos.x ? -1 : 1) * 4 + (Math.random()-0.5)*2; } boss.bossState = 'jumping'; boss.stateTimer = 60; } if (boss.isGroundedBoss) boss.vel.x *= 0.95;
};

export const drawBoss = (ctx: CanvasRenderingContext2D, e: Enemy, id: string | null, frame: number) => {
  const { pos, width, height } = e; ctx.save(); ctx.translate(pos.x, pos.y);

  // Body does NOT spin during hurricane
  const shouldSpin = e.rotation && !(id === 'Hector Hurricane' && e.bossState === 'hurricane');
  if (shouldSpin) { 
    ctx.translate(width / 2, height / 2); ctx.rotate(e.rotation!); ctx.translate(-width / 2, -height / 2); 
  }

  if (id === 'Drug Trade Dale' && e.bossState === 'speed_dash') ctx.filter = `hue-rotate(${frame * 10}deg) saturate(3)`;
  switch (id) {
    case 'Artie Avalanche': ctx.fillStyle = '#AED6F1'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.fillStyle = '#FF8A80'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); ctx.fillStyle = '#2E86C1'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, Math.PI, 0); ctx.fill(); ctx.stroke(); break;
    case 'Victor Volcano': ctx.fillStyle = '#BA4A00'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); const lOff = (e.bossState === 'attacking' || e.bossState === 'telegraphing') ? Math.sin(frame * 0.5) * 6 : 0; ctx.fillStyle = '#C62828'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3 + lOff, width * 0.3, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); ctx.fillStyle = '#FF4500'; ctx.fillRect(width * 0.2, height * 0.2 + lOff, width * 0.6, height * 0.1); break;
    case 'Ernie Earthquake': ctx.fillStyle = '#6E2C00'; ctx.fillRect(0, height * 0.3, width, height * 0.7); ctx.strokeRect(0, height * 0.3, width, height * 0.7); ctx.fillStyle = '#FF5252'; ctx.fillRect(width * 0.2, 0, width * 0.6, height * 0.4); break;
    case 'Hector Hurricane': 
      if (e.bossState === 'hurricane') {
         // THUNDER AND LIGHTNING EFFECT
         ctx.save(); ctx.lineWidth = 3; ctx.shadowBlur = 15; ctx.shadowColor = '#00E5FF';
         for(let i=0; i<3; i++) {
           if ((frame + i * 20) % 30 < 5) {
             ctx.strokeStyle = i % 2 === 0 ? '#FFFFFF' : '#00E5FF'; ctx.beginPath(); ctx.moveTo(width/2, height/2); let curX = width/2, curY = height/2;
             for(let j=0; j<6; j++) { curX += (Math.random()-0.5) * 80; curY += (Math.random()-0.5) * 80; ctx.lineTo(curX, curY); }
             ctx.stroke();
           }
         }
         // Rotating cyan wind arcs
         ctx.globalAlpha = 0.5; ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
         for(let i=0; i<8; i++){
            const arcR = width * (1.2 + Math.sin(frame * 0.1 + i) * 0.3); const startA = frame * 0.15 + i * (Math.PI/4);
            ctx.beginPath(); ctx.arc(width/2, height/2, arcR, startA, startA + 0.6); ctx.stroke();
         }
         ctx.restore();
      }
      ctx.fillStyle = '#16A085'; ctx.fillRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7); ctx.strokeRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7); ctx.fillStyle = '#FF8A80'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); break;
    case 'Drug Trade Dale': ctx.fillStyle = '#2C3E50'; ctx.fillRect(0, 0, width, height); ctx.strokeRect(0, 0, width, height); ctx.fillStyle = '#8E44AD'; ctx.fillRect(width * 0.2, 0, width * 0.6, height * 0.4); ctx.fillStyle = 'gold'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.25, width * 0.2, 0, Math.PI * 2); ctx.fill(); if (e.bossState === 'using_shipment') { ctx.fillStyle = '#fff'; ctx.fillRect(width * 0.1, -20, width * 0.8, 20); } if (e.bossState === 'speed_dash') { ctx.save(); ctx.translate(width * 0.2, height * 0.3); ctx.rotate(-0.5); ctx.fillStyle = COLORS.PROJECTILE_DART; ctx.fillRect(0, -2, 16, 4); ctx.fillStyle = 'red'; ctx.fillRect(16, -4, 6, 8); ctx.restore(); } break;
    case 'Toxic Tommy': ctx.fillStyle = '#27AE60'; ctx.fillRect(0, 0, width, height); ctx.strokeRect(0, 0, width, height); ctx.fillStyle = '#ADFF2F'; ctx.fillRect(width * 0.1, height * 0.1, width * 0.8, height * 0.3); ctx.fillStyle = 'black'; ctx.beginPath(); ctx.arc(width * 0.3, height * 0.25, 4, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(width * 0.7, height * 0.25, 4, 0, Math.PI * 2); ctx.fill(); break;
    default: ctx.fillStyle = 'yellow'; ctx.fillRect(0, 0, width, height); break;
  }
  ctx.restore();
};

export const drawDaleDrugs = (ctx: CanvasRenderingContext2D, e: Enemy) => {
  if (e.bossState === 'using_shipment' && e.shipmentCount! > 0) { const stackX = e.pos.x - 60, groundY = 550; ctx.save(); for (let i = 0; i < e.shipmentCount!; i++) { const row = Math.floor(i / 2), col = i % 2; if (e.shipmentType === 'cocaine') { ctx.fillStyle = '#fff'; ctx.strokeStyle = '#ccc'; ctx.lineWidth = 1; const bx = stackX + (col * 20) + (row * 3), by = groundY - (row * 15) - 20; ctx.fillRect(bx, by, 18, 18); ctx.strokeRect(bx, by, 18, 18); } else if (e.shipmentType === 'meth') { ctx.fillStyle = '#111'; ctx.strokeStyle = '#FFD700'; ctx.lineWidth = 2; const bx = stackX + (col * 30) - 10, by = groundY - (row * 35) - 40; ctx.fillRect(bx, by, 30, 40); ctx.strokeRect(bx, by, 30, 40); ctx.fillStyle = '#FFD700'; ctx.font = '8px "Press Start 2P"'; ctx.textAlign = 'center'; ctx.fillText("METH", bx + 15, by + 25); } else if (e.shipmentType === 'speed' && e.stateTimer! > 0) { const bx = stackX, by = groundY - 20; ctx.fillStyle = COLORS.PROJECTILE_DART; ctx.fillRect(bx + 5, by, 15, 4); ctx.fillStyle = 'red'; ctx.fillRect(bx, by - 2, 6, 8); } } ctx.restore(); }
};

