         ctx.fillRect(b.x, b.y + b.h / 2 + doorOpen, b.w, b.h / 2);
         return;
      }
      ctx.fillStyle = stageColor ? (b.type === 'ground' || b.type === 'platform' ? stageColor.ground : '#444') : '#555';
      if (b.type === 'wall') ctx.fillStyle = '#222';
      ctx.fillRect(b.x, b.y, b.w, b.h);
      ctx.strokeStyle = '#000';
      ctx.lineWidth = 2;
      ctx.strokeRect(b.x, b.y, b.w, b.h);
    });

    state.pickups.forEach(p => {
       ctx.fillStyle = p.type.includes('health') ? '#ef4444' : '#eab308'; 
       ctx.save();
       ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2);
       const scale = 1.0 + Math.sin(state.frame * 0.1) * 0.1;
       ctx.scale(scale, scale);
       if (p.type.includes('health')) {
          ctx.fillRect(-p.width/3, -p.height/8, p.width/1.5, p.height/4);
          ctx.fillRect(-p.width/8, -p.height/3, p.width/4, p.height/1.5);
       } else {
          ctx.fillRect(-p.width/2, -p.height/2, p.width, p.height);
          ctx.fillStyle = 'black';
          ctx.fillText("A", -3, 3);
       }
       ctx.restore();
    });

    state.particles.forEach(p => {
      if (p.isWater) return; 
      ctx.fillStyle = p.color;
      ctx.globalAlpha = Math.min(1.0, p.life / 20);
      ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size);
      ctx.globalAlpha = 1.0;
    });

    state.enemies.forEach(e => {
       if (e.health <= 0 && !e.isBlownAway) return;
       ctx.save();
       if (e.type === 'boss') {
          BossLogic.drawBoss(ctx, e, stageId, state.frame);
          if (stageId === 'Drug Trade Dale') BossLogic.drawDaleDrugs(ctx, e);
       } else {
          ctx.translate(e.pos.x, e.pos.y);
          if (e.isBlownAway) ctx.rotate(e.rotation || 0);

          if (e.enemyType === 'drone' || e.enemyType === 'flyer') ctx.fillStyle = COLORS.ENEMY_FLYER;
          else if (e.enemyType === 'tank' || e.enemyType === 'turret') ctx.fillStyle = COLORS.ENEMY_TANK;
          else if (e.enemyType === 'shield') ctx.fillStyle = COLORS.ENEMY_SHIELD;

          if (e.isOiled) ctx.fillStyle = '#3E2723';
          if (e.frozenTimer && e.frozenTimer > 0) ctx.fillStyle = '#AED6F1';

          ctx.fillRect(0, 0, e.width, e.height);

          if (e.enemyType === 'shield') {
             if (e.isShieldActive) {
                ctx.fillStyle = '#95A5A6';
                ctx.fillRect(-5, 0, 5, e.height);
             }
          }
          if (e.enemyType === 'flyer') {
             ctx.fillStyle = '#ccc';
             const wingY = Math.sin(state.frame * 0.5) * 5;
             ctx.fillRect(-10, 5 + wingY, 10, 5);
             ctx.fillRect(e.width, 5 + wingY, 10, 5);
          }
       }

       if (e.isTased) {
          ctx.strokeStyle = '#00FFFF';
          ctx.beginPath();
          ctx.moveTo(0, 0);
          ctx.lineTo(e.width, e.height);
          ctx.moveTo(e.width, 0);
          ctx.lineTo(0, e.height);
          ctx.stroke();
       }

       if (e.isOnFire) {
         ctx.fillStyle = 'orange';
         ctx.beginPath();
         ctx.arc(e.width/2, e.height/2, e.width * 0.6, 0, Math.PI*2);
         ctx.fill();
       }

       if (e.type === 'boss' && e.health > 0) {
         ctx.fillStyle = 'black';
         ctx.fillRect(0, -15, e.width, 5);
         ctx.fillStyle = 'red';
         ctx.fillRect(0, -15, e.width * (e.health / e.maxHealth), 5);
       }
       ctx.restore();

       if (e.type === 'boss' && state.bossVulgarityTimer > 0 && state.bossLastVulgarity) {
          ctx.font = 'bold 12px monospace';
          const text = state.bossLastVulgarity;
          const w = ctx.measureText(text).width;
          const x = e.pos.x + e.width/2 - w/2;
          const y = e.pos.y - 40;
          ctx.fillStyle = 'black';
          ctx.fillRect(x - 5, y - 15, w + 10, 20);
          ctx.fillStyle = 'red';
          ctx.fillText(text, x, y);
       }
    });

    drawPlayer(ctx);

    if (state.player.isTasing && state.player.taserTargetId) {
       const target = state.enemies.find((e: Enemy) => e.id === state.player.taserTargetId) || state.projectiles.find((p: Projectile) => p.id === state.player.taserTargetId);
       if (target) {
          ctx.strokeStyle = COLORS.TASER_BOLT;
          ctx.lineWidth = 2;
          ctx.beginPath();
          const startX = state.player.pos.x + state.player.width/2;
          const startY = state.player.pos.y + state.player.height/2;
          const endX = target.pos.x + target.width/2;
          const endY = target.pos.y + target.height/2;
          ctx.moveTo(startX, startY);
          const segments = 10;
          for(let i=1; i<segments; i++) {
             const t = i / segments;
             const tx = startX + (endX - startX) * t;
             const ty = startY + (endY - startY) * t;
             ctx.lineTo(tx + (Math.random()-0.5)*10, ty + (Math.random()-0.5)*10);
          }
          ctx.lineTo(endX, endY);
          ctx.stroke();
       } else if (!target) {
          // Wasted Stream Logic
          ctx.strokeStyle = COLORS.TASER_BOLT;
          ctx.lineWidth = 2;
          ctx.beginPath();
          const startX = state.player.pos.x + state.player.width/2;
          const startY = state.player.pos.y + state.player.height/2;
          const endX = startX + (state.player.facing * 400);
          const endY = startY + (Math.sin(state.frame * 0.4) * 60);
          ctx.moveTo(startX, startY);
          const segments = 10;
          for (let i = 1; i < segments; i++) {
             const t = i / segments;
             const tx = startX + (endX - startX) * t + (Math.random()-0.5)*40;
             const ty = startY + (endY - startY) * t + (Math.random()-0.5)*40;
             ctx.lineTo(tx, ty);
          }
          ctx.lineTo(endX, endY);
          ctx.stroke();
       }
    }

    state.projectiles.forEach(p => {
       ctx.save();
       ctx.translate(p.pos.x, p.pos.y);
       if (p.rotation) {
          ctx.translate(p.width/2, p.height/2);
          ctx.rotate(p.rotation);
          ctx.translate(-p.width/2, -p.height/2);
       }

       if (p.isBoulder) {
          ctx.fillStyle = '#5D4037';
          ctx.beginPath(); ctx.arc(p.width/2, p.height/2, p.width/2, 0, Math.PI*2); ctx.fill();
       } else if (p.isIce) {
          ctx.fillStyle = COLORS.PROJECTILE_ICE;
          ctx.fillRect(0, 0, p.width, p.height);
       } else if (p.isOilRocket) {
          ctx.fillStyle = '#1A110F';
          ctx.fillRect(0, 0, p.width, p.height);
          ctx.fillStyle = 'red';
          ctx.fillRect(p.width - 5, 2, 5, p.height - 4);
       } else if (p.isSludge) {
          ctx.fillStyle = '#2E7D32';
          if (p.isLingering) {
             ctx.globalAlpha = 0.7;
             ctx.beginPath(); ctx.ellipse(p.width/2, p.height, p.width/2, p.height/2, 0, 0, Math.PI*2); ctx.fill();
             ctx.globalAlpha = 1.0;
          } else {
             ctx.beginPath(); ctx.arc(p.width/2, p.height/2, p.width/2, 0, Math.PI*2); ctx.fill();
          }
       } else if (p.isMethBarrel) {
          ctx.fillStyle = '#111';
          ctx.fillRect(0, 0, p.width, p.height);
          ctx.fillStyle = '#FFD700';
          ctx.font = '8px monospace';
          ctx.fillText("METH", 5, 25);
       } else if (p.isCocaine) {
          ctx.fillStyle = 'white';
          ctx.fillRect(0, 0, p.width, p.height);
       } else if (p.isPoop) {
          ctx.fillStyle = '#5D4037';
          ctx.beginPath(); ctx.arc(p.width/2, p.height/2, p.width/2, 0, Math.PI*2); ctx.fill();
       } else {
          ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY;
          if (p.isDart) ctx.fillStyle = '#BDC3C7';
          ctx.fillRect(0, 0, p.width, p.height);
       }
       ctx.restore();
    });

    state.particles.forEach(p => {
       if (!p.isWater) return;
       ctx.fillStyle = p.color;
       ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size);
    });

    state.damageNumbers.forEach(d => {
       ctx.fillStyle = d.isCritical ? '#FFD700' : 'white';
       ctx.font = `bold ${d.isCritical ? '24px' : '16px'} Arial`;
       ctx.strokeStyle = 'black';
       ctx.lineWidth = 3;
       ctx.strokeText(d.value.toString(), d.pos.x, d.pos.y);
       ctx.fillText(d.value.toString(), d.pos.x, d.pos.y);
    });

    if (state.victoryString) {
       ctx.save();
       ctx.fillStyle = 'yellow';
       ctx.font = 'bold 80px Arial';
       ctx.strokeStyle = 'red';
       ctx.lineWidth = 5;
       const measure = ctx.measureText(state.victoryString);
       const x = state.camera.x + CANVAS_WIDTH/2 - measure.width/2;
       const y = state.camera.y + CANVAS_HEIGHT/2;
       ctx.strokeText(state.victoryString, x, y);
       ctx.fillText(state.victoryString, x, y);
       ctx.restore();
    }

    if (state.deathString) {
       ctx.save();
       ctx.fillStyle = 'red';
       ctx.font = 'bold 80px Arial';
       ctx.strokeStyle = 'black';
       ctx.lineWidth = 5;
       const measure = ctx.measureText(state.deathString);
       const x = state.camera.x + CANVAS_WIDTH/2 - measure.width/2;
       const y = state.camera.y + CANVAS_HEIGHT/2;
       ctx.strokeText(state.deathString, x, y);
       ctx.fillText(state.deathString, x, y);
       ctx.restore();
    }

    ctx.restore();
  }, [stageId, drawPlayer]);

  useEffect(() => {
    let frameId: number; 
    const loop = () => { update(); draw(); frameId = window.requestAnimationFrame(loop); };
    const state = gameStateRef.current;
    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) { 
      if (state.frame === 0 && status === GameStatus.LEVEL_INTRO) { 
        state.frame = 1;
        createLevel(); 
      }
      frameId = window.requestAnimationFrame(loop); 
    } else { 
      state.victoryString = ""; state.postVictoryTimer = 0; state.bossExplosionTimer = 0; state.introTimer = 0; state.enemies = []; state.particles = []; state.projectiles = []; state.blocks = []; state.camera = { x: 0, y: 0 }; state.frame = 0; draw(); 
    }
    return () => window.cancelAnimationFrame(frameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

