const Overlay: React.FC<OverlayProps> = ({ 
  status, onStart, onResume, onBossSelect, onQuitToMenu, onSelectStage, onIconClick, onCheatAllWeapons, onToggleInvincibility, onToggleInfiniteAmmo, onToggleInfinitePower, onToggleJumpToBoss,
  onIncrementRank, onDecrementRank, progressionRank = 0,
  cheatEnabled, invincibilityEnabled, infiniteAmmoEnabled, infinitePowerEnabled, jumpToBossEnabled, showCheats = false, bossTaunt, victorySpeech, briefing, defeatedStages = [], selectedIndex, overlayActiveTime, stageId,
  availableWeapons = [], currentWeapon
}) => {
  const isInputLocked = overlayActiveTime < 2000;
  const currentStages = STAGES(progressionRank);

  if (status === GameStatus.PLAYING || status === GameStatus.LEVEL_INTRO || status === GameStatus.BOSS_TRANSITION) return null;

  const getWeaponDescription = (w: WeaponType) => {
    if (w === 'GUN') return "STANDARD PUMP ACTION";
    const bossName = Object.keys(BOSS_WEAPON_MAP).find(k => BOSS_WEAPON_MAP[k] === w);
    if (bossName) return WEAPON_DESCRIPTIONS[bossName];
    return "HEAVY DEVASTATION";
  };

  const getDisplayName = (w: WeaponType) => {
    if (w === 'OIL_ROCKET') return 'ROCKET';
    if (w === 'FLAMETHROWER') return 'FLAME';
    return w;
  };

  // Weapon Inventory Grid Split Logic
  const totalWeapons = availableWeapons.length;
  const useTwoRows = totalWeapons > 4;
  const topRowSize = useTwoRows ? Math.ceil(totalWeapons / 2) : totalWeapons;
  const bottomRowSize = useTwoRows ? Math.floor(totalWeapons / 2) : 0;

  const topRowWeapons = availableWeapons.slice(0, topRowSize);
  const bottomRowWeapons = availableWeapons.slice(topRowSize);

  const renderWeaponIcon = (w: WeaponType, absoluteIndex: number) => (
    <div key={w} className="flex flex-col items-center gap-2">
      <WeaponIcon 
        type={w} 
        isEquipped={currentWeapon === w} 
        isSelected={selectedIndex === absoluteIndex}
        onClick={() => onIconClick?.(absoluteIndex)}
      />
      <div className={`text-[8px] font-black ${selectedIndex === absoluteIndex ? 'text-yellow-400' : 'text-white/40'}`}>
        {getDisplayName(w)}
      </div>
    </div>
  );

  return (
    <div className="absolute inset-0 bg-black/95 flex flex-col items-center justify-center z-50 p-6 text-center overflow-hidden">
      {status === GameStatus.START && (
        <>
          {showCheats && (
            <div className="absolute top-2 right-2 z-[60] flex flex-col gap-1 items-end max-w-[150px]">
                <div className="flex w-full border-2 border-gray-600 bg-gray-900 shadow-[2px_2px_0px_white] items-center overflow-hidden">
                   <button onClick={onDecrementRank} className="px-2 py-1 bg-gray-800 hover:bg-gray-700 text-white font-black text-[10px]">-</button>
                   <div className="flex-1 text-[7px] font-black text-yellow-400 uppercase tracking-tighter">SKP SET: {progressionRank}</div>
                   <button onClick={onIncrementRank} className="px-2 py-1 bg-gray-800 hover:bg-gray-700 text-white font-black text-[10px]">+</button>
                </div>
                <button onClick={onToggleJumpToBoss} className={`w-full px-2 py-1 border-2 transition-all font-black text-[7px] uppercase shadow-[2px_2px_0px_white] ${jumpToBossEnabled ? 'bg-red-500 border-white text-black' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>SKIP LEVEL: {jumpToBossEnabled ? 'ON' : 'OFF'}</button>
                <div className="h-2 w-full" />
                <button onClick={onToggleInvincibility} className={`w-full px-2 py-1 border-2 transition-all font-black text-[7px] uppercase shadow-[2px_2px_0px_white] ${invincibilityEnabled ? 'bg-green-500 border-white text-black' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>GOD MODE: {invincibilityEnabled ? 'ON' : 'OFF'}</button>
                <button onClick={onCheatAllWeapons} className={`w-full px-2 py-1 border-2 transition-all font-black text-[7px] uppercase shadow-[2px_2px_0px_white] ${cheatEnabled ? 'bg-yellow-500 border-white text-black' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>ALL WEAPONS: {cheatEnabled ? 'ON' : 'OFF'}</button>
                <button onClick={onToggleInfiniteAmmo} className={`w-full px-2 py-1 border-2 transition-all font-black text-[7px] uppercase shadow-[2px_2px_0px_white] ${infiniteAmmoEnabled ? 'bg-blue-500 border-white text-black' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>INF AMMO: {infiniteAmmoEnabled ? 'ON' : 'OFF'}</button>
                <button onClick={onToggleInfinitePower} className={`w-full px-2 py-1 border-2 transition-all font-black text-[7px] uppercase shadow-[2px_2px_0px_white] ${infinitePowerEnabled ? 'bg-purple-500 border-white text-black' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>INF POWER: {infinitePowerEnabled ? 'ON' : 'OFF'}</button>
            </div>
          )}
          <div className="animate-in fade-in zoom-in duration-700 max-w-lg relative w-full h-full flex flex-col items-center justify-center pt-8">
            <MeatheadCaricature />
            <h1 className="text-4xl md:text-5xl text-red-600 mb-2 font-black tracking-tighter drop-shadow-[4px_4px_0px_white]">MEATHEAD</h1>
            <div className="text-white text-[9px] mb-6 border-y border-red-900 py-3 px-4 italic uppercase tracking-tight leading-relaxed max-w-sm mx-auto">MISSION: {briefing}</div>
            <button 
              disabled={isInputLocked} 
              onClick={onStart} 
              className={`px-10 py-4 text-white text-xl border-b-[8px] transition-all font-black uppercase ring-4 ring-white/10 ${isInputLocked ? 'bg-gray-700 border-gray-900 opacity-50 cursor-not-allowed' : 'bg-red-700 hover:bg-red-500 border-red-900 active:translate-y-1 active:border-b-[2px]'}`}
            >
              {isInputLocked ? 'LOADING MISSION...' : 'PRESS START'}
            </button>
            <ControlsGuide />
          </div>
        </>
      )}

      {status === GameStatus.STAGE_SELECT && (
        <div className="flex flex-col items-center w-full max-w-4xl">
          <h2 className="text-2xl text-white font-black italic mb-8 tracking-widest bg-red-900 px-6 py-2 border-2 border-white shadow-[4px_4px_0px_white]">SELECT YOUR TARGET</h2>
          <div className="grid grid-cols-2 gap-8 w-full max-w-2xl px-4">
            {currentStages.map((stage, i) => {
              const isDefeated = defeatedStages.includes(stage.id);
              const isSelected = selectedIndex === i;
              return (
                <div 
                  key={stage.id} 
                  onClick={() => onSelectStage?.(stage.id)}
                  className={`relative cursor-pointer transition-all duration-200 group border-4 ${isSelected ? 'border-yellow-400 scale-105 shadow-[0_0_30px_rgba(255,255,0,0.4)]' : 'border-white/20'}`}
                >
                  <div className={`aspect-video overflow-hidden ${isDefeated ? 'grayscale brightness-50' : ''}`}>
                    <BossPortrait id={stage.id} />
                  </div>
                  <div className={`absolute bottom-0 left-0 right-0 p-2 font-black italic text-[10px] uppercase text-center border-t-2 ${isSelected ? 'bg-yellow-400 text-black border-white' : 'bg-black text-white border-white/20'}`}>
                    {stage.id}
                  </div>
                  {isDefeated && (
                    <div className="absolute inset-0 flex items-center justify-center pointer-events-none bg-red-950/20">
                      <div className="text-red-600 font-black text-4xl -rotate-12 select-none uppercase tracking-tighter drop-shadow-[2px_2px_0px_black] animate-pulse">DEAD AS SHIT</div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {status === GameStatus.PAUSED && (
        <div className="flex flex-col items-center w-full max-w-2xl p-8 bg-black/80 border-4 border-red-900 shadow-[0_0_50px_rgba(255,0,0,0.2)]">
          <h2 className="text-4xl text-red-600 font-black italic mb-10 tracking-tighter drop-shadow-[2px_2px_0px_white]">PUMP BREAK</h2>

          <div className="w-full mb-10">
             <div className="text-gray-400 text-[10px] font-black uppercase mb-4 text-left border-b border-gray-800 pb-2">WEAPON INVENTORY</div>
             <div className="flex flex-col gap-6 items-center">
               {/* Top Row */}
               <div className="flex flex-wrap gap-4 justify-center">
                 {topRowWeapons.map((w, i) => renderWeaponIcon(w, i))}
               </div>
               {/* Bottom Row */}
               {useTwoRows && (
                 <div className="flex flex-wrap gap-4 justify-center">
                   {bottomRowWeapons.map((w, i) => renderWeaponIcon(w, topRowSize + i))}
                 </div>
               )}
             </div>

             {selectedIndex >= 0 && selectedIndex < availableWeapons.length && (
               <div className="mt-6 p-4 bg-gray-900 border-2 border-gray-700 min-h-[80px] flex flex-col justify-center">
                 <div className="text-yellow-400 font-black text-[10px] italic mb-1 uppercase underline decoration-2">{WEAPON_NAMES[Object.keys(WEAPON_NAMES).find(k => BOSS_WEAPON_MAP[k] === availableWeapons[selectedIndex]) || ''] || 'STANDARD ISSUE'}</div>
                 <div className="text-white text-[9px] font-bold uppercase leading-tight italic">{getWeaponDescription(availableWeapons[selectedIndex])}</div>
               </div>
             )}
          </div>

          <div className="flex flex-col gap-3 w-full max-w-xs">
            <button onClick={onResume} className={`w-full py-3 font-black italic uppercase border-2 shadow-[4px_4px_0px_red] transition-all ${selectedIndex === availableWeapons.length ? 'bg-white text-black border-white' : 'bg-red-900 text-white border-red-700 hover:bg-red-700'}`}>BACK TO THE GAINS</button>
            <button onClick={onBossSelect} className={`w-full py-3 font-black italic uppercase border-2 shadow-[4px_4px_0px_red] transition-all ${selectedIndex === availableWeapons.length + 1 ? 'bg-white text-black border-white' : 'bg-red-900 text-white border-red-700 hover:bg-red-700'}`}>ABANDON REP</button>
            <button onClick={onQuitToMenu} className={`w-full py-3 font-black italic uppercase border-2 shadow-[4px_4px_0px_red] transition-all ${selectedIndex === availableWeapons.length + 2 ? 'bg-white text-black border-white' : 'bg-red-900 text-white border-red-700 hover:bg-red-700'}`}>QUIT GYM</button>
          </div>
        </div>
      )}

      {status === GameStatus.BOSS_INTRO && (
        <div className="flex flex-col items-center w-full">
           <div className="text-red-600 text-6xl font-black italic mb-4 animate-bounce tracking-tighter drop-shadow-[4px_4px_0px_white]">WARNING!</div>
           <div className="text-white text-xl font-black italic bg-red-900 px-10 py-4 border-4 border-white shadow-[10px_10px_0px_black] uppercase max-w-lg mb-8">
             {stageId && `${stageId.toUpperCase()} INCOMING!`}
           </div>
           <div className="text-yellow-400 text-sm font-black italic animate-pulse">"{bossTaunt}"</div>
        </div>
      )}

      {status === GameStatus.BOSS_VICTORY_SPEECH && (
        <div className="flex flex-col items-center w-full">
           <h2 className="text-red-600 text-6xl font-black italic mb-6 tracking-tighter drop-shadow-[4px_4px_0px_white] animate-pulse">TARGET MURDERED</h2>
           <div className="flex flex-col items-center gap-4 w-full max-w-lg mt-8">
              <div className="p-6 bg-red-900 border-4 border-white shadow-[8px_8px_0px_black] w-full">
                <div className="text-[10px] text-white/70 mb-3 uppercase font-black italic">NEW WEAPON ACQUIRED:</div>
                <div className="text-white font-black italic text-2xl mb-4 underline decoration-4 decoration-red-400 uppercase tracking-tighter">
                  {stageId && WEAPON_NAMES[stageId]}
                </div>
                <div className="text-white text-[9px] font-bold uppercase leading-snug italic bg-black/40 p-4 border border-white/20">
                  {stageId && WEAPON_DESCRIPTIONS[stageId]}
                </div>
              </div>
           </div>
        </div>
      )}

      {status === GameStatus.GAME_OVER && (
        <div className="flex flex-col items-center">
           <h2 className="text-8xl text-red-600 font-black italic mb-4 tracking-tighter drop-shadow-[8px_8px_0px_white] animate-pulse">TOTAL FAILURE</h2>
           <div className="text-white text-[10px] font-black italic mb-12 uppercase tracking-[0.3em]">YOU SKIPPED TOO MANY LEG DAYS</div>
           <button onClick={onStart} className="px-12 py-5 bg-red-800 text-white text-2xl font-black italic border-b-[10px] border-red-950 hover:bg-red-600 hover:scale-110 active:translate-y-2 active:border-b-0 transition-all uppercase ring-4 ring-white/10">TRY AGAIN, NANCY</button>
        </div>
      )}

      {status === GameStatus.VICTORY && (
        <div className="flex flex-col items-center max-w-2xl">
           <h2 className="text-6xl text-yellow-400 font-black italic mb-2 tracking-tighter drop-shadow-[6px_6px_0px_red]">ULTIMATE PUMP</h2>
           <div className="text-white text-[10px] font-black italic mb-10 uppercase tracking-[0.5em] border-b border-white/20 pb-4">ALL WEAKNESS ELIMINATED</div>
           <div className="aspect-video w-96 bg-gray-900 border-4 border-yellow-400 p-4 mb-8 overflow-hidden relative">
              <MeatheadCaricature />
              <div className="absolute inset-x-0 bottom-0 bg-yellow-400 text-black font-black italic py-1 text-center text-[10px]">SUPREME MEATHEAD</div>
           </div>
           <button onClick={onStart} className="px-12 py-5 bg-yellow-600 text-black text-2xl font-black italic border-b-[10px] border-yellow-900 hover:bg-yellow-400 hover:scale-110 active:translate-y-2 active:border-b-0 transition-all uppercase">RESTART BULK PHASE</button>
        </div>
      )}
    </div>
  );
};

export default Overlay;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import HUD from './HUD';
import Overlay from './Overlay';
import GameCanvas from './GameCanvas';
import { GameStatus, WeaponType } from './types';
import { 
  INITIAL_PLAYER_HEALTH, 
  SPECIAL_CHARGE_REGEN_FRAMES, 
  MAX_AMMO, 
  STAGES, 
  BOSS_WEAPON_MAP, 
  SET0_WEAPONS, 
  ALL_WEAPONS_CHEAT,
  VULGARITIES, 
  BOSS_DIALOGUE,
  WEAPON_ORDER
} from './constants';

// --- DEV CONFIG ---
const SHOW_CHEATS = true;
// ------------------

const App: React.FC = () => {
  const [status, setStatus] = useState<GameStatus>(GameStatus.START);
  const [health, setHealth] = useState(INITIAL_PLAYER_HEALTH);
  const [specialCharges, setSpecialCharges] = useState(2);
  const [specialChargeTimer, setSpecialChargeTimer] = useState(0);
  const [bossTaunt, setBossTaunt] = useState("YOU'RE TOAST.");
  const [victorySpeech, setVictorySpeech] = useState("");
  const [briefing, setBriefing] = useState("Your mission is to kill everything in sight for no particular reason.");
  const [selectedStage, setSelectedStage] = useState<string | null>(null);
  const [defeatedStages, setDefeatedStages] = useState<string[]>([]);
  const [availableWeapons, setAvailableWeapons] = useState<WeaponType[]>(['GUN']);
  const [currentWeapon, setCurrentWeapon] = useState<WeaponType>('GUN');

  const resetAmmo = useCallback(() => {
    return {
      'GUN': Infinity,
      'BOULDER': MAX_AMMO['BOULDER'],
      'SHOTGUN': MAX_AMMO['SHOTGUN'],
      'OIL_ROCKET': MAX_AMMO['OIL_ROCKET'],
      'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'],
      'TSUNAMI': MAX_AMMO['TSUNAMI'],
      'NEEDLES': MAX_AMMO['NEEDLES'],
      'TASER': MAX_AMMO['TASER'],
      'SLUDGE': MAX_AMMO['SLUDGE']
    };
  }, []);

  const [weaponAmmo, setWeaponAmmo] = useState<Record<WeaponType, number>>(resetAmmo());

  const [cheatEnabled, setCheatEnabled] = useState(false);
  const [invincibilityEnabled, setInvincibilityEnabled] = useState(false);
  const [infiniteAmmoEnabled, setInfiniteAmmoEnabled] = useState(false);
  const [infinitePowerEnabled, setInfinitePowerEnabled] = useState(false);
  const [jumpToBossEnabled, setJumpToBossEnabled] = useState(false);
  const [progressionRank, setProgressionRank] = useState(0);

  const [isVictoryPhase, setIsVictoryPhase] = useState(false);
  const [overlayActiveTime, setOverlayActiveTime] = useState(0);

  const [selectedIndex, setSelectedIndex] = useState(0);

  // Refs to prevent stale closures in polling
  const statusRef = useRef(status);
  const selectedIndexRef = useRef(selectedIndex);
  const progressionRankRef = useRef(progressionRank);
  const availableWeaponsRef = useRef(availableWeapons);

  const lastPadInputRef = useRef(0);
  const lastAStateRef = useRef(false);
  const lastBStateRef = useRef(false);
  const lastStartStateRef = useRef(false);
  const lastLBStateRef = useRef(false);
  const lastRBStateRef = useRef(false);

  // Sync refs with state
  useEffect(() => { statusRef.current = status; }, [status]);
  useEffect(() => { selectedIndexRef.current = selectedIndex; }, [selectedIndex]);
  useEffect(() => { progressionRankRef.current = progressionRank; }, [progressionRank]);
  useEffect(() => { availableWeaponsRef.current = availableWeapons; }, [availableWeapons]);

  // Global Meathead cooldown for App-level speech
  const meatheadSpeechCooldownRef = useRef(0);

  useEffect(() => {
    let interval: number;
    if (status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH || status === GameStatus.START || status === GameStatus.VICTORY) {
      setOverlayActiveTime(0);
      interval = window.setInterval(() => {
        setOverlayActiveTime(prev => prev + 100);
      }, 100);
    }
    return () => clearInterval(interval);
  }, [status]);

  // Handle Meathead speech cooldown decrement
  useEffect(() => {
    const timer = setInterval(() => {
      if (meatheadSpeechCooldownRef.current > 0) meatheadSpeechCooldownRef.current -= 100;
    }, 100);
    return () => clearInterval(timer);
  }, []);

  const speakBossTaunt = useCallback((stage: string, text: string) => {
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(text);
      switch (stage) {
        case 'Artie Avalanche': utterance.pitch = 1.6; utterance.rate = 0.85; break;
        case 'Victor Volcano': utterance.pitch = 0.7; utterance.rate = 0.85; break;
        case 'Ernie Earthquake': utterance.pitch = 0.1; utterance.rate = 0.55; break;
        case 'Hector Hurricane': utterance.pitch = 1.2; utterance.rate = 1.5; break;
        case 'Blackout Barry': utterance.pitch = 1.4; utterance.rate = 1.1; break;
        default: utterance.pitch = 1.0; utterance.rate = 1.0;
      }
      utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  }, []);

  useEffect(() => {
    if (status === GameStatus.BOSS_INTRO && selectedStage && bossTaunt) {
      speakBossTaunt(selectedStage, bossTaunt);
    }
  }, [status, selectedStage, bossTaunt, speakBossTaunt]);

  const cycleWeapon = useCallback((dir: number) => {
    setAvailableWeapons(prevAvailable => {
      if (prevAvailable.length <= 1) return prevAvailable;
      setCurrentWeapon(current => {
        const idx = prevAvailable.indexOf(current);
        const nextIdx = (idx + dir + prevAvailable.length) % prevAvailable.length;
        return prevAvailable[nextIdx];
      });
      return prevAvailable;
    });
  }, []);

  const selectWeaponByIndex = useCallback((index: number) => {
    setAvailableWeapons(prev => {
      if (index >= 0 && index < prev.length) {
        setCurrentWeapon(prev[index]);
      }
      return prev;
    });
  }, []);

  const handleIconClick = useCallback((index: number) => {
    setSelectedIndex(index);
    selectWeaponByIndex(index);
  }, [selectWeaponByIndex]);

  const speakRebuke = useCallback(() => {
    if ('speechSynthesis' in window) {
      if (window.speechSynthesis.speaking) return;
      if (meatheadSpeechCooldownRef.current > 0) return;
      const text = VULGARITIES.REBUKE[Math.floor(Math.random() * VULGARITIES.REBUKE.length)];
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1; utterance.rate = 1.1; utterance.volume = 1.0;
      utterance.onend = () => { meatheadSpeechCooldownRef.current = 1000; };
      utterance.onerror = () => { meatheadSpeechCooldownRef.current = 1000; };
      window.speechSynthesis.speak(utterance);
    }
  }, []);

  const togglePause = useCallback(() => {
    setStatus(prev => {
      if (isVictoryPhase || prev === GameStatus.BOSS_TRANSITION || prev === GameStatus.BOSS_INTRO || prev === GameStatus.BOSS_VICTORY_SPEECH || prev === GameStatus.LEVEL_INTRO || prev === GameStatus.VICTORY) return prev;
      if (prev === GameStatus.PLAYING) { 
        setSelectedIndex(availableWeaponsRef.current.indexOf(currentWeapon));
        return GameStatus.PAUSED; 
      }
      if (prev === GameStatus.PAUSED) return GameStatus.PLAYING;
      return prev;
    });
  }, [isVictoryPhase, currentWeapon]);

  const handleStart = useCallback(() => {
    if (overlayActiveTime < 2000) return;
    if (status === GameStatus.VICTORY || status === GameStatus.GAME_OVER) {
      if ('speechSynthesis' in window) window.speechSynthesis.cancel();
      // RESET HEALTH AND AMMO ON RESTART
      setHealth(INITIAL_PLAYER_HEALTH);
      setWeaponAmmo(resetAmmo());

      if (progressionRank === 0 && defeatedStages.length >= 4) {
        setProgressionRank(1); 
        setDefeatedStages([]); 
        setAvailableWeapons(SET0_WEAPONS.sort((a,b) => WEAPON_ORDER.indexOf(a) - WEAPON_ORDER.indexOf(b))); 
        setCurrentWeapon('GUN'); 
        setStatus(GameStatus.STAGE_SELECT);
      } else {
        setDefeatedStages([]); 
        const weaponsToStart: WeaponType[] = (cheatEnabled && SHOW_CHEATS) ? ALL_WEAPONS_CHEAT : (progressionRank === 1 ? SET0_WEAPONS : ['GUN'] as WeaponType[]); 
        setAvailableWeapons([...weaponsToStart].sort((a,b) => WEAPON_ORDER.indexOf(a) - WEAPON_ORDER.indexOf(b))); 
        setCurrentWeapon('GUN'); 
        setSelectedIndex(0); 
        setIsVictoryPhase(false); 
        setStatus(GameStatus.START);
      }
    } else if (status === GameStatus.START) {
      const weaponsToStart: WeaponType[] = (cheatEnabled && SHOW_CHEATS) ? ALL_WEAPONS_CHEAT : (progressionRank === 1 ? SET0_WEAPONS : ['GUN'] as WeaponType[]); 
      setAvailableWeapons([...weaponsToStart].sort((a,b) => WEAPON_ORDER.indexOf(a) - WEAPON_ORDER.indexOf(b))); 
      setCurrentWeapon('GUN'); 
      setWeaponAmmo(resetAmmo()); 
      setStatus(GameStatus.STAGE_SELECT);
    } else if (status === GameStatus.BOSS_INTRO) {
      setStatus(GameStatus.PLAYING);
    } else if (status === GameStatus.BOSS_VICTORY_SPEECH) {
      if ('speechSynthesis' in window) window.speechSynthesis.cancel();
      setIsVictoryPhase(false);
      if (defeatedStages.length >= 4) { setStatus(GameStatus.VICTORY); } 
      else { 
        setStatus(GameStatus.STAGE_SELECT); 
        setSelectedStage(null); 
        setSelectedIndex(0); 
        setCurrentWeapon('GUN'); 
        setWeaponAmmo(resetAmmo()); 
      }
    }
  }, [status, defeatedStages, overlayActiveTime, cheatEnabled, progressionRank, resetAmmo]);

  const handleResume = useCallback(() => { setStatus(GameStatus.PLAYING); }, []);

  const handleBossSelect = useCallback(() => {
    if ('speechSynthesis' in window) window.speechSynthesis.cancel();
    setSelectedStage(null); setSelectedIndex(0); setIsVictoryPhase(false); setCurrentWeapon('GUN'); setStatus(GameStatus.STAGE_SELECT); setWeaponAmmo(resetAmmo());
  }, [resetAmmo]);

  const handleQuitToMenu = useCallback(() => { 
    if ('speechSynthesis' in window) window.speechSynthesis.cancel();
    setSelectedStage(null); setSelectedIndex(0); setIsVictoryPhase(false); setDefeatedStages([]); setCurrentWeapon('GUN'); setProgressionRank(0); setStatus(GameStatus.START); 
  }, []);

  const handleSelectStage = useCallback((stage: string) => {
    if (defeatedStages.includes(stage)) { speakRebuke(); return; }
    if ('speechSynthesis' in window) window.speechSynthesis.cancel();
    setSelectedStage(stage); 
    setHealth(INITIAL_PLAYER_HEALTH); 
    setSpecialCharges(2); 
    setSpecialChargeTimer(0); 
    setCurrentWeapon('GUN'); 
    setWeaponAmmo(resetAmmo()); 
    setIsVictoryPhase(false); 
    setStatus(GameStatus.LEVEL_INTRO);
  }, [defeatedStages, speakRebuke, resetAmmo]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const key = e.key.toLowerCase();
      if (key === 'escape') togglePause();

      if (status === GameStatus.PAUSED || status === GameStatus.STAGE_SELECT) {
        const numW = availableWeapons.length;
        const useTwoRows = numW > 4;
        const topRowSize = useTwoRows ? Math.ceil(numW / 2) : numW;
        const bottomRowSize = useTwoRows ? Math.floor(numW / 2) : 0;

        if (key === 'arrowup' || key === 'w') { 
          if (status === GameStatus.PAUSED) {
            setSelectedIndex(p => {
              if (p >= numW) return p - 1; 
              if (useTwoRows && p >= topRowSize) return p - topRowSize; 
              return p;
            });
          }
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p - 2 + 4) % 4); 
        } 
        else if (key === 'arrowdown' || key === 's') { 
          if (status === GameStatus.PAUSED) {
            setSelectedIndex(p => {
              if (useTwoRows && p < topRowSize && p + topRowSize < numW) return p + topRowSize; 
              if (p < numW) return numW; 
              if (p < numW + 2) return p + 1; 
              return p;
            });
          }
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p + 2) % 4); 
        } 
        else if (key === 'arrowleft' || key === 'a') { 
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p % 2 === 0 ? p + 1 : p - 1));
          if (status === GameStatus.PAUSED && selectedIndex < numW) {
            setSelectedIndex(p => p > 0 ? p - 1 : p);
          }
        } 
        else if (key === 'arrowright' || key === 'd') { 
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p % 2 === 0 ? p + 1 : p - 1));
          if (status === GameStatus.PAUSED && selectedIndex < numW) {
            setSelectedIndex(p => p < numW - 1 ? p + 1 : p);
          }
        } 
        else if (key === 'enter' || key === ' ') { 
          if (status === GameStatus.PAUSED) {
            if (selectedIndex < numW) {
              selectWeaponByIndex(selectedIndex);
            } else if (selectedIndex === numW) {
              handleResume();
            } else if (selectedIndex === numW + 1) {
              handleBossSelect();
            } else if (selectedIndex === numW + 2) {
              handleQuitToMenu();
            }
          } else if (status === GameStatus.STAGE_SELECT) { handleSelectStage(STAGES(progressionRank)[selectedIndex].id); } 
        }
      } else if (status === GameStatus.PLAYING) { 
        if (key === 'q') cycleWeapon(-1); if (key === 'e') cycleWeapon(1); 
      } 
      else if (status === GameStatus.START || status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH || status === GameStatus.VICTORY) { if (key === 'enter' || key === ' ') handleStart(); }
    };
    const handleWheel = (e: WheelEvent) => { if (status === GameStatus.PLAYING) cycleWeapon(e.deltaY > 0 ? 1 : -1); };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('wheel', handleWheel);
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('wheel', handleWheel); };
  }, [togglePause, status, cycleWeapon, selectWeaponByIndex, availableWeapons, currentWeapon, selectedIndex, handleResume, handleBossSelect, handleQuitToMenu, handleSelectStage, handleStart, progressionRank]);

  const handleToggleCheat = useCallback(() => {
    setCheatEnabled(prev => { 
      const newState = !prev; 
      if (newState) setAvailableWeapons([...ALL_WEAPONS_CHEAT].sort((a,b) => WEAPON_ORDER.indexOf(a) - WEAPON_ORDER.indexOf(b))); 
      else {
        const resetWpns = progressionRank === 1 ? SET0_WEAPONS : ['GUN'] as WeaponType[];
        setAvailableWeapons([...resetWpns].sort((a,b) => WEAPON_ORDER.indexOf(a) - WEAPON_ORDER.indexOf(b))); 
        setCurrentWeapon('GUN'); 
      } 
      return newState; 
    });
  }, [progressionRank]);

  const handleToggleInvincibility = useCallback(() => setInvincibilityEnabled(prev => !prev), []);
  const handleToggleInfiniteAmmo = useCallback(() => setInfiniteAmmoEnabled(prev => !prev), []);
  const handleToggleInfinitePower = useCallback(() => setInfinitePowerEnabled(prev => !prev), []);
  const handleToggleJumpToBoss = useCallback(() => setJumpToBossEnabled(prev => !prev), []);

  const handleIncrementRank = useCallback(() => { 
    setProgressionRank(r => { 
      const next = Math.min(r + 1, 1); 
      if (next === 1 && !cheatEnabled) setAvailableWeapons([...SET0_WEAPONS].sort((a,b) => WEAPON_ORDER.indexOf(a) - WEAPON_ORDER.indexOf(b))); 
      return next; 
    }); 
  }, [cheatEnabled]);

  const handleDecrementRank = useCallback(() => { 
    setProgressionRank(r => { 
      const next = Math.max(r - 1, 0); 
      if (next === 0 && !cheatEnabled) setAvailableWeapons(['GUN'] as WeaponType[]); 
      return next; 
    }); 
  }, [cheatEnabled]);

  const handleBossTransition = useCallback(() => setStatus(GameStatus.BOSS_TRANSITION), []);
  const handleBossDeath = useCallback(() => setIsVictoryPhase(true), []);
  const handleBossEncounter = useCallback(() => { setStatus(GameStatus.BOSS_INTRO); const pool = BOSS_DIALOGUE.INTRO_QUOTES[selectedStage || ''] || BOSS_DIALOGUE.INTRO_QUOTES['default']; const taunt = pool[1] || pool[0]; setBossTaunt(taunt); }, [selectedStage]);

  const handleBossDefeated = useCallback((stageId: string) => {
    const newWeapon = BOSS_WEAPON_MAP[stageId];
    if (newWeapon) {
      setAvailableWeapons(prev => {
        const next = prev.includes(newWeapon) ? prev : [...prev, newWeapon];
        return [...next].sort((a, b) => WEAPON_ORDER.indexOf(a) - WEAPON_ORDER.indexOf(b));
      });
    }
    setDefeatedStages(prev => [...prev, stageId]);
    const speech = VULGARITIES.LOCAL_VICTORY[Math.floor(Math.random() * VULGARITIES.LOCAL_VICTORY.length)];
    setVictorySpeech(speech); setStatus(GameStatus.BOSS_VICTORY_SPEECH);
  }, []);

  const handleGameOver = useCallback((victory: boolean) => { 
    if ('speechSynthesis' in window) window.speechSynthesis.cancel();
    if (!victory) { setIsVictoryPhase(false); setStatus(GameStatus.GAME_OVER); } 
  }, []);
  const handlePlayerUpdate = useCallback((h: number, sc: number, st: number, ammo?: Record<WeaponType, number>, forcedWeapon?: WeaponType) => { setHealth(h); setSpecialCharges(sc); setSpecialChargeTimer(st); if (ammo) setWeaponAmmo(ammo); if (forcedWeapon) setCurrentWeapon(forcedWeapon); }, []);
  const handleIntroComplete = useCallback(() => setStatus(GameStatus.PLAYING), []);

  useEffect(() => {
    let frameId: number;
    const poll = () => {
      const gamepads = navigator.getGamepads();
      const gp = gamepads[0];
      if (gp) {
        const now = Date.now();
        const currentStatus = statusRef.current;
        const currentIdx = selectedIndexRef.current;
        const numW = availableWeaponsRef.current.length;
        const useTwoRows = numW > 4;
        const topRowSize = useTwoRows ? Math.ceil(numW / 2) : numW;

        if (now - lastPadInputRef.current > 200) {
            let dx = 0, dy = 0;
            if (gp.axes[0] < -0.5 || gp.buttons[14]?.pressed) dx = -1;
            if (gp.axes[0] > 0.5 || gp.buttons[15]?.pressed) dx = 1;
            if (gp.axes[1] < -0.5 || gp.buttons[12]?.pressed) dy = -1;
            if (gp.axes[1] > 0.5 || gp.buttons[13]?.pressed) dy = 1;

            if (currentStatus === GameStatus.STAGE_SELECT) {
              if (dx !== 0) { setSelectedIndex(prev => (prev % 2 === 0 ? prev + 1 : prev - 1)); lastPadInputRef.current = now; }
              if (dy !== 0) { setSelectedIndex(prev => (prev < 2 ? prev + 2 : prev - 2)); lastPadInputRef.current = now; }
            } else if (currentStatus === GameStatus.PAUSED) {
              if (dy < -0.3) { 
                setSelectedIndex(p => {
                  if (p >= numW) return p - 1;
                  if (useTwoRows && p >= topRowSize) return p - topRowSize;
                  return p;
                });
                lastPadInputRef.current = now; 
              } 
              else if (dy > 0.3) { 
                setSelectedIndex(p => {
                  if (useTwoRows && p < topRowSize && p + topRowSize < numW) return p + topRowSize;
                  if (p < numW) return numW;
                  if (p < numW + 2) return p + 1;
                  return p;
                });
                lastPadInputRef.current = now; 
              }
              else if (dx < -0.3 && currentIdx < numW) {
                setSelectedIndex(p => p > 0 ? p - 1 : p);
                lastPadInputRef.current = now;
              }
              else if (dx > 0.3 && currentIdx < numW) {
                setSelectedIndex(p => p < numW - 1 ? p + 1 : p);
                lastPadInputRef.current = now;
              }
            }
        }

        const aPressed = gp.buttons[0]?.pressed; 
        const bPressed = gp.buttons[1]?.pressed; 
        const startPressed = gp.buttons[9]?.pressed;
        const lbPressed = gp.buttons[4]?.pressed;
        const rbPressed = gp.buttons[5]?.pressed;

        if (aPressed && !lastAStateRef.current) {
            if (currentStatus === GameStatus.START || currentStatus === GameStatus.VICTORY || currentStatus === GameStatus.GAME_OVER || currentStatus === GameStatus.BOSS_INTRO || currentStatus === GameStatus.BOSS_VICTORY_SPEECH) {
              handleStart();
            } else if (currentStatus === GameStatus.STAGE_SELECT) {
              handleSelectStage(STAGES(progressionRankRef.current)[currentIdx].id);
            } else if (currentStatus === GameStatus.PAUSED) {
              if (currentIdx < numW) {
                selectWeaponByIndex(currentIdx);
              } else if (currentIdx === numW) {
                handleResume();
              } else if (currentIdx === numW + 1) {
                handleBossSelect();
              } else if (currentIdx === numW + 2) {
                handleQuitToMenu();
              }
            }
        }
        if (bPressed && !lastBStateRef.current) { 
          if (currentStatus === GameStatus.PAUSED) handleResume(); 
          else if (currentStatus === GameStatus.STAGE_SELECT) setStatus(GameStatus.START); 
        }
        if (startPressed && !lastStartStateRef.current) { if (currentStatus === GameStatus.START) handleStart(); else if (currentStatus === GameStatus.PLAYING || currentStatus === GameStatus.PAUSED) togglePause(); }
        if (currentStatus === GameStatus.PLAYING) { if (lbPressed && !lastLBStateRef.current) cycleWeapon(-1); if (rbPressed && !lastRBStateRef.current) cycleWeapon(1); }

        lastAStateRef.current = !!aPressed; lastBStateRef.current = !!bPressed; lastStartStateRef.current = !!startPressed; lastLBStateRef.current = !!lbPressed; lastRBStateRef.current = !!rbPressed;
      }
      frameId = requestAnimationFrame(poll);
    };
    frameId = requestAnimationFrame(poll);
    return () => cancelAnimationFrame(frameId);
  }, [handleStart, handleSelectStage, handleResume, handleBossSelect, handleQuitToMenu, togglePause, cycleWeapon, selectWeaponByIndex]);

  return (
    <div className="relative w-screen h-screen flex items-center justify-center bg-black overflow-hidden">
      <div className="relative shadow-2xl border-4 border-gray-800 bg-[#121212] box-content" style={{ width: 800, height: 600 }}>
        {(status === GameStatus.LEVEL_INTRO || status === GameStatus.PLAYING || status === GameStatus.BOSS_TRANSITION || status === GameStatus.PAUSED || status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH) && (
          <HUD health={health} maxHealth={INITIAL_PLAYER_HEALTH} specialCharges={specialCharges} specialChargeTimer={specialChargeTimer} maxChargeTimer={SPECIAL_CHARGE_REGEN_FRAMES} currentWeapon={currentWeapon} ammo={weaponAmmo[currentWeapon]} maxAmmo={MAX_AMMO[currentWeapon]} />
        )}
        <Overlay 
          status={status} 
          onStart={handleStart} 
          onResume={handleResume} 
          onBossSelect={handleBossSelect} 
          onQuitToMenu={handleQuitToMenu} 
          onSelectStage={handleSelectStage} 
          onIconClick={handleIconClick}
          onCheatAllWeapons={handleToggleCheat} 
          onToggleInvincibility={handleToggleInvincibility} 
          onToggleInfiniteAmmo={handleToggleInfiniteAmmo} 
          onToggleInfinitePower={handleToggleInfinitePower} 
          onToggleJumpToBoss={handleToggleJumpToBoss} 
          onIncrementRank={handleIncrementRank} 
          onDecrementRank={handleDecrementRank} 
          progressionRank={progressionRank} 
          cheatEnabled={cheatEnabled} 
          invincibilityEnabled={invincibilityEnabled} 
          infiniteAmmoEnabled={infiniteAmmoEnabled} 
          infinitePowerEnabled={infinitePowerEnabled} 
          jumpToBossEnabled={jumpToBossEnabled} 
          showCheats={SHOW_CHEATS} 
          bossTaunt={bossTaunt} 
          victorySpeech={victorySpeech} 
          briefing={briefing} 
          defeatedStages={defeatedStages} 
          selectedIndex={selectedIndex} 
          overlayActiveTime={overlayActiveTime} 
          stageId={selectedStage} 
          availableWeapons={availableWeapons}
          currentWeapon={currentWeapon}
        />
        <GameCanvas status={status} stageId={selectedStage} onPlayerUpdate={handlePlayerUpdate} onBossEncounter={handleBossEncounter} onBossTransition={handleBossTransition} onBossDefeated={handleBossDefeated} onBossDeath={handleBossDeath} onBossSelect={handleBossSelect} onGameOver={handleGameOver} onIntroComplete={handleIntroComplete} onTogglePause={togglePause} currentWeapon={currentWeapon} initialAmmo={weaponAmmo} invincibilityEnabled={invincibilityEnabled && (SHOW_CHEATS)} infiniteAmmoEnabled={infiniteAmmoEnabled && (SHOW_CHEATS)} infinitePowerEnabled={infinitePowerEnabled && (SHOW_CHEATS)} jumpToBossEnabled={jumpToBossEnabled && (SHOW_CHEATS)} bossTauntText={bossTaunt} />
      </div>
    </div>
  );
};

