          <rect width="100" height="100" fill="#1C1C1C" />
          <path d="M10 100 L30 40 L70 40 L90 100" fill="#6E2C00" stroke="black" strokeWidth="2" />
          <rect x="30" y="25" width="40" height="45" fill="#e0ac69" stroke="black" strokeWidth="2" />
          <rect x="40" y="40" width="6" height="6" fill="black" />
          <rect x="54" y="40" width="6" height="6" fill="black" />
