      );
    case 'Hector Hurricane':
      return (
        <svg viewBox="0 0 100 100" className="w-full h-full">
          <rect width="100" height="100" fill="#0E2F44" />
          <path d="M20 90 C 20 50, 80 50, 80 90" fill="#16A085" stroke="black" strokeWidth="2" />
          <circle cx="50" cy="45" r="26" fill="#f1c27d" stroke="black" strokeWidth="2" />
          <rect x="35" y="42" width="30" height="8" rx="4" fill="#00FFFF" stroke="black" />
