        case 'Victor Volcano': utterance.pitch = 0.7; utterance.rate = 0.85; break;
        case 'Ernie Earthquake': utterance.pitch = 0.1; utterance.rate = 0.55; break;
        case 'Hector Hurricane': utterance.pitch = 1.2; utterance.rate = 1.5; break;
        case 'Blackout Barry': utterance.pitch = 1.4; utterance.rate = 1.1; break;
        default: utterance.pitch = 1.0; utterance.rate = 1.0;
      }
      utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  }, []);

  useEffect(() => {
    if (status === GameStatus.BOSS_INTRO && selectedStage && bossTaunt) {
      speakBossTaunt(selectedStage, bossTaunt);
    }
  }, [status, selectedStage, bossTaunt, speakBossTaunt]);

  const cycleWeapon = useCallback((dir: number) => {
    setAvailableWeapons(prevAvailable => {
      if (prevAvailable.length <= 1) return prevAvailable;
      setCurrentWeapon(current => {
        const idx = prevAvailable.indexOf(current);
        const nextIdx = (idx + dir + prevAvailable.length) % prevAvailable.length;
        return prevAvailable[nextIdx];
      });
      return prevAvailable;
    });
  }, []);

  const selectWeaponByIndex = useCallback((index: number) => {
    setAvailableWeapons(prev => {
      if (index >= 0 && index < prev.length) {
        setCurrentWeapon(prev[index]);
      }
      return prev;
    });
  }, []);

  const handleIconClick = useCallback((index: number) => {
    setSelectedIndex(index);
    selectWeaponByIndex(index);
  }, [selectWeaponByIndex]);

  const speakRebuke = useCallback(() => {
    if ('speechSynthesis' in window) {
      if (window.speechSynthesis.speaking) return;
      if (meatheadSpeechCooldownRef.current > 0) return;
      const text = VULGARITIES.REBUKE[Math.floor(Math.random() * VULGARITIES.REBUKE.length)];
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1; utterance.rate = 1.1; utterance.volume = 1.0;
      utterance.onend = () => { meatheadSpeechCooldownRef.current = 1000; };
      utterance.onerror = () => { meatheadSpeechCooldownRef.current = 1000; };
      window.speechSynthesis.speak(utterance);
    }
  }, []);

  const togglePause = useCallback(() => {
    setStatus(prev => {
      if (isVictoryPhase || prev === GameStatus.BOSS_TRANSITION || prev === GameStatus.BOSS_INTRO || prev === GameStatus.BOSS_VICTORY_SPEECH || prev === GameStatus.LEVEL_INTRO || prev === GameStatus.VICTORY) return prev;
      if (prev === GameStatus.PLAYING) { 
        setSelectedIndex(availableWeaponsRef.current.indexOf(currentWeapon));
        return GameStatus.PAUSED; 
      }
      if (prev === GameStatus.PAUSED) return GameStatus.PLAYING;
      return prev;
    });
  }, [isVictoryPhase, currentWeapon]);

  const handleStart = useCallback(() => {
    if (overlayActiveTime < 2000) return;
    if (status === GameStatus.VICTORY || status === GameStatus.GAME_OVER) {
      if ('speechSynthesis' in window) window.speechSynthesis.cancel();
      // RESET HEALTH AND AMMO ON RESTART
      setHealth(INITIAL_PLAYER_HEALTH);
      setWeaponAmmo(resetAmmo());

      if (progressionRank === 0 && defeatedStages.length >= 4) {
        setProgressionRank(1); 
        setDefeatedStages([]); 
        setAvailableWeapons(SET0_WEAPONS.sort((a,b) => WEAPON_ORDER.indexOf(a) - WEAPON_ORDER.indexOf(b))); 
        setCurrentWeapon('GUN'); 
        setStatus(GameStatus.STAGE_SELECT);
      } else {
        setDefeatedStages([]); 
        const weaponsToStart: WeaponType[] = (cheatEnabled && SHOW_CHEATS) ? ALL_WEAPONS_CHEAT : (progressionRank === 1 ? SET0_WEAPONS : ['GUN'] as WeaponType[]); 
        setAvailableWeapons([...weaponsToStart].sort((a,b) => WEAPON_ORDER.indexOf(a) - WEAPON_ORDER.indexOf(b))); 
        setCurrentWeapon('GUN'); 
        setSelectedIndex(0); 
        setIsVictoryPhase(false); 
        setStatus(GameStatus.START);
      }
    } else if (status === GameStatus.START) {
      const weaponsToStart: WeaponType[] = (cheatEnabled && SHOW_CHEATS) ? ALL_WEAPONS_CHEAT : (progressionRank === 1 ? SET0_WEAPONS : ['GUN'] as WeaponType[]); 
      setAvailableWeapons([...weaponsToStart].sort((a,b) => WEAPON_ORDER.indexOf(a) - WEAPON_ORDER.indexOf(b))); 
      setCurrentWeapon('GUN'); 
      setWeaponAmmo(resetAmmo()); 
      setStatus(GameStatus.STAGE_SELECT);
    } else if (status === GameStatus.BOSS_INTRO) {
      setStatus(GameStatus.PLAYING);
    } else if (status === GameStatus.BOSS_VICTORY_SPEECH) {
      if ('speechSynthesis' in window) window.speechSynthesis.cancel();
      setIsVictoryPhase(false);
      if (defeatedStages.length >= 4) { setStatus(GameStatus.VICTORY); } 
      else { 
        setStatus(GameStatus.STAGE_SELECT); 
        setSelectedStage(null); 
        setSelectedIndex(0); 
        setCurrentWeapon('GUN'); 
        setWeaponAmmo(resetAmmo()); 
      }
    }
  }, [status, defeatedStages, overlayActiveTime, cheatEnabled, progressionRank, resetAmmo]);

  const handleResume = useCallback(() => { setStatus(GameStatus.PLAYING); }, []);

  const handleBossSelect = useCallback(() => {
    if ('speechSynthesis' in window) window.speechSynthesis.cancel();
    setSelectedStage(null); setSelectedIndex(0); setIsVictoryPhase(false); setCurrentWeapon('GUN'); setStatus(GameStatus.STAGE_SELECT); setWeaponAmmo(resetAmmo());
  }, [resetAmmo]);

  const handleQuitToMenu = useCallback(() => { 
    if ('speechSynthesis' in window) window.speechSynthesis.cancel();
    setSelectedStage(null); setSelectedIndex(0); setIsVictoryPhase(false); setDefeatedStages([]); setCurrentWeapon('GUN'); setProgressionRank(0); setStatus(GameStatus.START); 
  }, []);

  const handleSelectStage = useCallback((stage: string) => {
    if (defeatedStages.includes(stage)) { speakRebuke(); return; }
    if ('speechSynthesis' in window) window.speechSynthesis.cancel();
    setSelectedStage(stage); 
    setHealth(INITIAL_PLAYER_HEALTH); 
    setSpecialCharges(2); 
    setSpecialChargeTimer(0); 
    setCurrentWeapon('GUN'); 
    setWeaponAmmo(resetAmmo()); 
    setIsVictoryPhase(false); 
    setStatus(GameStatus.LEVEL_INTRO);
  }, [defeatedStages, speakRebuke, resetAmmo]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const key = e.key.toLowerCase();
      if (key === 'escape') togglePause();

      if (status === GameStatus.PAUSED || status === GameStatus.STAGE_SELECT) {
        const numW = availableWeapons.length;
        const useTwoRows = numW > 4;
        const topRowSize = useTwoRows ? Math.ceil(numW / 2) : numW;
        const bottomRowSize = useTwoRows ? Math.floor(numW / 2) : 0;

        if (key === 'arrowup' || key === 'w') { 
          if (status === GameStatus.PAUSED) {
            setSelectedIndex(p => {
              if (p >= numW) return p - 1; 
              if (useTwoRows && p >= topRowSize) return p - topRowSize; 
              return p;
            });
          }
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p - 2 + 4) % 4); 
        } 
        else if (key === 'arrowdown' || key === 's') { 
          if (status === GameStatus.PAUSED) {
            setSelectedIndex(p => {
              if (useTwoRows && p < topRowSize && p + topRowSize < numW) return p + topRowSize; 
              if (p < numW) return numW; 
              if (p < numW + 2) return p + 1; 
              return p;
            });
          }
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p + 2) % 4); 
        } 
        else if (key === 'arrowleft' || key === 'a') { 
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p % 2 === 0 ? p + 1 : p - 1));
          if (status === GameStatus.PAUSED && selectedIndex < numW) {
            setSelectedIndex(p => p > 0 ? p - 1 : p);
          }
        } 
        else if (key === 'arrowright' || key === 'd') { 
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p % 2 === 0 ? p + 1 : p - 1));
          if (status === GameStatus.PAUSED && selectedIndex < numW - 1) {
             setSelectedIndex(p => p + 1);
          }
        }
        else if (key === 'enter' || key === ' ') {
          if (status === GameStatus.START) handleStart();
          else if (status === GameStatus.STAGE_SELECT) {
             const stages = STAGES(progressionRank);
             if (selectedIndex >= 0 && selectedIndex < stages.length) {
                handleSelectStage(stages[selectedIndex].id);
             }
          }
          else if (status === GameStatus.PAUSED) {
             if (selectedIndex < availableWeapons.length) {
                selectWeaponByIndex(selectedIndex);
                togglePause();
             } else {
                const action = selectedIndex - availableWeapons.length;
                if (action === 0) togglePause();
                if (action === 1) handleBossSelect();
                if (action === 2) handleQuitToMenu();
             }
          }
          else if (status === GameStatus.GAME_OVER || status === GameStatus.VICTORY) {
             handleStart();
          }
        }
      } else if (status === GameStatus.START || status === GameStatus.GAME_OVER || status === GameStatus.VICTORY || status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH) {
         if (key === 'enter' || key === ' ') {
           handleStart();
         }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [status, availableWeapons, selectedIndex, progressionRank, handleStart, handleResume, handleBossSelect, handleQuitToMenu, handleSelectStage, selectWeaponByIndex, togglePause]);

  const handlePlayerUpdate = useCallback((newHealth: number, charges: number, chargeTimer: number, ammo?: Record<WeaponType, number>, forcedWeapon?: WeaponType) => {
    setHealth(newHealth);
    setSpecialCharges(charges);
    setSpecialChargeTimer(chargeTimer);
    if (ammo) setWeaponAmmo(ammo);
    if (forcedWeapon && forcedWeapon !== currentWeapon) setCurrentWeapon(forcedWeapon);
  }, [currentWeapon]);

  const handleBossEncounter = useCallback(() => {
    setStatus(GameStatus.BOSS_INTRO);
  }, []);

  const handleBossTransition = useCallback(() => {
    setStatus(GameStatus.BOSS_TRANSITION);
  }, []);

  const handleBossDeath = useCallback(() => {
     // Optional logic if app needs to know immediately
  }, []);

  const handleBossDefeated = useCallback((stageId: string) => {
    if (!defeatedStages.includes(stageId)) {
      setDefeatedStages(prev => [...prev, stageId]);
    }
    const newWeapon = BOSS_WEAPON_MAP[stageId];
    if (newWeapon) {
       setAvailableWeapons(prev => {
         if (!prev.includes(newWeapon)) {
           return [...prev, newWeapon].sort((a,b) => WEAPON_ORDER.indexOf(a) - WEAPON_ORDER.indexOf(b));
         }
         return prev;
       });
    }
    setStatus(GameStatus.BOSS_VICTORY_SPEECH);
    setIsVictoryPhase(true);
  }, [defeatedStages]);

  const handleGameOver = useCallback((victory: boolean) => {
    setStatus(GameStatus.GAME_OVER);
  }, []);

  const handleIntroComplete = useCallback(() => {
    setStatus(GameStatus.PLAYING);
  }, []);

  return (
    <div className="relative w-screen h-screen flex items-center justify-center bg-black overflow-hidden">
      <div className="relative shadow-2xl border-4 border-gray-800 bg-[#121212] box-content" style={{ width: 800, height: 600 }}>
       <GameCanvas 
          status={status}
          stageId={selectedStage}
          onPlayerUpdate={handlePlayerUpdate}
          onBossEncounter={handleBossEncounter}
          onBossTransition={handleBossTransition}
          onBossDefeated={handleBossDefeated}
          onBossDeath={handleBossDeath}
          onBossSelect={handleBossSelect}
          onGameOver={handleGameOver}
          onIntroComplete={handleIntroComplete}
          onTogglePause={togglePause}
          currentWeapon={currentWeapon}
          initialAmmo={weaponAmmo}
          invincibilityEnabled={invincibilityEnabled}
          infiniteAmmoEnabled={infiniteAmmoEnabled}
          infinitePowerEnabled={infinitePowerEnabled}
          jumpToBossEnabled={jumpToBossEnabled}
          bossTauntText={bossTaunt}
       />

       {(status === GameStatus.PLAYING || status === GameStatus.BOSS_TRANSITION || status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH) && (
         <HUD 
            health={health}
            maxHealth={INITIAL_PLAYER_HEALTH}
            specialCharges={specialCharges}
            specialChargeTimer={specialChargeTimer}
            maxChargeTimer={SPECIAL_CHARGE_REGEN_FRAMES}
            currentWeapon={currentWeapon}
            ammo={weaponAmmo[currentWeapon]}
            maxAmmo={MAX_AMMO[currentWeapon]}
         />
       )}

       <Overlay 
          status={status}
          onStart={handleStart}
          onResume={handleResume}
          onBossSelect={handleBossSelect}
          onQuitToMenu={handleQuitToMenu}
          onSelectStage={handleSelectStage}
          onIconClick={handleIconClick}
          onCheatAllWeapons={() => setCheatEnabled(p => !p)}
          onToggleInvincibility={() => setInvincibilityEnabled(p => !p)}
          onToggleInfiniteAmmo={() => setInfiniteAmmoEnabled(p => !p)}
          onToggleInfinitePower={() => setInfinitePowerEnabled(p => !p)}
          onToggleJumpToBoss={() => setJumpToBossEnabled(p => !p)}
          onIncrementRank={() => setProgressionRank(p => p + 1)}
          onDecrementRank={() => setProgressionRank(p => Math.max(0, p - 1))}
          cheatEnabled={cheatEnabled}
          invincibilityEnabled={invincibilityEnabled}
          infiniteAmmoEnabled={infiniteAmmoEnabled}
          infinitePowerEnabled={infinitePowerEnabled}
          jumpToBossEnabled={jumpToBossEnabled}
          progressionRank={progressionRank}
          showCheats={SHOW_CHEATS}
          bossTaunt={bossTaunt}
          victorySpeech={victorySpeech}
          briefing={briefing}
          defeatedStages={defeatedStages}
          selectedIndex={selectedIndex}
          overlayActiveTime={overlayActiveTime}
          stageId={selectedStage}
          availableWeapons={availableWeapons}
          currentWeapon={currentWeapon}
       />
      </div>
    </div>
  );
};

export default App;

