        ctx.lineTo(player.pos.x + player.width/2 + 6, bubbleY + boxH);
        ctx.fill();
        ctx.stroke();
        ctx.fillStyle = 'white';
        ctx.fillRect(player.pos.x + player.width/2 - 5, bubbleY + boxH - 3, 10, 6);
        ctx.fillStyle = 'black'; 
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(text, player.pos.x + player.width/2, bubbleY + boxH/2); 
        ctx.textAlign = 'left'; 
        ctx.textBaseline = 'alphabetic';
    }
  }, []);

  // ... [Rest of file is standard] ...
  const draw = useCallback(() => {
    // ... [existing render code] ...
    if (!canvasRef.current) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;
    const state = gameStateRef.current;

    if (status === GameStatus.START || status === GameStatus.STAGE_SELECT) {
        ctx.fillStyle = COLORS.BG_DARK;
        ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
        return;
    }

    // Background
    ctx.fillStyle = (state.stageId && STAGE_COLORS[state.stageId]) ? STAGE_COLORS[state.stageId].bg : COLORS.BG_DARK;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    if (state.screenShakeTimer > 0) {
      const shake = Math.min(state.screenShakeTimer, SCREEN_SHAKE_MAX);
      const shakeX = (Math.random() - 0.5) * shake;
      const shakeY = (Math.random() - 0.5) * shake;
      ctx.translate(shakeX, shakeY);
    }

    ctx.save();
    ctx.translate(-state.camera.x, -state.camera.y);

    // Draw Blocks
    state.blocks.forEach(b => {
        if (b.type === 'wall' || b.type === 'ground') { ctx.fillStyle = (state.stageId && STAGE_COLORS[state.stageId]) ? STAGE_COLORS[state.stageId].ground : COLORS.GROUND; ctx.fillRect(b.x, b.y, b.w, b.h); } 
        else if (b.type === 'platform') { ctx.fillStyle = (state.stageId && STAGE_COLORS[state.stageId]) ? STAGE_COLORS[state.stageId].accent : '#555'; ctx.fillRect(b.x, b.y, b.w, b.h); } 
        else if (b.type === 'door') { ctx.fillStyle = '#333'; ctx.fillRect(b.x, b.y, b.w, b.h); if (state.doorState !== 'closed') { ctx.fillStyle = '#000'; ctx.fillRect(b.x, b.y + b.h - state.doorOpenAmount, b.w, state.doorOpenAmount); } }
    });

    // Draw Pickups
    state.pickups.forEach(p => {
        ctx.fillStyle = p.type.includes('health') ? '#FF0000' : '#FFFF00'; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); ctx.strokeStyle = '#FFF'; ctx.lineWidth = 2; ctx.strokeRect(p.pos.x, p.pos.y, p.width, p.height); ctx.fillStyle = '#FFF'; ctx.font = 'bold 10px Arial'; ctx.textAlign = 'center'; ctx.fillText(p.type.includes('health') ? '+' : 'A', p.pos.x + p.width/2, p.pos.y + p.height - 5);
    });

    // Draw Enemies
    state.enemies.forEach(e => {
        if (e.health <= 0 && !e.isBlownAway) return;
        if (e.type === 'boss') {
            BossLogic.drawBoss(ctx, e, state.stageId, state.frame);
            if (state.stageId === 'Drug Trade Dale') {
               BossLogic.drawDaleDrugs(ctx, e);
               BossLogic.drawDaleTruck(ctx, e);
            }
        } else {
             ctx.save(); ctx.translate(e.pos.x, e.pos.y); if (e.isBlownAway) ctx.rotate(e.rotation || 0);
             if (e.isTased) { ctx.translate(Math.random() * 4 - 2, Math.random() * 4 - 2); }
             if (e.needleCount && e.needleCount > 0) { ctx.filter = `hue-rotate(${state.frame * 15}deg) saturate(2)`; }
             if (e.enemyType === 'drone' || e.enemyType === 'flyer') ctx.fillStyle = COLORS.ENEMY_FLYER; else if (e.enemyType === 'tank' || e.enemyType === 'turret') ctx.fillStyle = COLORS.ENEMY_TANK; else if (e.enemyType === 'shield') ctx.fillStyle = COLORS.ENEMY_SHIELD;
             if (e.isOiled) ctx.fillStyle = '#3E2723'; if (e.frozenTimer && e.frozenTimer > 0) ctx.fillStyle = '#AED6F1';
             ctx.fillRect(0, 0, e.width, e.height);
             if (e.needleOffsets) { ctx.fillStyle = COLORS.PROJECTILE_DART; e.needleOffsets.forEach(off => { ctx.save(); ctx.translate(off.x, off.y); ctx.rotate(off.rot); ctx.fillRect(-2, -10, 4, 10); ctx.fillStyle = 'red'; ctx.fillRect(-1, -12, 2, 2); ctx.restore(); }); }
             if (e.enemyType === 'shield' && e.isShieldActive) { ctx.fillStyle = '#95A5A6'; ctx.fillRect(-5, 0, 5, e.height); }
             if (e.enemyType === 'flyer') { ctx.fillStyle = '#ccc'; const wingY = Math.sin(state.frame * 0.5) * 5; ctx.fillRect(-10, 5 + wingY, 10, 5); ctx.fillRect(e.width, 5 + wingY, 10, 5); }
             if (e.needleCount && e.needleCount > 0) { ctx.filter = 'none'; }
             ctx.restore();
        }
        if (e.isTased) { ctx.strokeStyle = '#00FFFF'; ctx.beginPath(); ctx.moveTo(e.pos.x, e.pos.y); ctx.lineTo(e.pos.x+e.width, e.pos.y+e.height); ctx.moveTo(e.pos.x+e.width, e.pos.y); ctx.lineTo(e.pos.x, e.pos.y+e.height); ctx.stroke(); }
        if (e.isOnFire || e.isPermasmolder) { ctx.fillStyle = e.isPermasmolder ? '#a00' : 'orange'; ctx.beginPath(); const rad = e.width * 0.6 + Math.sin(state.frame * 0.5) * 5; ctx.arc(e.pos.x+e.width/2, e.pos.y+e.height/2, rad, 0, Math.PI*2); ctx.fill(); }

        if (e.type === 'boss' && state.bossVulgarityTimer > 0 && state.bossLastVulgarity) { ctx.font = 'bold 12px monospace'; const text = state.bossLastVulgarity; const w = ctx.measureText(text).width; const x = e.pos.x + e.width/2 - w/2; const y = e.pos.y - 40; ctx.fillStyle = 'black'; ctx.fillRect(x - 5, y - 15, w + 10, 20); ctx.fillStyle = 'red'; ctx.fillText(text, x, y); }
    });

    drawPlayer(ctx);

    if (state.player.isTasing && state.player.taserTargetId) {
       const target = state.enemies.find((e: Enemy) => e.id === state.player.taserTargetId) || state.projectiles.find((p: Projectile) => p.id === state.player.taserTargetId);
       let tx = 0, ty = 0; if (target) { tx = target.pos.x + target.width/2; ty = target.pos.y + target.height/2; } else { tx = state.player.pos.x + state.player.width/2 + (state.player.facing * TASER_RANGE); ty = state.player.pos.y + state.player.height/2; }
       ctx.beginPath(); ctx.strokeStyle = COLORS.TASER_BOLT; ctx.lineWidth = 2; ctx.moveTo(state.player.pos.x + state.player.width/2, state.player.pos.y + state.player.height/2);
       const dist = Math.sqrt(Math.pow(tx - (state.player.pos.x+state.player.width/2), 2) + Math.pow(ty - (state.player.pos.y+state.player.height/2), 2));
       const segs = Math.floor(dist / 10); let cx = state.player.pos.x + state.player.width/2, cy = state.player.pos.y + state.player.height/2;
       for(let i=0; i<segs; i++) { cx += (tx - cx) / (segs - i); cy += (ty - cy) / (segs - i); ctx.lineTo(cx + (Math.random()-0.5)*10, cy + (Math.random()-0.5)*10); } ctx.lineTo(tx, ty); ctx.stroke();
    }

    state.projectiles.forEach(p => {
       if (p.isTsunami) return; 
       ctx.save(); ctx.translate(p.pos.x, p.pos.y); if (p.rotation) { ctx.translate(p.width/2, p.height/2); ctx.rotate(p.rotation); ctx.translate(-p.width/2, -p.height/2); }
       if (p.isBoulder) { ctx.fillStyle = '#5D4037'; ctx.beginPath(); ctx.arc(p.width/2, p.height/2, p.width/2, 0, Math.PI*2); ctx.fill(); } 
       else if (p.isIce || p.isShrapnel) { ctx.fillStyle = COLORS.PROJECTILE_ICE; ctx.fillRect(0, 0, p.width, p.height); } 
       else if (p.isDart) { ctx.fillStyle = COLORS.PROJECTILE_DART; ctx.fillRect(0, 0, p.width, p.height); } 
       else if (p.isOilRocket || p.isOilSplash) { ctx.fillStyle = '#1A110F'; ctx.fillRect(0, 0, p.width, p.height); if(p.isOilRocket) { ctx.fillStyle = 'red'; ctx.fillRect(p.width - 5, 2, 5, p.height - 4); } } 
       else if (p.isSludge) { ctx.fillStyle = '#2E7D32'; if (p.isLingering) { ctx.globalAlpha = 0.7; ctx.beginPath(); ctx.ellipse(p.width/2, p.height, p.width/2, p.height/2, 0, 0, Math.PI*2); ctx.fill(); ctx.globalAlpha = 1.0; } else { ctx.beginPath(); ctx.arc(p.width/2, p.height/2, p.width/2, 0, Math.PI*2); ctx.fill(); } } 
       else if (p.isMethBarrel) { ctx.fillStyle = '#111'; ctx.fillRect(0, 0, p.width, p.height); ctx.fillStyle = '#FFD700'; ctx.font = '8px monospace'; ctx.fillText("METH", 5, 25); } 
       else if (p.isCocaine) { ctx.fillStyle = '#FFFFFF'; ctx.fillRect(0, 0, p.width, p.height); } 
       else if (p.isPoop) { 
          ctx.fillStyle = '#5D4037'; 
          ctx.beginPath(); 
          ctx.ellipse(p.width/2, p.height/2, p.width/2, p.height/3, 0, 0, Math.PI*2);
          ctx.ellipse(p.width/2 - 10, p.height/2 + 5, 8, 6, 0.2, 0, Math.PI*2);
          ctx.ellipse(p.width/2 + 10, p.height/2 - 5, 8, 6, -0.2, 0, Math.PI*2);
          ctx.fill(); 
       } 
       else { ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY; ctx.fillRect(0, 0, p.width, p.height); }
       ctx.restore();
    });

    state.particles.forEach(p => { if (!p.isWater) { ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); } });
    state.damageNumbers.forEach(d => { ctx.fillStyle = d.isCritical ? '#FFD700' : 'white'; ctx.font = `bold ${d.isCritical ? '24px' : '16px'} Arial`; ctx.strokeStyle = 'black'; ctx.lineWidth = 3; ctx.strokeText(d.value.toString(), d.pos.x, d.pos.y); ctx.fillText(d.value.toString(), d.pos.x, d.pos.y); });

    // VISIBLE VOLCANOES
    state.bossVolcanoes.forEach(v => {
       ctx.fillStyle = '#8B4513';
       ctx.beginPath();
       ctx.moveTo(v.pos.x - 30, v.pos.y + 40);
       ctx.lineTo(v.pos.x + 30, v.pos.y + 40);
       ctx.lineTo(v.pos.x + 10, v.pos.y - 10);
       ctx.lineTo(v.pos.x - 10, v.pos.y - 10);
       ctx.fill();
       ctx.fillStyle = '#FF4500';
       ctx.beginPath();
       ctx.arc(v.pos.x, v.pos.y - 10, 10, 0, Math.PI, false);
       ctx.fill();
    });

    // Volcano Telegraphs
    state.bossVolcanoTelegraphs.forEach(t => {
       ctx.strokeStyle = '#FF4500'; ctx.lineWidth = 3; ctx.setLineDash([5, 5]);
       ctx.strokeRect(t.pos.x - 40, t.pos.y - 40, 80, 80);
       ctx.fillStyle = 'rgba(255, 69, 0, 0.3)';
       ctx.fillRect(t.pos.x - 40, t.pos.y - 40, 80, 80);
       ctx.fillStyle = 'white';
       ctx.font = '20px monospace';
       ctx.fillText('!', t.pos.x - 5, t.pos.y + 5);
       ctx.setLineDash([]);
    });

    // Poop Telegraphs
    state.bossPoopTelegraphs.forEach(t => {
       ctx.fillStyle = 'rgba(255, 0, 0, 0.5)';
       ctx.beginPath(); ctx.arc(t.pos.x, t.pos.y, 30, 0, Math.PI * 2); ctx.fill();
       ctx.strokeStyle = 'red'; ctx.lineWidth = 3; ctx.stroke();
       ctx.fillStyle = 'white';
       ctx.font = 'bold 24px monospace';
       ctx.fillText('WARNING', t.pos.x - 50, t.pos.y - 40);
       ctx.beginPath();
       const spawnLeft = t.spawnX === BOSS_DOOR_X;
       if (spawnLeft) {
          ctx.moveTo(t.pos.x - 20, t.pos.y); ctx.lineTo(t.pos.x + 20, t.pos.y); ctx.lineTo(t.pos.x + 10, t.pos.y - 10);
       } else {
          ctx.moveTo(t.pos.x + 20, t.pos.y); ctx.lineTo(t.pos.x - 20, t.pos.y); ctx.lineTo(t.pos.x - 10, t.pos.y - 10);
       }
       ctx.stroke();
    });

    const boss = state.enemies.find(e => e.type === 'boss');
    if (boss && boss.bossState === 'truck_incoming' && !boss.truckActive) {
       ctx.fillStyle = 'rgba(255, 255, 0, 0.5)';
       ctx.fillRect(state.camera.x, 350, CANVAS_WIDTH, 200);
       ctx.fillStyle = 'red';
       ctx.font = 'bold 40px "Press Start 2P"';
       ctx.textAlign = 'center';
       if (state.frame % 20 < 10) {
          ctx.fillText("TRUCK INCOMING!", state.camera.x + CANVAS_WIDTH/2, 300);
       }
    }

    state.bossSteamExplosions.forEach(e => { ctx.fillStyle = `rgba(255, 255, 255, ${e.life / 45 * 0.5})`; ctx.beginPath(); ctx.arc(e.pos.x, e.pos.y, e.radius, 0, Math.PI * 2); ctx.fill(); });

    ctx.restore();
    if (state.victoryString) { ctx.fillStyle = '#FFD700'; ctx.font = 'italic black 60px Arial'; ctx.textAlign = 'center'; ctx.fillText(state.victoryString, CANVAS_WIDTH/2, CANVAS_HEIGHT/2); }
    if (state.deathString) { ctx.fillStyle = '#FF0000'; ctx.font = 'italic black 60px Arial'; ctx.textAlign = 'center'; ctx.fillText(state.deathString, CANVAS_WIDTH/2, CANVAS_HEIGHT/2); }
  }, [status]);

  useEffect(() => {
    let animationFrameId: number;
    const loop = () => {
      if (status === GameStatus.PLAYING || status === GameStatus.LEVEL_INTRO || status === GameStatus.BOSS_TRANSITION || status === GameStatus.BOSS_VICTORY_SPEECH || status === GameStatus.BOSS_INTRO) {
        update();
      }
      draw();
      onPlayerUpdate(
        gameStateRef.current.player.health,
        gameStateRef.current.player.specialCharges,
        gameStateRef.current.player.specialChargeTimer,
        gameStateRef.current.player.weaponAmmo,
        gameStateRef.current.player.currentWeapon
      );
      animationFrameId = requestAnimationFrame(loop);
    };
    if (status === GameStatus.LEVEL_INTRO || status === GameStatus.START) {
        respawn();
    }
    loop();
    return () => cancelAnimationFrame(animationFrameId);
  }, [status, update, draw, onPlayerUpdate, respawn]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="w-full h-full object-contain bg-black" />;
};

export default GameCanvas;

import { 
  Player, Projectile, Vector2, WeaponType, Particle, Enemy, DamageNumber, Vector2 as Vec2
} from './types';
import { 
  BULLET_DAMAGE, BOULDER_DAMAGE, BOULDER_SPEED, SHOTGUN_DAMAGE, 
  SHOTGUN_COOLDOWN, SHOTGUN_FREEZE_TIME, FLAMETHROWER_DAMAGE, 
  FLAMETHROWER_RANGE, FLAMETHROWER_MAX_RANGE, FLAMETHROWER_RAMP_FRAMES,
  TSUNAMI_COOLDOWN, COLORS, PARTICLE_PALETTES,
  MAX_AMMO, TASER_RANGE, CANVAS_WIDTH, GUN_COOLDOWN, GUN_VELOCITY,
  BOULDER_COOLDOWN, SHOTGUN_PELLET_COUNT, NEEDLE_DAMAGE, NEEDLE_COOLDOWN,
  SLUDGE_DAMAGE, SLUDGE_COOLDOWN, FILTH_SHIELD_DURATION,
  OIL_ROCKET_DAMAGE, OIL_ROCKET_COOLDOWN, OIL_ROCKET_VELOCITY, OIL_SPLASH_COUNT,
  OIL_EXPLOSION_DAMAGE, OIL_EXPLOSION_RADIUS, OILED_DURATION,
  SLUDGE_PROJ_SIZE_MIN, SLUDGE_PROJ_SIZE_RAND, TSUNAMI_WAVE_SPEED,
  TSUNAMI_DAMAGE_BOSS, TSUNAMI_DAMAGE_WEAKNESS, ENEMY_HIT_COOLDOWN,
  TASER_AMMO_CONSUMPTION_RATE, TASER_TICK_RATE, TASER_DOT_DAMAGE, TASER_FIRE_THRESHOLD
} from './constants';
import * as BossLogic from './boss';

export interface WeaponHelpers {
  addProjectile: (p: Projectile) => void;
  addParticle: (p: Particle) => void;
  playGunSound: (type: 'gun' | 'ice' | 'flame' | 'tsunami' | 'dart' | 'horn' | 'ignite' | 'barf') => void;
  spawnExplosion: (pos: Vec2, color: string, count: number, baseVelX?: number, spread?: number) => void;
  spawnDamageNumber: (pos: Vec2, value: number | string, isCritical?: boolean) => void;
  spawnGlassShatter: (pos: Vec2) => void;
  spawnDeathShower: (pos: Vector2, facing: number, multiplier?: number) => void;
  spawnPickup: (pos: Vector2) => void;
  speakVulgarity: (category: any) => void;
  setScreenShake: (duration: number) => void;
  triggerBossDeath: (boss: Enemy, facing: number, wasWeakness: boolean) => void;
}

export const fireWeapon = (player: Player, state: any, helpers: WeaponHelpers, isMoveUp: boolean, isMoveDown: boolean, infiniteAmmo: boolean) => {
  const { currentWeapon, facing, pos, width, isDucking } = player;

  // Cooldown check is handled by caller usually, but double check here for safety
  if (player.shootCooldown > 0) return;

  const gunOffsetY = isDucking ? 42 : 18; 
  const shootX = pos.x + (facing === 1 ? width : -10);
  const shootY = pos.y + gunOffsetY;

  if (currentWeapon === 'GUN') {
    helpers.addProjectile({ id: `p-${Date.now()}`, pos: { x: shootX, y: shootY }, vel: { x: facing * GUN_VELOCITY, y: 0 }, width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'player' });
    player.shootCooldown = GUN_COOLDOWN; helpers.playGunSound('gun');
  } else if (currentWeapon === 'BOULDER') {
    if (!state.projectiles.some((p: Projectile) => p.owner === 'player' && p.isBoulder)) {
      const vy = isMoveUp ? -18 : 0; const vx = isMoveUp ? facing * (BOULDER_SPEED * 0.9) : facing * BOULDER_SPEED;
      helpers.addProjectile({ id: `b-${Date.now()}`, pos: { x: player.pos.x + (facing === 1 ? width : -40), y: pos.y + 20 }, vel: { x: vx, y: vy }, width: 48, height: 48, health: 1, maxHealth: 1, type: 'projectile', damage: BOULDER_DAMAGE, owner: 'player', isBoulder: true });
      player.shootCooldown = BOULDER_COOLDOWN; if (!infiniteAmmo) player.weaponAmmo['BOULDER']--;
    }
  } else if (currentWeapon === 'SHOTGUN') {
    for (let i = 0; i < SHOTGUN_PELLET_COUNT; i++) {
      const angle = (i - Math.floor(SHOTGUN_PELLET_COUNT/2)) * 0.15; const speed = 11 + Math.random() * 6;
      helpers.addProjectile({ id: `pellet-${Date.now()}-${i}`, pos: { x: shootX, y: shootY }, vel: { x: Math.cos(angle) * facing * speed, y: Math.sin(angle) * speed }, width: 10, height: 10, health: 1, maxHealth: 1, type: 'projectile', damage: SHOTGUN_DAMAGE, owner: 'player', isIce: true });
    }
    player.shootCooldown = SHOTGUN_COOLDOWN; helpers.playGunSound('ice'); if (!infiniteAmmo) player.weaponAmmo['SHOTGUN']--;
  } else if (currentWeapon === 'NEEDLES') {
    helpers.addProjectile({ id: `dart-${Date.now()}`, pos: { x: shootX, y: shootY }, vel: { x: facing * 24, y: (Math.random() - 0.5) * 5 }, width: 20, height: 4, health: 1, maxHealth: 1, type: 'projectile', damage: NEEDLE_DAMAGE, owner: 'player', isDart: true });
    player.shootCooldown = NEEDLE_COOLDOWN; helpers.playGunSound('dart'); if (!infiniteAmmo) player.weaponAmmo['NEEDLES']--;
  } else if (currentWeapon === 'OIL_ROCKET') {
    helpers.addProjectile({ 
      id: `oil-rocket-${Date.now()}`, 
      pos: { x: shootX, y: shootY - 10 }, 
      vel: { x: facing * OIL_ROCKET_VELOCITY, y: 0 }, 
      width: 50, height: 18, 
      health: 1, maxHealth: 1, 
      type: 'projectile', 
      damage: OIL_ROCKET_DAMAGE, 
      owner: 'player', 
      isOilRocket: true 
    });
    player.shootCooldown = OIL_ROCKET_COOLDOWN; 
    helpers.playGunSound('gun'); 
    if (!infiniteAmmo) player.weaponAmmo['OIL_ROCKET']--;
  } else if (currentWeapon === 'FLAMETHROWER') {
    // Handled in updateWeaponMechanics loop for continuous fire
  } else if (currentWeapon === 'SLUDGE') { 
    player.barfTimer = 24; player.shootCooldown = SLUDGE_COOLDOWN; player.filthShieldTimer = FILTH_SHIELD_DURATION; 
    if (!infiniteAmmo) player.weaponAmmo['SLUDGE']--; 
    helpers.playGunSound('barf'); 
  } else if (currentWeapon === 'TSUNAMI') { 
    if (!state.tsunamiActive) { 
      state.tsunamiActive = true; state.tsunamiDir = facing; state.tsunamiStartX = facing === 1 ? state.camera.x : state.camera.x + 800; state.tsunamiX = state.tsunamiStartX; 
      player.shootCooldown = TSUNAMI_COOLDOWN; helpers.playGunSound('tsunami'); 
      if (!infiniteAmmo) player.weaponAmmo['TSUNAMI']--; 
    } 
  } else if (currentWeapon === 'TASER') { 
    // Handled in updateWeaponMechanics loop
  }
};

export const updateWeaponMechanics = (
  player: Player,
  state: any,
  helpers: WeaponHelpers,
  inputs: { shootRequested: boolean; moveUp: boolean; moveDown: boolean; infiniteAmmo: boolean },
  stageId: string | null
) => {
  const { currentWeapon } = player;
  const hasAmmo = (wpn: WeaponType) => wpn === 'GUN' || player.weaponAmmo[wpn] >= 1;

  // 0. STANDARD FIRING (Semi-Automatic / Single Shot Logic)
  // These weapons fire once per press (or cooldown cycle) and don't need continuous state updates like Flamethrower/Taser
  if (inputs.shootRequested && player.shootCooldown <= 0) {
    if (currentWeapon === 'GUN' || 
        currentWeapon === 'BOULDER' || 
        currentWeapon === 'SHOTGUN' || 
        currentWeapon === 'NEEDLES' ||
        currentWeapon === 'OIL_ROCKET' ||
        currentWeapon === 'SLUDGE' ||
        currentWeapon === 'TSUNAMI') {

      if (hasAmmo(currentWeapon) || inputs.infiniteAmmo) {
        fireWeapon(player, state, helpers, inputs.moveUp, inputs.moveDown, inputs.infiniteAmmo);
      }
    }
  }

  // 1. ROCKET STEERING
  if (currentWeapon === 'OIL_ROCKET') {
    const steeringForce = 0.5;
    state.projectiles.forEach((p: Projectile) => {
      if (p.isOilRocket && p.owner === 'player') {
        if (inputs.moveUp) p.vel.y -= steeringForce;
        if (inputs.moveDown) p.vel.y += steeringForce;
        p.vel.y *= 0.96; 
      }
    });
  }

  // 2. SLUDGE BARF
  if (player.barfTimer && player.barfTimer > 0) {
    player.barfTimer--;
    if (player.barfTimer % 2 === 0) { 
       const gunOffsetY = player.isDucking ? 42 : 18;
       const shootX = player.pos.x + (player.facing === 1 ? player.width : -10);
       const shootY = player.pos.y + gunOffsetY;
       helpers.addProjectile({ 
         id: `sludge-part-${Date.now()}-${player.barfTimer}`, 
         pos: { x: shootX, y: shootY }, 
         vel: { 
           x: player.facing * (11 + Math.random() * 8), 
           y: -3 - Math.random() * 9 
         }, 
         width: SLUDGE_PROJ_SIZE_MIN + Math.random() * SLUDGE_PROJ_SIZE_RAND, 
         height: SLUDGE_PROJ_SIZE_MIN + Math.random() * SLUDGE_PROJ_SIZE_RAND, 
         health: 1, maxHealth: 1, 
         type: 'projectile', damage: SLUDGE_DAMAGE, owner: 'player', isSludge: true, life: 150 
       });
    }
  }

  // 3. TSUNAMI
  if (state.tsunamiActive) {
    state.tsunamiX += TSUNAMI_WAVE_SPEED * state.tsunamiDir; 
    const dist = Math.abs(state.tsunamiX - state.tsunamiStartX);
    const totalDist = CANVAS_WIDTH * 1.5;
    const progress = dist / totalDist;
    const tsunamiTopY = Math.pow(Math.min(1.0, dist / (CANVAS_WIDTH * 1.25)), 0.6) * 560;
    const waveHeight = 600 - tsunamiTopY;
    const bendMult = 120;
    const dir = state.tsunamiDir;
    const density = 35;

    for (let i = 0; i <= density; i++) {
      const yPct = i / density;
      const yPos = tsunamiTopY + (yPct * waveHeight);
      const normalizedY = (yPct - 0.5) * 2;
      const xOffset = (normalizedY * normalizedY) * bendMult * dir;
      const px = state.tsunamiX + xOffset;
      const py = yPos;
      helpers.addParticle({ pos: { x: px + (Math.random() - 0.5) * 40, y: py + (Math.random() - 0.5) * 15 }, vel: { x: (TSUNAMI_WAVE_SPEED * 0.4 + Math.random() * 8) * dir, y: (Math.random() - 0.5) * 4 }, life: 12 + Math.random() * 18, color: PARTICLE_PALETTES.WATER[Math.floor(PARTICLE_PALETTES.WATER.length * Math.random())], size: 8 + Math.random() * 12, isWater: true });
      if (i < 3 && Math.random() > 0.4) helpers.addParticle({ pos: { x: px, y: py }, vel: { x: (TSUNAMI_WAVE_SPEED * 0.9) * dir, y: (Math.random() - 0.5) * 10 }, life: 20 + Math.random() * 10, color: '#FFFFFF', size: 5 + Math.random() * 5, isWater: true });
    }

    if (stageId === 'Victor Volcano') state.bossVolcanoes = state.bossVolcanoes.filter((v: any) => { if (Math.abs(v.pos.x - state.tsunamiX) < 60) { state.bossSteamExplosions.push({ pos: { ...v.pos }, life: 45, radius: 100 }); (helpers as any).spawnSteamExplosionParticles(v.pos, 40); helpers.setScreenShake(12); return false; } return true; });

    state.projectiles.forEach((p: Projectile) => { 
      if (p.isMethBarrel && p.health > 0) { 
        if (Math.abs(p.pos.x + p.width / 2 - state.tsunamiX) < 120) { 
          p.vel = { x: state.tsunamiDir * 20, y: -10 }; 
          p.rotation = (p.rotation || 0) + 0.5; 
          p.health -= TSUNAMI_DAMAGE_BOSS; 
          helpers.spawnDamageNumber(p.pos, TSUNAMI_DAMAGE_BOSS); 
        } 
      } 
    });

    state.enemies.forEach((e: Enemy) => { 
      if (e.health > 0 && !e.isBlownAway) { 
        const ebY = e.pos.y + e.height; 
        if (Math.abs(e.pos.x + e.width / 2 - state.tsunamiX) < 120 && ebY > tsunamiTopY) { 
          if (e.type === 'boss') { 
            if (state.arenaLocked && (!e.hitCooldown || e.hitCooldown <= 0)) { 
              const isW = BossLogic.checkIsWeakness(stageId, currentWeapon); 
              const dmg = isW ? TSUNAMI_DAMAGE_WEAKNESS : TSUNAMI_DAMAGE_BOSS; 
              e.health -= dmg; 
              e.hitCooldown = ENEMY_HIT_COOLDOWN; 
              helpers.spawnDamageNumber(e.pos, dmg, isW); 
              if (e.health <= 0) helpers.triggerBossDeath(e, state.tsunamiDir, isW); 
            } 
          } else { 
            e.health = 0; 
            e.isBlownAway = true; 
            e.vel = { x: state.tsunamiDir * 20, y: -10 }; 
            helpers.spawnDeathShower(e.pos, state.tsunamiDir); 
            helpers.spawnPickup(e.pos); 
            helpers.speakVulgarity('tsunami_kill'); 
            player.killSatisfactionTimer = 60; 
          } 
        } 
      } 
    });
    if (progress >= 1.0) state.tsunamiActive = false;
  }

  // 4. TASER & FLAMETHROWER (CONTINUOUS)
  if (currentWeapon === 'FLAMETHROWER' && inputs.shootRequested && (hasAmmo('FLAMETHROWER') || inputs.infiniteAmmo)) {
     fireWeapon(player, state, helpers, inputs.moveUp, inputs.moveDown, inputs.infiniteAmmo);
  } else if (currentWeapon === 'FLAMETHROWER') {
     player.flameTimer = 0; // Reset ramp up
  }

  if (currentWeapon === 'TASER' && inputs.shootRequested && (hasAmmo('TASER') || inputs.infiniteAmmo)) { 
    if (!player.isTasing) fireWeapon(player, state, helpers, inputs.moveUp, inputs.moveDown, inputs.infiniteAmmo); 
    if (player.isTasing) { 
      player.taserTimer = (player.taserTimer || 0) + 1; 
      if (!inputs.infiniteAmmo && state.frame % TASER_AMMO_CONSUMPTION_RATE === 0) player.weaponAmmo['TASER'] -= 1; 
      player.vel.x = 0; 
      if (player.weaponAmmo['TASER'] <= 0) { player.isTasing = false; player.taserTargetId = null; } 
      const target = (state.enemies.find((e: Enemy) => e.id === player.taserTargetId) || state.projectiles.find((p: Projectile) => p.id === player.taserTargetId)) as (Enemy | Projectile | undefined); 

      if (target && (target.pos.x + target.width < state.camera.x || target.pos.x > state.camera.x + CANVAS_WIDTH || target.health <= 0)) { 
         player.taserTargetId = null; 
      } 

      if (target && target.health > 0) { 
        const dx = (target.pos.x + target.width/2) - (player.pos.x + player.width/2); 
        const dy = (target.pos.y + target.height/2) - (player.pos.y + player.height/2); 
        const dist = Math.sqrt(dx*dx + dy*dy); 
        if (dist > TASER_RANGE + 100) { player.taserTargetId = null; } 
        else { 
          if (target.type === 'boss') { 
            const b = target as Enemy; 
            if (!b.hitCooldown || b.hitCooldown <= 0) { 
              const dmg = BossLogic.getBossDamage(b, stageId, currentWeapon); 
              const isW = BossLogic.checkIsWeakness(stageId, currentWeapon); 
              b.health -= dmg; b.hitCooldown = ENEMY_HIT_COOLDOWN; helpers.spawnDamageNumber(b.pos, dmg, isW); 
              if (b.health <= 0) helpers.triggerBossDeath(b, player.facing, isW); 
            } 
          } else { 
            target.isTased = true; 
            if (state.frame % TASER_TICK_RATE === 0) { 
              target.health -= TASER_DOT_DAMAGE; helpers.spawnDamageNumber(target.pos, TASER_DOT_DAMAGE); 
              if (target.health <= 0) { 
                if (target.type === 'enemy') { 
                  const e = target as Enemy; e.isBlownAway = true; e.vel = { x: (Math.random()-0.5)*10, y: -15 }; helpers.spawnDeathShower(e.pos, 0); helpers.spawnPickup(e.pos); helpers.speakVulgarity('taser_kill'); 
                } 
                player.taserTargetId = null; 
              } 
            } 
            if (player.taserTimer! >= TASER_FIRE_THRESHOLD && !target.isOnFire) { 
              target.isOnFire = true; 
              target.isPermasmolder = true; // Apply permanent heavy DOT
              helpers.playGunSound('ignite'); 
            } 
          } 
        } 
      } 
    } 
  } else { player.isTasing = false; player.taserTargetId = null; player.taserTimer = 0; }
};

import React, { useRef, useEffect, useCallback } from 'react';
