        if (state.frame % 3 === 0) spawnExplosion({ x: player.pos.x + (player.facing === 1 ? 0 : player.width), y: player.pos.y + player.height - 10 }, '#FFFFFF', 3, -player.facing * 5, 5);
    }
    if (player.isUppercutting) {
        player.chargeDuration--;
        if (player.chargeDuration <= 0 && player.vel.y > 0) player.isUppercutting = false;
        if (state.frame % 3 === 0) spawnExplosion({ x: player.pos.x + player.width / 2, y: player.pos.y + player.height }, '#FFFF00', 3, 0, 10);
    }

    // Apply Gravity & Physics
    if (!player.isCharging) player.vel.y += GRAVITY;
    player.vel.y = Math.min(player.vel.y, 15);

    // Collision Helpers
    const checkCollisionsX = (ent: any, blocks: any[]) => {
        for (const b of blocks) {
            if (b.type === 'pit') continue;
            if (ent.pos.x < b.x + b.w && ent.pos.x + ent.width > b.x && ent.pos.y < b.y + b.h && ent.pos.y + ent.height > b.y) {
                if (ent.vel.x > 0) { ent.pos.x = b.x - ent.width; ent.vel.x = 0; }
                else if (ent.vel.x < 0) { ent.pos.x = b.x + b.w; ent.vel.x = 0; }
            }
        }
    };
    const checkCollisionsY = (ent: any, blocks: any[]) => {
        ent.isGrounded = false;
        for (const b of blocks) {
             if (b.type === 'pit') continue;
             if (b.type === 'platform' && ent.vel.y < 0) continue;
             if (ent.pos.x < b.x + b.w && ent.pos.x + ent.width > b.x && ent.pos.y < b.y + b.h && ent.pos.y + ent.height > b.y) {
                 if (ent.vel.y >= 0) {
                     if (b.type === 'platform') {
                         if (ent.pos.y + ent.height - ent.vel.y <= b.y + 10 + Math.abs(ent.vel.y)) { 
                             ent.pos.y = b.y - ent.height; ent.vel.y = 0; ent.isGrounded = true; 
                         }
                     } else { ent.pos.y = b.y - ent.height; ent.vel.y = 0; ent.isGrounded = true; }
                 } else if (b.type !== 'platform') { ent.pos.y = b.y + b.h; ent.vel.y = 0; }
             }
        }
    };

    player.pos.x += player.vel.x;
    checkCollisionsX(player, blocks);
    player.pos.y += player.vel.y;
    checkCollisionsY(player, blocks);

    // Clamp Screen
    player.pos.x = Math.max(state.camera.x, Math.min(state.camera.x + CANVAS_WIDTH - player.width, player.pos.x));

    // Timers
    if (player.invincibilityTimer > 0) player.invincibilityTimer--;
    if (player.pushbackTimer > 0) player.pushbackTimer--;
    if (player.shootCooldown > 0) player.shootCooldown--;
    if (player.specialCharges < MAX_SPECIAL_CHARGES) {
        player.specialChargeTimer++;
        if (player.specialChargeTimer >= SPECIAL_CHARGE_REGEN_FRAMES) {
            player.specialCharges++; player.specialChargeTimer = 0;
        }
    }
    if (player.killSatisfactionTimer > 0) player.killSatisfactionTimer--;
    if (player.bossKillSatisfactionTimer > 0) player.bossKillSatisfactionTimer--;
    if (player.filthShieldTimer && player.filthShieldTimer > 0) player.filthShieldTimer--;
    if (player.questionMarkTimer && player.questionMarkTimer > 0) player.questionMarkTimer--;
    if (state.voiceLineCooldown > 0) state.voiceLineCooldown--;
    if (state.playerStunTimer > 0) state.playerStunTimer--;

    // Update Camera
    const targetCamX = Math.max(0, Math.min(stageId ? 8000 - CANVAS_WIDTH : 0, player.pos.x - CANVAS_WIDTH * 0.4));
    if (state.arenaLocked) { 
        state.camera.x += (BOSS_DOOR_X - state.camera.x) * 0.1; 
        if (Math.abs(state.camera.x - BOSS_DOOR_X) < 2) state.camera.x = BOSS_DOOR_X; 
    } else {
        state.camera.x += (targetCamX - state.camera.x) * 0.1;
    }

    // --- LOGIC HELPERS ---
    const bossHelpers: BossLogic.BossHelpers = {
      spawnDamageNumber, spawnDeathShower, onBossDeath, speakVulgarity, playGunSound, spawnExplosion, spawnSteamExplosionParticles, spawnPoopExplosion, spawnPowderExplosion, spawnMethExplosion, spawnGlassShatter,
      setBossVulgarity: (t, d) => { state.bossLastVulgarity = t; state.bossVulgarityTimer = d; },
      setScreenShake: (d) => { state.screenShakeTimer = d; },
      setErnieVibration: (d) => { state.ernieVibrationTimer = d; },
      setPlayerStun: (d) => { state.playerStunTimer = d; },
      addProjectile: (p) => state.projectiles.push(p),
      addVolcano: (v) => state.bossVolcanoes.push(v),
      clearVolcanoes: () => state.bossVolcanoes = [],
      addVolcanoTelegraph: (v) => state.bossVolcanoTelegraphs.push(v),
      clearVolcanoTelegraphs: () => state.bossVolcanoTelegraphs = [],
      addPoopTelegraph: (t) => state.bossPoopTelegraphs.push(t),
      clearPoopTelegraphs: () => state.bossPoopTelegraphs = [],
      setVictorWallSide: (side: number) => state.victorWallSide = side,
      setTsunamiActive: (active: boolean) => state.tsunamiActive = active
    };

    const weaponHelpers: WeaponLogic.WeaponHelpers = {
      addProjectile: (p) => state.projectiles.push(p),
      addParticle: (p) => state.particles.push(p),
      playGunSound,
      spawnExplosion,
      spawnDamageNumber,
      spawnGlassShatter,
      spawnDeathShower,
      spawnPickup,
      speakVulgarity,
      setScreenShake: (d) => state.screenShakeTimer = d,
      triggerBossDeath: (b, f, w) => BossLogic.triggerBossDeath(b, f, w, stageId, currentWeapon, state, bossHelpers)
    };

    const inputs = { shootRequested, moveUp, moveDown, infiniteAmmo: infiniteAmmoEnabled };
    WeaponLogic.updateWeaponMechanics(player, state, weaponHelpers, inputs, stageId);
    BossLogic.updateBossHazards(state, player, invincibilityEnabled, bossHelpers);

    // Update Enemies
    state.enemies = state.enemies.filter(e => {
        if (e.health <= 0 && !e.isBlownAway && e.type !== 'boss') return false;

        if (e.isBlownAway) {
            e.vel.y += GRAVITY; e.pos.x += e.vel.x; e.pos.y += e.vel.y; e.rotation = (e.rotation || 0) + 0.2;
            return e.pos.y < 800;
        }

        if (e.type === 'boss') {
            if (state.arenaLocked) {
                BossLogic.updateBossAI(e, stageId, player, currentWeapon, invincibilityEnabled, state, bossHelpers);
            }
        } else {
             // Basic Enemy AI
             const dist = Math.abs((player.pos.x + player.width/2) - (e.pos.x + e.width/2));
             if (dist < 800) {
                 if (e.frozenTimer && e.frozenTimer > 0) e.frozenTimer--;
                 else {
                     if (e.enemyType === 'flyer') {
                         e.pos.x += Math.sin(state.frame * 0.05) * 2;
                         if (Math.random() < 0.01) {
                             state.projectiles.push({ id: `ep-${Date.now()}`, pos: { x: e.pos.x, y: e.pos.y + 20 }, vel: { x: 0, y: 5 }, width: 10, height: 10, health: 1, maxHealth: 1, type: 'projectile', damage: 10, owner: 'enemy' });
                         }
                     } else if (e.enemyType === 'shield' || e.enemyType === 'tank') {
                         if (e.behavior === 'patrol') {
                            // Simple patrol logic could go here
                         }
                         if (Math.random() < 0.015) {
                            const dir = player.pos.x < e.pos.x ? -1 : 1;
                            state.projectiles.push({ id: `ep-${Date.now()}`, pos: { x: e.pos.x + (dir === 1 ? e.width : 0), y: e.pos.y + 20 }, vel: { x: dir * 6, y: 0 }, width: 10, height: 10, health: 1, maxHealth: 1, type: 'projectile', damage: 15, owner: 'enemy' });
                         }
                     }
                 }

                 // Collisions with Player (Contact Damage)
                 if (player.pos.x < e.pos.x + e.width && player.pos.x + player.width > e.pos.x &&
                     player.pos.y < e.pos.y + e.height && player.pos.y + player.height > e.pos.y) {
                         if (player.isCharging || player.isUppercutting) {
                             if (!e.hitCooldown || e.hitCooldown <= 0) {
                                 e.health -= (player.isCharging ? BOSS_CHARGE_DAMAGE : BOSS_UPPERCUT_DAMAGE);
                                 e.hitCooldown = 20;
                                 spawnDamageNumber(e.pos, player.isCharging ? BOSS_CHARGE_DAMAGE : BOSS_UPPERCUT_DAMAGE);
                                 if (e.health <= 0) {
                                     e.isBlownAway = true; e.vel = { x: player.facing * 15, y: -10 };
                                     speakVulgarity(player.isCharging ? 'charge_kill' : 'uppercut_kill');
                                 }
                             }
                         } else if (player.invincibilityTimer <= 0 && !invincibilityEnabled) {
                             player.health -= 15; player.invincibilityTimer = 60;
                             player.vel = { x: (player.pos.x < e.pos.x ? -1 : 1) * 10, y: -5 };
                             speakVulgarity('hurt');
                         }
                 }
             }
        }
        if (e.hitCooldown && e.hitCooldown > 0) e.hitCooldown--;
        return true;
    });

    // Update Projectiles
    state.projectiles = state.projectiles.filter(p => {
        p.life = (p.life !== undefined) ? p.life - 1 : 600;
        if (p.life <= 0) return false;

        p.vel.y += (p.isBoulder || p.isShrapnel || p.isMethBarrel || p.isSludge || p.isOilRocket || p.isOilSplash) ? GRAVITY : 0;
        p.pos.x += p.vel.x; p.pos.y += p.vel.y;

        // Block collision for projectiles
        if (p.isBoulder || p.isShrapnel || p.isMethBarrel || p.isSludge || p.isOilRocket || p.isOilSplash) {
            checkCollisionsY(p, blocks);
            if (p.isGrounded) {
                if (p.isOilRocket) {
                    spawnExplosion(p.pos, '#1A110F', 20, 0, 30);
                    spawnExplosion(p.pos, 'orange', 15, 0, 25);
                    playGunSound('ignite');
                    return false;
                }
                if (p.isSludge) {
                    p.vel.x = 0; p.isLingering = true;
                    // Sludge Pool Logic
                    return p.life > 0;
                }
                if (p.isBoulder) {
                    if (Math.abs(p.vel.y) > 2) p.vel.y *= -BOULDER_BOUNCE_DAMPING; else p.vel.y = 0;
                    p.vel.x *= 0.95;
                }
            }
        }

        // Projectile vs Player
        if (p.owner === 'enemy') {
            if (player.pos.x < p.pos.x + p.width && player.pos.x + player.width > p.pos.x &&
                player.pos.y < p.pos.y + p.height && player.pos.y + player.height > p.pos.y) {
                    if (player.invincibilityTimer <= 0 && !invincibilityEnabled) {
                        player.health -= p.damage; player.invincibilityTimer = 45;
                        spawnDamageNumber(player.pos, p.damage);
                        speakVulgarity('hurt');
                        return false;
                    }
            }
        }

        // Projectile vs Enemy collision is handled in `WeaponLogic` or simply here for basics
        if (p.owner === 'player') {
            for (const e of state.enemies) {
                if (e.health > 0 && !e.isBlownAway && 
                    p.pos.x < e.pos.x + e.width && p.pos.x + p.width > e.pos.x &&
                    p.pos.y < e.pos.y + e.height && p.pos.y + p.height > e.pos.y) {
                        if (!e.hitCooldown || e.hitCooldown <= 0) {
                            // Hit logic
                            e.health -= p.damage; e.hitCooldown = 10;
                            spawnDamageNumber(e.pos, p.damage);
                            if (e.health <= 0) {
                                e.isBlownAway = true; e.vel = { x: p.vel.x > 0 ? 10 : -10, y: -10 };
                                if (e.type === 'boss') BossLogic.triggerBossDeath(e, player.facing, false, stageId, currentWeapon, state, bossHelpers);
                                else speakVulgarity('gun_kill');
                            }
                            // Destroy projectile
                            if (!p.isBoulder && !p.isSludge && !p.isOilRocket) return false;
                        }
                }
            }
        }

        return true;
    });

    // Pickups
    state.pickups = state.pickups.filter(p => {
        p.vel.y += GRAVITY; p.pos.y += p.vel.y;
        checkCollisionsY(p, blocks);
        if (player.pos.x < p.pos.x + p.width && player.pos.x + player.width > p.pos.x &&
            player.pos.y < p.pos.y + p.height && player.pos.y + player.height > p.pos.y) {
                if (p.type === 'small_health') player.health = Math.min(player.maxHealth, player.health + HEALTH_PICKUP_SMALL);
                else if (p.type === 'large_health') player.health = Math.min(player.maxHealth, player.health + HEALTH_PICKUP_LARGE);
                else if (p.type === 'small_ammo' || p.type === 'large_ammo') {
                    // Refill logic
                }
                return false;
        }
        return true;
    });

    state.particles = state.particles.filter(p => { 
        if (!p.isStuck) { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; } 
        return p.life > 0; 
    });

    // PLAYER DEATH CHECK
    if ((player.health <= 0 || player.pos.y > 1000) && state.deathTimer <= 0) { 
        state.deathTimer = 180; 
        state.deathString = "YOU DIED"; 
        spawnDeathShower(player.pos, player.facing, 3); 
        speakVulgarity('death'); 
    }

    // Boss Status Pass
    const activeBoss = state.enemies.find(e => e.type === 'boss');
    const showBossHUD = activeBoss && state.arenaLocked && activeBoss.health > 0;

    const forced = state.shouldSyncWeapon ? 'GUN' as WeaponType : undefined; if (state.shouldSyncWeapon) state.shouldSyncWeapon = false;
    onPlayerUpdate(
        player.health, 
        player.specialCharges, 
        player.specialChargeTimer, 
        player.weaponAmmo, 
        forced,
        showBossHUD ? activeBoss.health : 0,
        activeBoss ? activeBoss.maxHealth : 0,
        stageId || ""
    );
  }, [status, stageId, onBossDefeated, currentWeapon, respawn, invincibilityEnabled, infiniteAmmoEnabled, infinitePowerEnabled, jumpToBossEnabled, bossTauntText, onPlayerUpdate, spawnDamageNumber, spawnDeathShower, speakVulgarity, playGunSound, spawnExplosion, spawnSteamExplosionParticles, spawnPoopExplosion, spawnPowderExplosion, spawnMethExplosion, spawnGlassShatter, onBossDeath, onIntroComplete, onBossEncounter, onBossTransition, onCycleWeapon, onTogglePause]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="w-full h-full object-contain bg-black" />;
};

