    let gx = 0, gy = 0, gJump = false, gShoot = false, gCharge = false, gCycleL = false, gCycleR = false, gPause = false;
    if (gp) {
       if (Math.abs(gp.axes[0]) > 0.3) gx = gp.axes[0];
       if (Math.abs(gp.axes[1]) > 0.3) gy = gp.axes[1];
       if (gp.buttons[12]?.pressed) gy = -1; // D-Pad Up
       if (gp.buttons[13]?.pressed) gy = 1; // D-Pad Down
       if (gp.buttons[14]?.pressed) gx = -1; // D-Pad Left
       if (gp.buttons[15]?.pressed) gx = 1; // D-Pad Right

       gJump = gp.buttons[0]?.pressed; // A
       gShoot = gp.buttons[2]?.pressed || gp.buttons[1]?.pressed; // X or B
       // Remapping: 
       // A=Jump, X/B=Shoot, RT=Charge, LB/RB=Cycle, Start=Pause
       gCharge = gp.buttons[7]?.pressed; // RT only for charge
       gCycleL = gp.buttons[4]?.pressed; // LB
       gCycleR = gp.buttons[5]?.pressed; // RB
       gPause = gp.buttons[9]?.pressed;

       // Handle discrete cycle events (debounce)
