    const moveUp = !playerIsStunned && player.pushbackTimer <= 0 && (km['w'] || km['arrowup'] || km['keyw'] || gy < -0.5);
    const moveLeft = !playerIsStunned && player.pushbackTimer <= 0 && ((km['a'] || km['arrowleft'] || km['keya']) || gx < -0.3);
    const moveRight = !playerIsStunned && player.pushbackTimer <= 0 && ((km['d'] || km['arrowright'] || km['keyd']) || gx > 0.3);
