                            }
                            // Destroy projectile
                            if (!p.isBoulder && !p.isSludge && !p.isOilRocket) return false;
                        }
                }
            }
        }

        return true;
    });

    // Pickups
    state.pickups = state.pickups.filter(p => {
        p.vel.y += GRAVITY; p.pos.y += p.vel.y;
        checkCollisionsY(p, blocks);
        if (player.pos.x < p.pos.x + p.width && player.pos.x + player.width > p.pos.x &&
            player.pos.y < p.pos.y + p.height && player.pos.y + player.height > p.pos.y) {
                if (p.type === 'small_health') player.health = Math.min(player.maxHealth, player.health + HEALTH_PICKUP_SMALL);
                else if (p.type === 'large_health') player.health = Math.min(player.maxHealth, player.health + HEALTH_PICKUP_LARGE);
                else if (p.type === 'small_ammo' || p.type === 'large_ammo') {
                    // Refill logic
                }
                return false;
        }
        return true;
    });

    state.particles = state.particles.filter(p => { 
        if (!p.isStuck) { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; } 
        return p.life > 0; 
    });

    // PLAYER DEATH CHECK
    if ((player.health <= 0 || player.pos.y > 1000) && state.deathTimer <= 0) { 
        state.deathTimer = 180; 
        state.deathString = "YOU DIED"; 
        spawnDeathShower(player.pos, player.facing, 3); 
        speakVulgarity('death'); 
