                    p.vel.x = 0; p.isLingering = true;
                    // Sludge Pool Logic
                    return p.life > 0;
                }
                if (p.isBoulder) {
                    if (Math.abs(p.vel.y) > 2) p.vel.y *= -BOULDER_BOUNCE_DAMPING; else p.vel.y = 0;
                    p.vel.x *= 0.95;
                }
            }
        }

        // Projectile vs Player
        if (p.owner === 'enemy') {
            if (player.pos.x < p.pos.x + p.width && player.pos.x + player.width > p.pos.x &&
                player.pos.y < p.pos.y + p.height && player.pos.y + player.height > p.pos.y) {
                    if (player.invincibilityTimer <= 0 && !invincibilityEnabled) {
                        player.health -= p.damage; player.invincibilityTimer = 45;
                        spawnDamageNumber(player.pos, p.damage);
                        speakVulgarity('hurt');
                        return false;
                    }
            }
        }

        // Projectile vs Enemy collision is handled in `WeaponLogic` or simply here for basics
        if (p.owner === 'player') {
            for (const e of state.enemies) {
                if (e.health > 0 && !e.isBlownAway && 
                    p.pos.x < e.pos.x + e.width && p.pos.x + p.width > e.pos.x &&
                    p.pos.y < e.pos.y + e.height && p.pos.y + p.height > e.pos.y) {
                        if (!e.hitCooldown || e.hitCooldown <= 0) {
                            // Hit logic
                            e.health -= p.damage; e.hitCooldown = 10;
                            spawnDamageNumber(e.pos, p.damage);
                            if (e.health <= 0) {
                                e.isBlownAway = true; e.vel = { x: p.vel.x > 0 ? 10 : -10, y: -10 };
                                if (e.type === 'boss') BossLogic.triggerBossDeath(e, player.facing, false, stageId, currentWeapon, state, bossHelpers);
                                else speakVulgarity('gun_kill');
                            }
                            // Destroy projectile
                            if (!p.isBoulder && !p.isSludge && !p.isOilRocket) return false;
                        }
                }
            }
        }

        return true;
    });

    // Pickups
    state.pickups = state.pickups.filter(p => {
        p.vel.y += GRAVITY; p.pos.y += p.vel.y;
        checkCollisionsY(p, blocks);
        if (player.pos.x < p.pos.x + p.width && player.pos.x + player.width > p.pos.x &&
            player.pos.y < p.pos.y + p.height && player.pos.y + player.height > p.pos.y) {
                if (p.type === 'small_health') player.health = Math.min(player.maxHealth, player.health + HEALTH_PICKUP_SMALL);
                else if (p.type === 'large_health') player.health = Math.min(player.maxHealth, player.health + HEALTH_PICKUP_LARGE);
                else if (p.type === 'small_ammo' || p.type === 'large_ammo') {
                    // Refill logic
                }
                return false;
        }
        return true;
    });

    state.particles = state.particles.filter(p => { 
        if (!p.isStuck) { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; } 
        return p.life > 0; 
    });

    // PLAYER DEATH CHECK
    if ((player.health <= 0 || player.pos.y > 1000) && state.deathTimer <= 0) { 
        state.deathTimer = 180; 
        state.deathString = "YOU DIED"; 
        spawnDeathShower(player.pos, player.facing, 3); 
        speakVulgarity('death'); 
    }

    // Boss Status Pass
    const activeBoss = state.enemies.find(e => e.type === 'boss');
    const showBossHUD = activeBoss && state.arenaLocked && activeBoss.health > 0;

    const forced = state.shouldSyncWeapon ? 'GUN' as WeaponType : undefined; if (state.shouldSyncWeapon) state.shouldSyncWeapon = false;
    onPlayerUpdate(
        player.health, 
        player.specialCharges, 
        player.specialChargeTimer, 
        player.weaponAmmo, 
        forced,
        showBossHUD ? activeBoss.health : 0,
        activeBoss ? activeBoss.maxHealth : 0,
        stageId || ""
    );
  }, [status, stageId, onBossDefeated, currentWeapon, respawn, invincibilityEnabled, infiniteAmmoEnabled, infinitePowerEnabled, jumpToBossEnabled, bossTauntText, onPlayerUpdate, spawnDamageNumber, spawnDeathShower, speakVulgarity, playGunSound, spawnExplosion, spawnSteamExplosionParticles, spawnPoopExplosion, spawnPowderExplosion, spawnMethExplosion, spawnGlassShatter, onBossDeath, onIntroComplete, onBossEncounter, onBossTransition, onCycleWeapon, onTogglePause]);

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const state = gameStateRef.current;
    const { 
        player, enemies, projectiles, particles, blocks, pickups, damageNumbers, 
        camera, frame, screenShakeTimer, stageId, ernieVibrationTimer 
    } = state;

    // Clear Canvas
    ctx.fillStyle = COLORS.BG_DARK;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Screen Shake
    ctx.save();
    if (screenShakeTimer > 0 || ernieVibrationTimer > 0) {
        const shakeMag = (ernieVibrationTimer > 0) ? 5 : Math.min(screenShakeTimer, SCREEN_SHAKE_MAX);
        ctx.translate((Math.random() - 0.5) * shakeMag, (Math.random() - 0.5) * shakeMag);
    }

    // Camera Transform
    ctx.save();
    ctx.translate(-camera.x, -camera.y);

    // Draw Background
    const currentStage = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_LIGHT, accent: '#555' };
    ctx.fillStyle = currentStage.bg;
    ctx.fillRect(camera.x, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Draw Blocks
    blocks.forEach(b => {
        if (b.type === 'pit') return;
        ctx.fillStyle = (b.type === 'ground' || b.type === 'platform') ? currentStage.ground : '#333';
        if (b.type === 'door') ctx.fillStyle = '#111';
        ctx.fillRect(b.x, b.y, b.w, b.h);
        ctx.strokeStyle = currentStage.accent;
        ctx.lineWidth = 2;
        ctx.strokeRect(b.x, b.y, b.w, b.h);
    });

    // Draw Door Visual (Dynamic)
    const doorX = BOSS_DOOR_X;
    const doorY = 400;
    const doorH = 150;
    const doorW = DOOR_WIDTH;
    if (state.doorState !== 'closed' || state.camera.x > doorX - 1000) {
        ctx.fillStyle = '#222';
        ctx.fillRect(doorX, doorY - state.doorOpenAmount, doorW, doorH);
        ctx.strokeStyle = '#555';
        ctx.strokeRect(doorX, doorY - state.doorOpenAmount, doorW, doorH);
    }

    // Pickups
    pickups.forEach(p => {
        ctx.fillStyle = (p.type.includes('health')) ? '#ef4444' : '#eab308';
        ctx.beginPath();
        ctx.arc(p.pos.x + p.width/2, p.pos.y + p.height/2, p.width/2, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = 'white';
        ctx.lineWidth = 2;
        ctx.stroke();
        ctx.fillStyle = 'white';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(p.type.includes('health') ? 'HP' : 'AM', p.pos.x + p.width/2, p.pos.y + p.height/2);
    });

    // Enemies
    enemies.forEach(e => {
        if (e.health <= 0 && !e.isBlownAway) return;
        if (e.type === 'boss') {
            BossLogic.drawBoss(ctx, e, stageId, frame);
            if (stageId === 'Drug Trade Dale') {
                BossLogic.drawDaleDrugs(ctx, e);
                BossLogic.drawDaleTruck(ctx, e);
            }
        } else {
             ctx.fillStyle = e.enemyType === 'shield' ? COLORS.ENEMY_SHIELD : (e.enemyType === 'tank' ? COLORS.ENEMY_TANK : COLORS.ENEMY_FLYER);
             ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);

             ctx.fillStyle = 'white';
             ctx.fillRect(e.pos.x + 10, e.pos.y + 10, 10, 10);
             ctx.fillRect(e.pos.x + e.width - 20, e.pos.y + 10, 10, 10);

             if (e.enemyType === 'shield' && e.isShieldActive) {
                 ctx.strokeStyle = '#00FFFF';
                 ctx.lineWidth = 2;
                 ctx.strokeRect(e.pos.x - 5, e.pos.y - 5, e.width + 10, e.height + 10);
             }
        }
    });

    // Projectiles
    projectiles.forEach(p => {
        ctx.save();
        ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2);
        if (p.rotation) ctx.rotate(p.rotation);
        ctx.translate(-(p.pos.x + p.width/2), -(p.pos.y + p.height/2));

        if (p.isBoulder) {
            ctx.fillStyle = '#5D4037';
            ctx.beginPath(); ctx.arc(p.pos.x + p.width/2, p.pos.y + p.height/2, p.width/2, 0, Math.PI * 2); ctx.fill();
        } else if (p.isIce || p.isShrapnel) {
             ctx.fillStyle = COLORS.PROJECTILE_ICE;
             ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height);
        } else if (p.isSludge) {
             ctx.fillStyle = '#2E7D32';
             ctx.beginPath(); ctx.arc(p.pos.x + p.width/2, p.pos.y + p.height/2, p.width/2, 0, Math.PI * 2); ctx.fill();
        } else if (p.isOilRocket) {
             ctx.fillStyle = '#1A110F';
             ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height);
             ctx.fillStyle = 'orange';
             ctx.fillRect(p.pos.x - 10, p.pos.y + 4, 10, p.height - 8);
        } else if (p.isMethBarrel) {
             ctx.fillStyle = '#000';
             ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height);
             ctx.fillStyle = 'yellow';
             ctx.font = '8px Arial';
             ctx.fillText('METH', p.pos.x + 5, p.pos.y + 20);
        } else if (p.isCocaine) {
             ctx.fillStyle = 'white';
             ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height);
        } else if (p.isPoop) {
             ctx.fillStyle = '#3E2723';
             ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height);
        } else {
             ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY;
             ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height);
        }
        ctx.restore();
    });

    // Particles
    particles.forEach(p => {
        ctx.fillStyle = p.color;
        if (p.isWater || p.isGlass || p.isBossGore) ctx.globalAlpha = p.life / 60;
        ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size);
        ctx.globalAlpha = 1.0;
    });

    // Player
    if (player.health > 0) {
        ctx.save();
        ctx.translate(player.pos.x, player.pos.y);
        if (player.invincibilityTimer > 0 && frame % 4 < 2) ctx.globalAlpha = 0.5;

        // Visuals
        ctx.fillStyle = COLORS.MEATHEAD_SKIN;
        ctx.fillRect(0, 0, player.width, player.height);
        ctx.fillStyle = COLORS.MEATHEAD_PANTS;
        ctx.fillRect(0, player.height * 0.6, player.width, player.height * 0.4);

        ctx.fillStyle = 'black';
        if (player.facing === 1) ctx.fillRect(player.width - 15, 15, 5, 5); 
        else ctx.fillRect(10, 15, 5, 5);

        ctx.fillStyle = COLORS.GUN;
        const gunY = player.isDucking ? 35 : 15;
        if (player.facing === 1) ctx.fillRect(player.width - 5, gunY, 20, 10);
        else ctx.fillRect(-15, gunY, 20, 10);

        // Taser Visuals
        if (player.isTasing && player.taserTargetId) {
             const target = enemies.find(e => e.id === player.taserTargetId) || projectiles.find(p => p.id === player.taserTargetId);
             if (target) {
                 ctx.strokeStyle = '#00E5FF';
                 ctx.lineWidth = 2;
                 ctx.beginPath();
                 const originX = player.facing === 1 ? player.width + 15 : -15;
                 ctx.moveTo(originX, gunY + 5);
                 const tx = target.pos.x + target.width/2 - player.pos.x;
                 const ty = target.pos.y + target.height/2 - player.pos.y;
                 const segments = 10;
                 for(let i=1; i<=segments; i++) {
                     const t = i/segments;
                     const lx = originX + (tx - originX) * t;
                     const ly = (gunY + 5) + (ty - (gunY + 5)) * t;
                     ctx.lineTo(lx + (Math.random()-0.5)*10, ly + (Math.random()-0.5)*10);
                 }
                 ctx.stroke();
             }
        }

        // Shield
        if (player.filthShieldTimer && player.filthShieldTimer > 0) {
            ctx.strokeStyle = '#2E7D32';
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.arc(player.width/2, player.height/2, Math.max(player.width, player.height), 0, Math.PI*2);
            ctx.stroke();
            ctx.fillStyle = 'rgba(46, 125, 50, 0.3)';
            ctx.fill();
        }
        ctx.restore();
    }

    // Damage Numbers
    damageNumbers.forEach(dn => {
        ctx.fillStyle = dn.isCritical ? '#FFD700' : 'white';
        ctx.font = dn.isCritical ? 'bold 20px "Press Start 2P"' : '12px "Press Start 2P"';
        ctx.strokeStyle = 'black';
        ctx.lineWidth = 3;
        ctx.strokeText(dn.value.toString(), dn.pos.x, dn.pos.y);
        ctx.fillText(dn.value.toString(), dn.pos.x, dn.pos.y);
    });

    // Vulgarity
    if (state.playerVulgarityTimer > 0 && state.playerLastVulgarity) {
        ctx.save();
        ctx.setTransform(1, 0, 0, 1, 0, 0); 
        const screenX = player.pos.x - camera.x + player.width/2;
        const screenY = player.pos.y - camera.y - 40;
        ctx.fillStyle = '#FFD700';
        ctx.font = 'bold 16px "Press Start 2P"';
        ctx.textAlign = 'center';
        ctx.strokeStyle = 'black';
        ctx.lineWidth = 4;
        ctx.strokeText(state.playerLastVulgarity, screenX, screenY);
        ctx.fillText(state.playerLastVulgarity, screenX, screenY);
        ctx.restore();
    }

    if (state.bossVulgarityTimer > 0 && state.bossLastVulgarity) {
        ctx.save();
        ctx.setTransform(1, 0, 0, 1, 0, 0); 
        const boss = enemies.find(e => e.type === 'boss');
        if (boss) {
             const screenX = boss.pos.x - camera.x + boss.width/2;
             const screenY = boss.pos.y - camera.y - 50;
             ctx.fillStyle = '#FF0000';
             ctx.font = 'bold 18px "Press Start 2P"';
             ctx.textAlign = 'center';
             ctx.strokeStyle = 'black';
             ctx.lineWidth = 4;
             ctx.strokeText(state.bossLastVulgarity, screenX, screenY);
             ctx.fillText(state.bossLastVulgarity, screenX, screenY);
        }
        ctx.restore();
    }

    ctx.restore(); 
    ctx.restore(); 
  }, [stageId]);

  // UseEffect to trigger level load when entering Intro or Start
  useEffect(() => {
    let animationFrameId: number;
    // CRITICAL FIX: Only call respawn if we are actually entering the level intro state
    if (status === GameStatus.LEVEL_INTRO) {
        respawn();
    } else if (status === GameStatus.START) {
        // Initial spawn on title screen if needed
        respawn();
    }

    const loop = () => {
      if (status === GameStatus.PLAYING || status === GameStatus.LEVEL_INTRO || status === GameStatus.BOSS_TRANSITION || status === GameStatus.BOSS_VICTORY_SPEECH || status === GameStatus.BOSS_INTRO) {
        update();
      }
      draw();
      animationFrameId = requestAnimationFrame(loop);
    };
    loop();
    return () => cancelAnimationFrame(animationFrameId);
  }, [status, update, draw, respawn]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="w-full h-full object-contain bg-black" />;
};

