  availableWeapons: WeaponType[];
  weaponAmmo: Record<WeaponType, number>;
  // Visuals
  renderScale: Vector2;
  // Filth Shield
  filthShieldTimer?: number;
  // Flamethrower specific
  flameTimer?: number;
  flameAngle?: number;
  // Taser specific
  isTasing?: boolean;
  taserTargetId?: string | null;
  taserTimer?: number;
  // Sludge specific
  barfTimer?: number;
  // Visuals
