}

export interface Projectile extends Entity {
  damage: number;
  owner: 'player' | 'enemy';
  isBoulder?: boolean;
  isIce?: boolean;
  isTsunami?: boolean;
  isShrapnel?: boolean;
  isPoop?: boolean;
  isDart?: boolean;
  isCocaine?: boolean;
  isMethBarrel?: boolean;
  isSludge?: boolean;
