       // Input for special moves
       if (charge && player.chargeInputReleased && player.specialCharges > 0 && !player.hasUsedAirMove) {
          player.specialCharges--; player.specialChargeTimer = 0; player.chargeInputReleased = false; player.chargeDuration = CHARGE_DURATION;
          if (up) { player.isUppercutting = true; player.vel.y = UPPERCUT_FORCE; player.renderScale = { x: 0.6, y: 1.4 }; }
          else { player.isCharging = true; player.vel.x = player.facing * CHARGE_SPEED; player.renderScale = { x: 1.3, y: 0.7 }; }
       }
       if (!charge) player.chargeInputReleased = true;
    }

    // Special Charge Regeneration
    if (player.specialCharges < MAX_SPECIAL_CHARGES) {
       player.specialChargeTimer++;
       if (player.specialChargeTimer >= SPECIAL_CHARGE_REGEN_FRAMES) { player.specialCharges++; player.specialChargeTimer = 0; }
    }

    if (player.pushbackTimer <= 0 && state.playerStunTimer <= 0 && !player.isCharging && !player.isUppercutting) {
      if (left) { player.vel.x -= 0.8; player.facing = -1; }
      if (right) { player.vel.x += 0.8; player.facing = 1; }
      if (!left && !right) player.vel.x *= player.isGrounded ? (stageId === 'Artie Avalanche' ? FRICTION_ICE_STOP : FRICTION_DEFAULT) : 0.95;
    } else if (!player.isCharging && !player.isUppercutting) { player.vel.x *= 0.95; }

    player.vel.x = Math.max(-PLAYER_SPEED * (player.isCharging ? 3 : 1), Math.min(PLAYER_SPEED * (player.isCharging ? 3 : 1), player.vel.x));
    player.isDucking = down && player.isGrounded;

    if (jump && !player.isCharging && !player.isUppercutting) {
      if (player.isGrounded && player.jumpInputReleased) { 
          player.vel.y = PLAYER_JUMP_FORCE; 
          player.isGrounded = false; player.isJumping = true; player.jumpInputReleased = false;
          player.renderScale = { x: 0.7, y: 1.3 }; // Jump Stretch
      }
    } else { player.jumpInputReleased = true; if (player.vel.y < -5 && !player.isUppercutting) player.vel.y *= 0.6; }

    player.vel.y += GRAVITY;
    player.pos.x += player.vel.x + state.totalPullForceX;

    // X Collision
    for (const b of blocks) {
      if (b.type !== 'platform' && b.type !== 'pit' && player.pos.x < b.x + b.w && player.pos.x + player.width > b.x && player.pos.y < b.y + b.h && player.pos.y + player.height > b.y) {
        if (player.vel.x > 0) player.pos.x = b.x - player.width;
        else if (player.vel.x < 0) player.pos.x = b.x + b.w;
        player.vel.x = 0;
        if (player.isCharging) { player.isCharging = false; player.chargeDuration = 0; }
      }
    }

    // Door Logic
    if (player.pos.x > BOSS_DOOR_X - 100 && state.doorState === 'closed') state.doorState = 'opening';
    if (state.doorState === 'opening') { state.doorOpenAmount += DOOR_OPEN_SPEED; if (state.doorOpenAmount >= 150) state.doorState = 'open'; }
    if (state.doorState === 'open' && player.pos.x > BOSS_DOOR_X + DOOR_WIDTH + 50) state.doorState = 'closing';
    if (state.doorState === 'closing') { state.doorOpenAmount -= DOOR_OPEN_SPEED; if (state.doorOpenAmount <= 0) { state.doorState = 'done'; state.arenaLocked = true; onBossEncounter(); } }

    player.pos.y += player.vel.y;
    const wasGrounded = player.isGrounded;
    player.isGrounded = false;

    // Y Collision
    for (const b of blocks) {
      if (player.pos.x < b.x + b.w && player.pos.x + player.width > b.x && player.pos.y < b.y + b.h && player.pos.y + player.height > b.y) {
        if (b.type === 'pit') { player.health = 0; spawnDeathShower(player.pos); speakVulgarity('death'); state.deathTimer = 120; onGameOver(false); return; }
        if (player.vel.y > 0 && player.pos.y + player.height - player.vel.y <= b.y) {
           if (b.type === 'platform' && down) continue; 
           if (!wasGrounded && player.vel.y > 8) player.renderScale = { x: 1.3, y: 0.7 }; // Land Squash
           player.pos.y = b.y - player.height; player.vel.y = 0; player.isGrounded = true; player.isJumping = false; player.hasUsedAirMove = false;
        } else if (player.vel.y < 0 && b.type !== 'platform') {
           player.pos.y = b.y + b.h; player.vel.y = 0;
        }
      }
    }
    player.pos.x = Math.max(0, Math.min(stageId === 'Drug Trade Dale' ? 8200 : 8000 - player.width, player.pos.x));
    if (player.pos.y > 800) { player.health = 0; spawnDeathShower(player.pos); speakVulgarity('death'); state.deathTimer = 120; onGameOver(false); return; }

    // Weapon & Projectiles
    if (player.shootCooldown > 0) player.shootCooldown--;
    if (shoot && player.shootCooldown <= 0 && !player.isCharging && !player.isUppercutting) WeaponLogic.updateWeaponMechanics(player, state, weaponHelpers, { shootRequested: true, moveUp: up, moveDown: down, infiniteAmmo: infiniteAmmoEnabled }, stageId);
    else WeaponLogic.updateWeaponMechanics(player, state, weaponHelpers, { shootRequested: false, moveUp: up, moveDown: down, infiniteAmmo: infiniteAmmoEnabled }, stageId);

    // Update Projectiles
    state.projectiles = projectiles.filter(p => {
       p.pos.x += p.vel.x; p.pos.y += p.vel.y;
       if (p.isOilRocket && p.vel.x < 15) p.vel.x *= 1.05;
       if (p.isCocaine || p.isBoulder || p.isMethBarrel) {
          p.vel.y += GRAVITY;
          if (p.isMethBarrel) {
             p.rotation = (p.rotation || 0) + (p.vel.x * 0.1);
             if (p.pos.y > 470) { p.pos.y = 470; p.vel.y *= -0.6; p.vel.x *= 0.8; if(Math.abs(p.vel.y)<1) p.vel.y=0; }
          }
       }
       if (p.bounces !== undefined) {
         if (p.pos.y > 500) { p.pos.y = 500; p.vel.y *= -BOULDER_BOUNCE_DAMPING; p.bounces--; }
         if (p.bounces <= 0 && p.isMethBarrel) return false;
       }
       // Collision Checks
       let hit = false;
       if (p.owner === 'player') {
          for (const e of enemies) {
             if (e.health > 0 && !e.isBlownAway && p.pos.x < e.pos.x + e.width && p.pos.x + p.width > e.pos.x && p.pos.y < e.pos.y + e.height && p.pos.y + p.height > e.pos.y) {
                 if (e.type === 'boss' && !state.arenaLocked) continue;
                 const dmg = e.type === 'boss' ? BossLogic.getBossDamage(e, stageId, player.currentWeapon, p) : p.damage;
                 const isWeak = e.type === 'boss' ? BossLogic.checkIsWeakness(stageId, player.currentWeapon, p) : false;

                 if (p.isOilRocket) {
                    spawnExplosion(p.pos, '#000', 30);
                    for (let i=0; i<OIL_SPLASH_COUNT; i++) {
                       state.particles.push({ pos: { ...p.pos }, vel: { x: (Math.random()-0.5)*15, y: -5 - Math.random()*10 }, life: 60+Math.random()*60, color: '#000', size: 4+Math.random()*6 });
                    }
                    if (!e.isOiled) { e.isOiled = true; e.oiledTimer = OILED_DURATION; }
                    // Splash damage
                    state.enemies.forEach(other => {
                       if (other !== e && other.health > 0 && !other.isBlownAway) {
                          const dist = Math.sqrt(Math.pow(other.pos.x - p.pos.x, 2) + Math.pow(other.pos.y - p.pos.y, 2));
                          if (dist < OIL_ROCKET_SPLASH_RADIUS) {
                             other.health -= OIL_ROCKET_SPLASH_DAMAGE;
                             if (!other.isOiled) { other.isOiled = true; other.oiledTimer = OILED_DURATION; }
                             spawnDamageNumber(other.pos, OIL_ROCKET_SPLASH_DAMAGE);
                          }
                       }
                    });
                 }

                 if (e.type === 'shield' && e.isShieldActive && p.pos.x < e.pos.x + e.width/2) {
                    // Blocked
                    spawnExplosion(p.pos, '#FFF', 5);
                 } else {
                    e.health -= dmg; spawnDamageNumber(e.pos, dmg, isWeak);
                    if (e.health <= 0) {
                        if (e.type === 'boss') BossLogic.triggerBossDeath(e, player.facing, isWeak, stageId, player.currentWeapon, state, bossHelpers);
                        else { 
                           e.isBlownAway = true; e.vel = { x: p.vel.x > 0 ? 10 : -10, y: -10 }; 
                           spawnDeathShower(e.pos, p.vel.x > 0 ? 1 : -1); 
                           spawnPickup(e.pos); 
                           if (p.isBoulder) speakVulgarity('boulder_kill'); 
                           else if (p.isIce) speakVulgarity('shotgun_kill'); 
                           else if (p.isDart) speakVulgarity('dart_kill'); 
                           else if (p.isOilRocket) speakVulgarity('oil_rocket_kill');
                           else speakVulgarity('gun_kill'); 
                           player.killSatisfactionTimer = 60; 
                        }
                    }
                 }
                 if (!p.isBoulder && !p.isSludge && !p.isOilRocket) hit = true;
             }
          }
       } else {
          // Enemy Projectile vs Player
          if (p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
             if (player.invincibilityTimer <= 0 && !invincibilityEnabled) {
                player.health -= p.damage;
                if (player.health > 0) { 
                   player.invincibilityTimer = PLAYER_INVINCIBILITY_FRAMES; 
                   player.pushbackTimer = PLAYER_PUSHBACK_DURATION; 
                   player.vel = { x: p.vel.x > 0 ? PLAYER_PUSHBACK_VEL_X : -PLAYER_PUSHBACK_VEL_X, y: PLAYER_PUSHBACK_VEL_Y }; 
                   speakVulgarity('hurt'); 
                }
             }
             hit = true;
          }
       }
       if (hit) return false;
       return p.pos.x > state.camera.x - 100 && p.pos.x < state.camera.x + CANVAS_WIDTH + 100 && p.pos.y < 700;
    });

    // Handle Player Body Collision (Charge/Uppercut)
    if (player.isCharging || player.isUppercutting) {
        state.enemies.forEach(e => {
            if (e.health > 0 && !e.isBlownAway && player.pos.x < e.pos.x + e.width && player.pos.x + player.width > e.pos.x && player.pos.y < e.pos.y + e.height && player.pos.y + player.height > e.pos.y) {
                const dmg = player.isCharging ? BOSS_CHARGE_DAMAGE : BOSS_UPPERCUT_DAMAGE;
                if (e.type === 'boss') {
                    if (state.arenaLocked && (!e.hitCooldown || e.hitCooldown <= 0)) {
                        e.health -= dmg; e.hitCooldown = ENEMY_HIT_COOLDOWN; spawnDamageNumber(e.pos, dmg);
                        if (e.health <= 0) BossLogic.triggerBossDeath(e, player.facing, false, stageId, player.currentWeapon, state, bossHelpers);
                    }
                } else {
                    e.health = 0; e.isBlownAway = true; e.vel = { x: player.facing * 20, y: player.isUppercutting ? -25 : -10 };
                    spawnDeathShower(e.pos, player.facing); spawnPickup(e.pos); speakVulgarity(player.isCharging ? 'charge_kill' : 'uppercut_kill');
                    player.killSatisfactionTimer = 60;
                }
            }
        });
    }

    // Enemies
    enemies.forEach(e => {
       if (e.health <= 0 && !e.isBlownAway) return;
       if (e.isBlownAway) { e.pos.x += e.vel.x; e.pos.y += e.vel.y; e.vel.y += GRAVITY; e.rotation = (e.rotation || 0) + 0.2; return; }
       if (e.type === 'boss') {
          if (state.arenaLocked && !state.bossSpawned) { state.bossSpawned = true; }
          if (state.arenaLocked) BossLogic.updateBossAI(e, stageId, player, currentWeapon, invincibilityEnabled, state, bossHelpers);
       } else {
          // Basic Enemy AI
          const dist = Math.abs(player.pos.x - e.pos.x);
          if (dist < 800) {
             if (e.enemyType === 'flyer') {
                 e.pos.x += Math.sin(state.frame * 0.05) * 2;
                 if (e.behavior === 'shoot' && Math.random() < 0.02) {
                     state.projectiles.push({ id: `ep-${Date.now()}`, pos: { x: e.pos.x, y: e.pos.y + e.height }, vel: { x: 0, y: 5 }, width: 12, height: 12, health: 1, maxHealth: 1, type: 'projectile', damage: 15, owner: 'enemy' });
                 }
             } else if (e.enemyType === 'shield') {
                if (dist < 300) e.isShieldActive = false; else e.isShieldActive = true;
                if (!e.isShieldActive && Math.random() < 0.03) {
                    const dir = player.pos.x < e.pos.x ? -1 : 1;
                    state.projectiles.push({ id: `ep-${Date.now()}`, pos: { x: e.pos.x, y: e.pos.y + 20 }, vel: { x: dir * 8, y: 0 }, width: 12, height: 12, health: 1, maxHealth: 1, type: 'projectile', damage: 15, owner: 'enemy' });
                }
             }
             // Simple collisions with player
             if (player.invincibilityTimer <= 0 && !invincibilityEnabled && !player.isCharging && !player.isUppercutting && player.pos.x < e.pos.x + e.width && player.pos.x + player.width > e.pos.x && player.pos.y < e.pos.y + e.height && player.pos.y + player.height > e.pos.y) {
                 player.health -= 10;
                 if (player.health > 0) { player.invincibilityTimer = 45; player.pushbackTimer = 15; player.vel = { x: player.pos.x < e.pos.x ? -15 : 15, y: -5 }; speakVulgarity('hurt'); }
             }
          }
       }
    });

    // Particles & Pickups
    state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; return p.life > 0; });
    state.pickups = pickups.filter(p => {
       if (p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
          if (p.type === 'small_health') player.health = Math.min(INITIAL_PLAYER_HEALTH, player.health + HEALTH_PICKUP_SMALL);
          else if (p.type === 'large_health') player.health = Math.min(INITIAL_PLAYER_HEALTH, player.health + HEALTH_PICKUP_LARGE);
          else {
             const ammoKey = player.currentWeapon;
             if (MAX_AMMO[ammoKey] !== Infinity) {
                const amount = Math.floor(MAX_AMMO[ammoKey] * (p.type === 'small_ammo' ? AMMO_PICKUP_PCT.SMALL : AMMO_PICKUP_PCT.LARGE));
                player.weaponAmmo[ammoKey] = Math.min(MAX_AMMO[ammoKey], player.weaponAmmo[ammoKey] + amount);
             }
          }
          return false;
       }
       return true;
    });
    state.damageNumbers = damageNumbers.filter(d => { d.pos.y += d.vel.y; d.life--; return d.life > 0; });

    // Camera
    let targetCamX = player.pos.x - CANVAS_WIDTH / 2;
    if (state.arenaLocked) targetCamX = BOSS_DOOR_X - (CANVAS_WIDTH - (8000 - BOSS_DOOR_X)) / 2; // Center in boss room
    else targetCamX = Math.max(0, Math.min(8000 - CANVAS_WIDTH, targetCamX));
    state.camera.x += (targetCamX - state.camera.x) * 0.1;
    if (state.screenShakeTimer > 0) state.camera.x += (Math.random() - 0.5) * state.screenShakeTimer;

    // Callbacks
    if (state.frame % 5 === 0) onPlayerUpdate(player.health, player.specialCharges, player.specialChargeTimer, player.weaponAmmo, player.currentWeapon, enemies.find(e => e.type === 'boss')?.health, enemies.find(e => e.type === 'boss')?.maxHealth, stageId || '');
    if (player.health <= 0 && state.deathTimer === 0) { state.deathTimer = 120; spawnDeathShower(player.pos); speakVulgarity('death'); onGameOver(false); }
  }, [stageId, onPlayerUpdate, onBossEncounter, onGameOver, onBossDefeated, currentWeapon, invincibilityEnabled, infiniteAmmoEnabled]);

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const state = gameStateRef.current;

    // Clear
    ctx.fillStyle = COLORS.BG_DARK; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.save();

    // Main Game Layer
    ctx.translate(-state.camera.x, 0);

    // Background
    if (stageId && STAGE_COLORS[stageId]) {
        ctx.fillStyle = STAGE_COLORS[stageId].bg; ctx.fillRect(state.camera.x, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    }

    // Blocks
    state.blocks.forEach(b => {
       if (b.type === 'door') {
           ctx.fillStyle = '#333'; ctx.fillRect(b.x, b.y, b.w, b.h);
           ctx.fillStyle = '#555'; ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h);
       } else if (b.type === 'pit') {
           // transparent
       } else {
           ctx.fillStyle = stageId ? STAGE_COLORS[stageId].ground : COLORS.GROUND; ctx.fillRect(b.x, b.y, b.w, b.h);
           ctx.strokeStyle = '#000'; ctx.strokeRect(b.x, b.y, b.w, b.h);
       }
    });

    // Pickups
    state.pickups.forEach(p => {
       ctx.fillStyle = p.type.includes('health') ? '#F00' : '#FFD700';
       ctx.beginPath(); ctx.arc(p.pos.x + p.width/2, p.pos.y + p.height/2, 8, 0, Math.PI * 2); ctx.fill();
    });

    // Enemies
    state.enemies.forEach(e => {
       if (e.type === 'boss') BossLogic.drawBoss(ctx, e, stageId, state.frame);
       else {
           ctx.fillStyle = e.enemyType === 'shield' ? COLORS.ENEMY_SHIELD : COLORS.ENEMY_TANK;
           ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
           if (e.enemyType === 'shield' && e.isShieldActive) {
               ctx.fillStyle = '#AAA'; ctx.fillRect(e.pos.x - 10, e.pos.y, 10, e.height);
           }
       }
       if (e.isOiled) { ctx.fillStyle = 'rgba(0,0,0,0.5)'; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); }
       if (e.type === 'boss' && stageId === 'Drug Trade Dale') BossLogic.drawDaleDrugs(ctx, e);
    });

    // Boss Hazards
    state.bossVolcanoes.forEach(v => { ctx.fillStyle = '#FF4500'; ctx.beginPath(); ctx.arc(v.pos.x, v.pos.y, 20, 0, Math.PI*2); ctx.fill(); });
    state.bossVolcanoTelegraphs.forEach(v => { ctx.strokeStyle = 'rgba(255,0,0,0.5)'; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(v.pos.x, v.pos.y, 20, 0, Math.PI*2); ctx.stroke(); });

    // Player with Transformations
    if (state.player.health > 0) {
       const { pos, width, height, facing, invincibilityTimer, renderScale, isCharging, isUppercutting, currentWeapon } = state.player;

       if (Math.floor(invincibilityTimer / 4) % 2 === 0) {
           ctx.save();
           // Pivot point at bottom center
           const cx = pos.x + width / 2;
           const cy = pos.y + height;
           ctx.translate(cx, cy);
           ctx.scale(facing * renderScale.x, renderScale.y);

           if (isCharging) {
               // Leaning forward
               ctx.rotate(0.35); // Lean forward relative to facing (since we scaled x by facing, positive rotation leans 'forward')

               // Speed blur effect
               ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
               ctx.beginPath();
               ctx.ellipse(width/2, -height/2, width/2, height/2, 0, 0, Math.PI*2);
               ctx.fill();
           } 

           if (isUppercutting) {
               // Elongated handled by scale, just extra fist needed
               // No rotation, just vertical stretch
           }

           // Draw relative to pivot (0, 0 is feet)
           ctx.fillStyle = COLORS.MEATHEAD_SKIN; 
           ctx.fillRect(-width/2, -height, width, height); // Body

           ctx.fillStyle = COLORS.MEATHEAD_PANTS; 
           ctx.fillRect(-width/2, -height * 0.4, width, height * 0.4); // Pants

           // Head/Torso details could be added here

           // Arms & Gun
           if (isUppercutting) {
               // Fist up
               ctx.fillStyle = COLORS.MEATHEAD_SKIN;
               ctx.fillRect(-10, -height - 20, 20, 30);
           } else {
               // Normal Gun Arm
               ctx.fillStyle = COLORS.MEATHEAD_SKIN; 
               ctx.fillRect(5, -height + 20, 34, 12);
               // Gun
               ctx.fillStyle = COLORS.GUN; 
               ctx.fillRect(25, -height + 20, 24, 8);
               if (currentWeapon === 'FLAMETHROWER') { 
                   ctx.fillStyle = 'orange'; 
                   ctx.fillRect(25, -height + 18, 24, 4); 
               }
           }

           ctx.restore();
       }

       // Filth Shield (Separate from scale)
       if (state.player.filthShieldTimer > 0) {
           ctx.fillStyle = `rgba(0, 255, 0, 0.3)`; ctx.beginPath(); ctx.arc(pos.x + width/2, pos.y + height/2, 50, 0, Math.PI*2); ctx.fill();
       }
    }

    // Projectiles
    state.projectiles.forEach(p => {
       ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY;
       if (p.isBoulder) ctx.fillStyle = '#5D4037';
       if (p.isIce) ctx.fillStyle = '#00FFFF';
       if (p.isSludge) ctx.fillStyle = '#2E7D32';
       if (p.isOilRocket) ctx.fillStyle = '#000';

       ctx.save();
       ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2);
       if (p.rotation) ctx.rotate(p.rotation);
       ctx.fillRect(-p.width/2, -p.height/2, p.width, p.height);
       ctx.restore();
    });

    // Particles
    state.particles.forEach(p => {
       ctx.fillStyle = p.color; ctx.beginPath(); ctx.arc(p.pos.x, p.pos.y, p.size, 0, Math.PI*2); ctx.fill();
    });

    // Damage Numbers
    state.damageNumbers.forEach(d => {
       ctx.fillStyle = d.isCritical ? '#FFD700' : '#FFF';
       ctx.font = `${d.isCritical ? '20px' : '12px'} monospace`;
       ctx.fillText(d.value.toString(), d.pos.x, d.pos.y);
    });

    ctx.restore();

    // Vulgarity Text Overlay (Screen Space)
    if (state.playerVulgarityTimer > 0) {
        ctx.fillStyle = 'yellow'; ctx.font = '24px monospace'; ctx.textAlign = 'center';
        ctx.fillText(state.playerLastVulgarity, CANVAS_WIDTH / 2, 100);
    }

    // Menu Overlay Backgrounds are handled by React Overlay component, but we ensure game renders black on menus
    if (status === GameStatus.START || status === GameStatus.STAGE_SELECT) {
        ctx.fillStyle = 'black';
        ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    }

  }, [stageId, status]);

  useEffect(() => {
    let animId: number;
    const loop = () => {
       update(); draw(); animId = requestAnimationFrame(loop);
    };
    animId = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(animId);
  }, [update, draw]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="block bg-black shadow-2xl" />;
};

export default GameCanvas;

