  SLUDGE_PROJ_SIZE_MIN, SLUDGE_PROJ_SIZE_RAND, TSUNAMI_WAVE_SPEED,
  TSUNAMI_DAMAGE_BOSS, TSUNAMI_DAMAGE_WEAKNESS, ENEMY_HIT_COOLDOWN,
  TASER_AMMO_CONSUMPTION_RATE, TASER_TICK_RATE, TASER_DOT_DAMAGE, TASER_FIRE_THRESHOLD
} from './constants';
import * as BossLogic from './boss';

// Helper methods to bridge weapon logic with the main game loop state.
export interface WeaponHelpers {
  addProjectile: (p: Projectile) => void;
  addParticle: (p: Particle) => void;
  playGunSound: (type: 'gun' | 'ice' | 'flame' | 'tsunami' | 'dart' | 'horn' | 'ignite' | 'barf') => void;
  spawnExplosion: (pos: Vec2, color: string, count: number, baseVelX?: number, spread?: number) => void;
  spawnDamageNumber: (pos: Vec2, value: number | string, isCritical?: boolean) => void;
  spawnGlassShatter: (pos: Vec2) => void;
  spawnDeathShower: (pos: Vector2, facing: number, multiplier?: number) => void;
  spawnPickup: (pos: Vector2) => void;
  speakVulgarity: (category: any) => void;
  setScreenShake: (duration: number) => void;
  triggerBossDeath: (boss: Enemy, facing: number, wasWeakness: boolean) => void;
}

// Handles the initial firing of a weapon (projectile creation, ammo reduction, cooldown setting).
export const fireWeapon = (player: Player, state: any, helpers: WeaponHelpers, isMoveUp: boolean, isMoveDown: boolean, infiniteAmmo: boolean) => {
  const { currentWeapon, facing, pos, width, isDucking } = player;
  const shootX = pos.x + (facing === 1 ? width : -10);
  const shootY = isDucking ? pos.y + 45 : pos.y + 25;

  if (currentWeapon === 'GUN') {
    helpers.addProjectile({ id: `p-${Date.now()}`, pos: { x: shootX, y: shootY }, vel: { x: facing * GUN_VELOCITY, y: 0 }, width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'player' });
    player.shootCooldown = GUN_COOLDOWN; helpers.playGunSound('gun');
  } else if (currentWeapon === 'BOULDER') {
    if (!state.projectiles.some((p: Projectile) => p.owner === 'player' && p.isBoulder)) {
      const vy = isMoveUp ? -18 : 0; const vx = isMoveUp ? facing * (BOULDER_SPEED * 0.9) : facing * BOULDER_SPEED;
      helpers.addProjectile({ id: `b-${Date.now()}`, pos: { x: player.pos.x + (facing === 1 ? width : -40), y: pos.y + 20 }, vel: { x: vx, y: vy }, width: 48, height: 48, health: 1, maxHealth: 1, type: 'projectile', damage: BOULDER_DAMAGE, owner: 'player', isBoulder: true });
      player.shootCooldown = BOULDER_COOLDOWN; if (!infiniteAmmo) player.weaponAmmo['BOULDER']--;
    }
  } else if (currentWeapon === 'SHOTGUN') {
    for (let i = 0; i < SHOTGUN_PELLET_COUNT; i++) {
      const angle = (i - Math.floor(SHOTGUN_PELLET_COUNT/2)) * 0.15; const speed = 11 + Math.random() * 6;
      helpers.addProjectile({ id: `pellet-${Date.now()}-${i}`, pos: { x: shootX, y: shootY }, vel: { x: Math.cos(angle) * facing * speed, y: Math.sin(angle) * speed }, width: 10, height: 10, health: 1, maxHealth: 1, type: 'projectile', damage: SHOTGUN_DAMAGE, owner: 'player', isIce: true });
    }
    player.shootCooldown = SHOTGUN_COOLDOWN; helpers.playGunSound('ice'); if (!infiniteAmmo) player.weaponAmmo['SHOTGUN']--;
  } else if (currentWeapon === 'NEEDLES') {
    helpers.addProjectile({ id: `dart-${Date.now()}`, pos: { x: shootX, y: shootY }, vel: { x: facing * 24, y: (Math.random() - 0.5) * 5 }, width: 20, height: 4, health: 1, maxHealth: 1, type: 'projectile', damage: NEEDLE_DAMAGE, owner: 'player', isDart: true });
    player.shootCooldown = NEEDLE_COOLDOWN; helpers.playGunSound('dart'); if (!infiniteAmmo) player.weaponAmmo['NEEDLES']--;
  } else if (currentWeapon === 'OIL_ROCKET') {
    helpers.addProjectile({ 
      id: `oil-rocket-${Date.now()}`, 
      pos: { x: shootX, y: shootY - 10 }, 
      vel: { x: facing * OIL_ROCKET_VELOCITY, y: 0 }, 
      width: 50, height: 18, 
      health: 1, maxHealth: 1, 
      type: 'projectile', 
      damage: OIL_ROCKET_DAMAGE, 
      owner: 'player', 
      isOilRocket: true 
    });
    player.shootCooldown = OIL_ROCKET_COOLDOWN; 
    helpers.playGunSound('gun'); 
    if (!infiniteAmmo) player.weaponAmmo['OIL_ROCKET']--;
  } else if (currentWeapon === 'FLAMETHROWER') {
    let targetAngle = 0; if (isMoveUp) targetAngle = -Math.PI / 4; else if (isMoveDown) targetAngle = Math.PI / 4; player.flameAngle = targetAngle;
    player.flameTimer = (player.flameTimer || 0) + 1;
    const rampPct = Math.min(1.0, player.flameTimer / FLAMETHROWER_RAMP_FRAMES);
    const currentRange = FLAMETHROWER_RANGE + (FLAMETHROWER_MAX_RANGE - FLAMETHROWER_RANGE) * rampPct;
    if (state.frame % 2 === 0) {
      if (!infiniteAmmo) player.weaponAmmo['FLAMETHROWER']--; helpers.playGunSound('flame');
      const spawnX = pos.x + (facing === 1 ? width - 5 : 5), spawnY = isDucking ? pos.y + 45 : pos.y + 30;
      for (let i = 0; i < 6; i++) {
        const jitter = (Math.random() - 0.5) * 0.4; const speed = (8 + Math.random() * 8) * (1 + rampPct * 1.5); const finalAngle = targetAngle + jitter;
        helpers.addParticle({ pos: { x: spawnX, y: spawnY }, vel: { x: Math.cos(finalAngle) * facing * speed + player.vel.x, y: Math.sin(finalAngle) * speed }, life: 15 + Math.random() * 20, color: PARTICLE_PALETTES.FIRE[Math.floor(PARTICLE_PALETTES.FIRE.length * Math.random())], size: 8 + Math.random() * 12 });
      }
      const checkHit = (entity: Enemy | Projectile) => {
        const entMidX = entity.pos.x + entity.width / 2, entMidY = entity.pos.y + entity.height / 2, dx = entMidX - spawnX, dy = entMidY - spawnY, distSq = dx * dx + dy * dy;
        if (distSq > currentRange * currentRange) return false;
        const angleToEntity = Math.atan2(dy, dx * facing); return Math.abs(angleToEntity - targetAngle) < 0.35;
      };
      state.projectiles.forEach((p: Projectile) => { if (p.owner === 'enemy' && checkHit(p)) { if ((p.isIce && p.width > 30) || !(p.id.startsWith('debris-') || p.id.startsWith('magma-') || (p.isBoulder && p.owner === 'enemy') || (p.isIce && p.width <= 20))) { p.health = 0; helpers.spawnExplosion({ x: p.pos.x + p.width/2, y: p.pos.y + p.height/2 }, p.isIce ? COLORS.PROJECTILE_ICE : (p.id.startsWith('magma') ? '#FF4500' : COLORS.PROJECTILE_ENEMY), Math.min(10, Math.ceil(p.width / 5)), 0, 10); } } });
      state.enemies.forEach((e: Enemy) => {
        if (e.health > 0 && !e.isBlownAway && checkHit(e)) {
          if (e.isOiled) {
            // OIL EXPLOSION COMBO
            e.isOiled = false;
            e.oiledTimer = 0;
            helpers.setScreenShake(35);
            helpers.playGunSound('ignite');
            const nukePos = { x: e.pos.x + e.width / 2, y: e.pos.y + e.height / 2 };
            for (let j = 0; j < 40; j++) {
              helpers.addParticle({
                pos: { x: nukePos.x + (Math.random()-0.5)*15, y: nukePos.y - j * 1.8 },
                vel: { x: (Math.random()-0.5)*2, y: -4 - Math.random()*3 },
                life: 40 + Math.random()*25, color: j < 20 ? '#FFFFFF' : '#FFD700', size: 8 + Math.random()*10
              });
            }
            for (let j = 0; j < 120; j++) {
              const ang = Math.random() * Math.PI;
              const dist = Math.random() * 140;
              helpers.addParticle({
                pos: { x: nukePos.x + Math.cos(ang) * dist, y: nukePos.y - 85 + Math.sin(ang) * dist * 0.45 },
                vel: { x: Math.cos(ang) * 3, y: Math.sin(ang) * 1.2 - 2 },
                life: 60 + Math.random()*60, 
                color: j % 3 === 0 ? '#FFFFFF' : (j % 3 === 1 ? '#FF4500' : '#FFD700'), 
                size: 15 + Math.random()*20
              });
            }
            helpers.spawnExplosion(nukePos, '#FFFFFF', 60, 0, 110);
            helpers.spawnExplosion(nukePos, '#1A110F', 40, 0, 50); 
            state.enemies.forEach((other: Enemy) => {
               if (other.health > 0 && !other.isBlownAway) {
                 const dx = other.pos.x - e.pos.x, dy = other.pos.y - e.pos.y;
                 const dist = Math.sqrt(dx*dx + dy*dy);
                 if (dist < OIL_EXPLOSION_RADIUS) {
                   const proxDmg = OIL_EXPLOSION_DAMAGE;
                   other.health -= proxDmg;
                   helpers.spawnDamageNumber(other.pos, proxDmg, true);
                   if (other.health <= 0) {
                     if (other.type === 'boss') helpers.triggerBossDeath(other, 0, false);
                     else { other.isBlownAway = true; other.vel = { x: (dx > 0 ? 1 : -1) * 20, y: -25 }; }
                   }
                 }
               }
            });
            e.health -= OIL_EXPLOSION_DAMAGE;
            helpers.spawnDamageNumber(e.pos, OIL_EXPLOSION_DAMAGE, true);
          }
          if (e.type === 'boss') {
            if (state.arenaLocked && (!e.hitCooldown || e.hitCooldown <= 0)) {
              const dmg = BossLogic.getBossDamage(e, state.stageId, currentWeapon);
              const isW = BossLogic.checkIsWeakness(state.stageId, currentWeapon);
              e.health -= dmg; e.hitCooldown = 60; helpers.spawnDamageNumber(e.pos, dmg, isW);
              if (state.stageId === 'Artie Avalanche' && isW && e.health > 0) { const tx = e.pos.x < 7560 ? 7850 : 7250; e.vel.y = -22; e.vel.x = (tx - e.pos.x) / 50; e.bossState = 'jumping'; e.stateTimer = 60; }
              if (e.health <= 0) helpers.triggerBossDeath(e, facing, isW);
            }
          } else {
            if (!e.hitCooldown || e.hitCooldown <= 0) {
              e.health -= FLAMETHROWER_DAMAGE; helpers.spawnDamageNumber(e.pos, FLAMETHROWER_DAMAGE); e.hitCooldown = 12;
              if (e.health <= 0) { e.isBlownAway = true; e.vel = { x: (3 + rampPct * 10) * facing, y: -5 }; player.killSatisfactionTimer = 60; }
            }
          }
        }
      });
    }
  } else if (currentWeapon === 'SLUDGE') { player.barfTimer = 24; player.shootCooldown = SLUDGE_COOLDOWN; player.filthShieldTimer = FILTH_SHIELD_DURATION; if (!infiniteAmmo) player.weaponAmmo['SLUDGE']--; helpers.playGunSound('barf'); } else if (currentWeapon === 'TSUNAMI') { if (!state.tsunamiActive) { state.tsunamiActive = true; state.tsunamiDir = facing; state.tsunamiStartX = facing === 1 ? state.camera.x : state.camera.x + 800; state.tsunamiX = state.tsunamiStartX; player.shootCooldown = TSUNAMI_COOLDOWN; helpers.playGunSound('tsunami'); if (!infiniteAmmo) player.weaponAmmo['TSUNAMI']--; } } else if (currentWeapon === 'TASER') { 
    if (!player.isTasing) { 
      let nearest: (Enemy | Projectile) | null = null, minDist = TASER_RANGE; 
      const playerMidX = player.pos.x + player.width/2, playerMidY = player.pos.y + player.height/2; 
      state.enemies.forEach((e: Enemy) => { 
        if (e.health > 0 && !e.isBlownAway) { 
          const ex = e.pos.x + e.width/2, ey = e.pos.y + e.height/2; 
          if (ex > state.camera.x && ex < state.camera.x + CANVAS_WIDTH) { 
            if ((facing === 1 && ex > playerMidX) || (facing === -1 && ex < playerMidX)) { 
              const dx = ex - playerMidX, dy = ey - playerMidY, dist = Math.sqrt(dx*dx + dy*dy); 
              if (dist < minDist) { minDist = dist; nearest = e; } 
            } 
          } 
        } 
      }); 
      state.projectiles.forEach((p: Projectile) => { 
        if (p.isMethBarrel && p.health > 0) { 
          const px = p.pos.x + p.width/2, py = p.pos.y + p.height/2; 
          if (px > state.camera.x && px < state.camera.x + CANVAS_WIDTH) { 
            if ((facing === 1 && px > playerMidX) || (facing === -1 && px < playerMidX)) { 
              const dx = px - playerMidX, dy = py - playerMidY, dist = Math.sqrt(dx*dx + dy*dy); 
              if (dist < minDist) { minDist = dist; nearest = p; } 
            } 
          } 
        } 
      }); 

      // ALWAYS ACTIVATE TASER, EVEN IF MISSING TARGET (WASTED STREAM)
      player.isTasing = true; 
      player.taserTimer = 0; 
      player.taserTargetId = nearest ? (nearest as (Enemy | Projectile)).id : null; 
    } 
  }
};

// Handles weapon mechanics that need to run every frame (steering, damage ticks, effects).
export const updateWeaponMechanics = (
  player: Player,
  state: any,
  helpers: WeaponHelpers,
  inputs: { shootRequested: boolean; moveUp: boolean; moveDown: boolean; infiniteAmmo: boolean },
  stageId: string | null
) => {
  const { currentWeapon } = player;

  // 1. ROCKET STEERING
  if (currentWeapon === 'OIL_ROCKET') {
    const steeringForce = 0.5;
    state.projectiles.forEach((p: Projectile) => {
      if (p.isOilRocket && p.owner === 'player') {
        if (inputs.moveUp) p.vel.y -= steeringForce;
        if (inputs.moveDown) p.vel.y += steeringForce;
        p.vel.y *= 0.96; 
      }
    });
  }

  // 2. SLUDGE BARF (Projectile spawning over time)
  if (player.barfTimer && player.barfTimer > 0) {
    player.barfTimer--;
    if (player.barfTimer % 2 === 0) { 
       const shootX = player.pos.x + (player.facing === 1 ? player.width : -10);
       const shootY = player.isDucking ? player.pos.y + 45 : player.pos.y + 25;
       helpers.addProjectile({ 
         id: `sludge-part-${Date.now()}-${player.barfTimer}`, 
         pos: { x: shootX, y: shootY }, 
         vel: { 
           x: player.facing * (11 + Math.random() * 8), 
           y: -3 - Math.random() * 9 
         }, 
         width: SLUDGE_PROJ_SIZE_MIN + Math.random() * SLUDGE_PROJ_SIZE_RAND, 
         height: SLUDGE_PROJ_SIZE_MIN + Math.random() * SLUDGE_PROJ_SIZE_RAND, 
         health: 1, maxHealth: 1, 
         type: 'projectile', damage: SLUDGE_DAMAGE, owner: 'player', isSludge: true, life: 150 
       });
    }
  }

  // 3. TSUNAMI (Moving the wave and handling logic)
  if (state.tsunamiActive) {
    state.tsunamiX += TSUNAMI_WAVE_SPEED * state.tsunamiDir; 
    const dist = Math.abs(state.tsunamiX - state.tsunamiStartX);
    const totalDist = CANVAS_WIDTH * 1.5;
    const progress = dist / totalDist;
    const tsunamiTopY = Math.pow(Math.min(1.0, dist / (CANVAS_WIDTH * 1.25)), 0.6) * 560;
    const waveHeight = 600 - tsunamiTopY;
    const bendMult = 120;
    const dir = state.tsunamiDir;
    const density = 35;

    // Visual particles for wave
    for (let i = 0; i <= density; i++) {
      const yPct = i / density;
      const yPos = tsunamiTopY + (yPct * waveHeight);
      const normalizedY = (yPct - 0.5) * 2;
      const xOffset = (normalizedY * normalizedY) * bendMult * dir;
      const px = state.tsunamiX + xOffset;
      const py = yPos;
      helpers.addParticle({ pos: { x: px + (Math.random() - 0.5) * 40, y: py + (Math.random() - 0.5) * 15 }, vel: { x: (TSUNAMI_WAVE_SPEED * 0.4 + Math.random() * 8) * dir, y: (Math.random() - 0.5) * 4 }, life: 12 + Math.random() * 18, color: PARTICLE_PALETTES.WATER[Math.floor(PARTICLE_PALETTES.WATER.length * Math.random())], size: 8 + Math.random() * 12, isWater: true });
      if (i < 3 && Math.random() > 0.4) helpers.addParticle({ pos: { x: px, y: py }, vel: { x: (TSUNAMI_WAVE_SPEED * 0.9) * dir, y: (Math.random() - 0.5) * 10 }, life: 20 + Math.random() * 10, color: '#FFFFFF', size: 5 + Math.random() * 5, isWater: true });
    }

    if (stageId === 'Victor Volcano') state.bossVolcanoes = state.bossVolcanoes.filter((v: any) => { if (Math.abs(v.pos.x - state.tsunamiX) < 60) { state.bossSteamExplosions.push({ pos: { ...v.pos }, life: 45, radius: 100 }); (helpers as any).spawnSteamExplosionParticles(v.pos, 40); helpers.setScreenShake(12); return false; } return true; });

    state.projectiles.forEach((p: Projectile) => { 
      if (p.isMethBarrel && p.health > 0) { 
        if (Math.abs(p.pos.x + p.width / 2 - state.tsunamiX) < 120) { 
          p.vel = { x: state.tsunamiDir * 20, y: -10 }; 
          p.rotation = (p.rotation || 0) + 0.5; 
          p.health -= TSUNAMI_DAMAGE_BOSS; 
          helpers.spawnDamageNumber(p.pos, TSUNAMI_DAMAGE_BOSS); 
        } 
      } 
    });

    state.enemies.forEach((e: Enemy) => { 
      if (e.health > 0 && !e.isBlownAway) { 
        const ebY = e.pos.y + e.height; 
        if (Math.abs(e.pos.x + e.width / 2 - state.tsunamiX) < 120 && ebY > tsunamiTopY) { 
          if (e.type === 'boss') { 
            if (state.arenaLocked && (!e.hitCooldown || e.hitCooldown <= 0)) { 
              const isW = BossLogic.checkIsWeakness(stageId, currentWeapon); 
              const dmg = isW ? TSUNAMI_DAMAGE_WEAKNESS : TSUNAMI_DAMAGE_BOSS; 
              e.health -= dmg; 
              e.hitCooldown = ENEMY_HIT_COOLDOWN; 
              helpers.spawnDamageNumber(e.pos, dmg, isW); 
              if (e.health <= 0) helpers.triggerBossDeath(e, state.tsunamiDir, isW); 
            } 
          } else { 
            e.health = 0; 
            e.isBlownAway = true; 
            e.vel = { x: state.tsunamiDir * 20, y: -10 }; 
            helpers.spawnDeathShower(e.pos, state.tsunamiDir); 
            helpers.spawnPickup(e.pos); 
            helpers.speakVulgarity('tsunami_kill'); 
            player.killSatisfactionTimer = 60; 
          } 
        } 
      } 
    });
    if (progress >= 1.0) state.tsunamiActive = false;
  }

  // 4. TASER (Damage tick loop)
  const hasAmmo = (wpn: WeaponType) => wpn === 'GUN' || player.weaponAmmo[wpn] >= 1;
  if (currentWeapon === 'TASER' && inputs.shootRequested && (hasAmmo('TASER') || inputs.infiniteAmmo)) { 
    if (!player.isTasing) fireWeapon(player, state, helpers, inputs.moveUp, inputs.moveDown, inputs.infiniteAmmo); 
    if (player.isTasing) { 
      player.taserTimer = (player.taserTimer || 0) + 1; 
      if (!inputs.infiniteAmmo && state.frame % TASER_AMMO_CONSUMPTION_RATE === 0) player.weaponAmmo['TASER'] -= 1; 
      player.vel.x = 0; 
      if (player.weaponAmmo['TASER'] <= 0) { player.isTasing = false; player.taserTargetId = null; } 
      const target = (state.enemies.find((e: Enemy) => e.id === player.taserTargetId) || state.projectiles.find((p: Projectile) => p.id === player.taserTargetId)) as (Enemy | Projectile | undefined); 

      if (target && (target.pos.x + target.width < state.camera.x || target.pos.x > state.camera.x + CANVAS_WIDTH || target.health <= 0)) { 
         player.taserTargetId = null; 
      } 

      if (target && target.health > 0) { 
        const dx = (target.pos.x + target.width/2) - (player.pos.x + player.width/2); 
        const dy = (target.pos.y + target.height/2) - (player.pos.y + player.height/2); 
        const dist = Math.sqrt(dx*dx + dy*dy); 
        if (dist > TASER_RANGE + 100) { player.taserTargetId = null; } 
        else { 
          if (target.type === 'boss') { 
            const b = target as Enemy; 
            if (!b.hitCooldown || b.hitCooldown <= 0) { 
              const dmg = BossLogic.getBossDamage(b, stageId, currentWeapon); 
              const isW = BossLogic.checkIsWeakness(stageId, currentWeapon); 
              b.health -= dmg; b.hitCooldown = ENEMY_HIT_COOLDOWN; helpers.spawnDamageNumber(b.pos, dmg, isW); 
              if (b.health <= 0) helpers.triggerBossDeath(b, player.facing, isW); 
            } 
          } else { 
            target.isTased = true; 
            if (state.frame % TASER_TICK_RATE === 0) { 
              target.health -= TASER_DOT_DAMAGE; helpers.spawnDamageNumber(target.pos, TASER_DOT_DAMAGE); 
              if (target.health <= 0) { 
                if (target.type === 'enemy') { 
                  const e = target as Enemy; e.isBlownAway = true; e.vel = { x: (Math.random()-0.5)*10, y: -15 }; helpers.spawnDeathShower(e.pos, 0); helpers.spawnPickup(e.pos); helpers.speakVulgarity('taser_kill'); 
                } 
                player.taserTargetId = null; 
              } 
            } 
            if (player.taserTimer! >= TASER_FIRE_THRESHOLD && !target.isOnFire) { target.isOnFire = true; helpers.playGunSound('ignite'); } 
          } 
        } 
      } 
    } 
  } else { player.isTasing = false; player.taserTargetId = null; player.taserTimer = 0; }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import HUD from './components/HUD';
import Overlay from './components/Overlay';
import GameCanvas from './components/GameCanvas';
import { GameStatus, WeaponType } from './types';
import { 
  INITIAL_PLAYER_HEALTH, 
  SPECIAL_CHARGE_REGEN_FRAMES, 
  MAX_AMMO, 
  STAGES, 
  BOSS_WEAPON_MAP, 
  SET0_WEAPONS,
  ALL_WEAPONS_CHEAT,
  VULGARITIES, 
  BOSS_DIALOGUE,
  WEAPON_ORDER
} from './constants';

// --- DEV CONFIG ---
const SHOW_CHEATS = true;
// ------------------

// The main container component. In GameMaker, this is equivalent to your 
// persistent 'obj_game_controller' or a 'room_manager'.
const App: React.FC = () => {
  // -- Global Game State --
  // These determine which 'Room' or 'Layer' is active.
  const [status, setStatus] = useState<GameStatus>(GameStatus.START);

  // -- Player Persistent Stats --
  // These persist between levels/screens.
  const [health, setHealth] = useState(INITIAL_PLAYER_HEALTH);
  const [specialCharges, setSpecialCharges] = useState(2);
  const [specialChargeTimer, setSpecialChargeTimer] = useState(0);

  // -- Narrative/UI State --
  const [bossTaunt, setBossTaunt] = useState("YOU'RE TOAST.");
  const [victorySpeech, setVictorySpeech] = useState("");
  const [briefing, setBriefing] = useState("Your mission is to kill everything in sight for no particular reason.");

  // -- Progression State --
  const [selectedStage, setSelectedStage] = useState<string | null>(null);
  const [defeatedStages, setDefeatedStages] = useState<string[]>([]);
  const [availableWeapons, setAvailableWeapons] = useState<WeaponType[]>(['GUN']);
  const [currentWeapon, setCurrentWeapon] = useState<WeaponType>('GUN');

  // Resets ammo to full capacity. 
  // In GM: Implement this in a script `scr_reset_ammo()` called on level start or death.
  const resetAmmo = useCallback(() => {
    return {
      'GUN': Infinity,
      'BOULDER': MAX_AMMO['BOULDER'],
      'SHOTGUN': MAX_AMMO['SHOTGUN'],
      'OIL_ROCKET': MAX_AMMO['OIL_ROCKET'],
      'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'],
      'TSUNAMI': MAX_AMMO['TSUNAMI'],
      'NEEDLES': MAX_AMMO['NEEDLES'],
      'TASER': MAX_AMMO['TASER'],
      'SLUDGE': MAX_AMMO['SLUDGE']
    };
  }, []);

  const [weaponAmmo, setWeaponAmmo] = useState<Record<WeaponType, number>>(resetAmmo());

  // -- Cheat/Debug Flags --
  const [cheatEnabled, setCheatEnabled] = useState(false);
  const [invincibilityEnabled, setInvincibilityEnabled] = useState(false);
  const [infiniteAmmoEnabled, setInfiniteAmmoEnabled] = useState(false);
  const [infinitePowerEnabled, setInfinitePowerEnabled] = useState(false);
  const [jumpToBossEnabled, setJumpToBossEnabled] = useState(false);

  // -- Meta Progression --
  // Rank 0 = First 4 bosses, Rank 1 = Second 4 bosses.
  const [progressionRank, setProgressionRank] = useState(0);

  const [isVictoryPhase, setIsVictoryPhase] = useState(false);
  const [overlayActiveTime, setOverlayActiveTime] = useState(0);

  // For menu navigation (Weapon Wheel / Stage Select cursor).
  const [selectedIndex, setSelectedIndex] = useState(0);

  // Refs are used here to access the latest state inside the requestAnimationFrame loop 
  // without triggering re-renders or stale closures.
  const statusRef = useRef(status);
  const selectedIndexRef = useRef(selectedIndex);
  const progressionRankRef = useRef(progressionRank);
  const availableWeaponsRef = useRef(availableWeapons);

  // Input edge detection (Previous frame state).
  // In GM: Use `gamepad_button_check_pressed` instead of manually tracking previous state.
  const lastPadInputRef = useRef(0);
  const lastAStateRef = useRef(false);
  const lastBStateRef = useRef(false);
  const lastStartStateRef = useRef(false);
  const lastLBStateRef = useRef(false);
  const lastRBStateRef = useRef(false);

  // Sync refs with state
  useEffect(() => { statusRef.current = status; }, [status]);
  useEffect(() => { selectedIndexRef.current = selectedIndex; }, [selectedIndex]);
  useEffect(() => { progressionRankRef.current = progressionRank; }, [progressionRank]);
  useEffect(() => { availableWeaponsRef.current = availableWeapons; }, [availableWeapons]);

  // Prevents Meathead from spamming lines too often globally.
  const meatheadSpeechCooldownRef = useRef(0);

  // -- Timers --
  // Updates overlay timer to prevent accidental skips on menu transitions.
  useEffect(() => {
    let interval: number;
    if (status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH || status === GameStatus.START || status === GameStatus.VICTORY) {
      setOverlayActiveTime(0);
      interval = window.setInterval(() => {
        setOverlayActiveTime(prev => prev + 100);
      }, 100);
    }
    return () => clearInterval(interval);
  }, [status]);

  // Decrement speech cooldown.
  useEffect(() => {
    const timer = setInterval(() => {
      if (meatheadSpeechCooldownRef.current > 0) meatheadSpeechCooldownRef.current -= 100;
    }, 100);
    return () => clearInterval(timer);
  }, []);

  // Browser TTS (Text-To-Speech) wrapper.
  const speakBossTaunt = useCallback((stage: string, text: string) => {
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(text);
      // Hardcoded voice pitches for bosses
      switch (stage) {
        case 'Artie Avalanche': utterance.pitch = 1.6; utterance.rate = 0.85; break;
        case 'Victor Volcano': utterance.pitch = 0.7; utterance.rate = 0.85; break;
        case 'Ernie Earthquake': utterance.pitch = 0.1; utterance.rate = 0.55; break;
        case 'Hector Hurricane': utterance.pitch = 1.2; utterance.rate = 1.5; break;
        case 'Blackout Barry': utterance.pitch = 1.4; utterance.rate = 1.1; break;
        default: utterance.pitch = 1.0; utterance.rate = 1.0;
      }
      utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  }, []);

  // Trigger boss speech on intro.
  useEffect(() => {
    if (status === GameStatus.BOSS_INTRO && selectedStage && bossTaunt) {
      speakBossTaunt(selectedStage, bossTaunt);
    }
  }, [status, selectedStage, bossTaunt, speakBossTaunt]);

  // -- Inventory Management --
  // Cycles weapon index +1 or -1.
  const cycleWeapon = useCallback((dir: number) => {
    setAvailableWeapons(prevAvailable => {
      if (prevAvailable.length <= 1) return prevAvailable;
      setCurrentWeapon(current => {
        const idx = prevAvailable.indexOf(current);
        const nextIdx = (idx + dir + prevAvailable.length) % prevAvailable.length;
        return prevAvailable[nextIdx];
      });
      return prevAvailable;
    });
  }, []);

  const selectWeaponByIndex = useCallback((index: number) => {
    setAvailableWeapons(prev => {
      if (index >= 0 && index < prev.length) {
        setCurrentWeapon(prev[index]);
      }
      return prev;
    });
  }, []);

  const handleIconClick = useCallback((index: number) => {
    setSelectedIndex(index);
    selectWeaponByIndex(index);
  }, [selectWeaponByIndex]);

  // Plays a random "Rebuke" line if player tries to select a dead boss.
  const speakRebuke = useCallback(() => {
    if ('speechSynthesis' in window) {
      if (window.speechSynthesis.speaking) return;
      if (meatheadSpeechCooldownRef.current > 0) return;
      const text = VULGARITIES.REBUKE[Math.floor(Math.random() * VULGARITIES.REBUKE.length)];
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1; utterance.rate = 1.1; utterance.volume = 1.0;
      utterance.onend = () => { meatheadSpeechCooldownRef.current = 1000; };
      utterance.onerror = () => { meatheadSpeechCooldownRef.current = 1000; };
      window.speechSynthesis.speak(utterance);
    }
  }, []);

  // -- Game Flow Control --

  const togglePause = useCallback(() => {
    setStatus(prev => {
      // Prevent pausing during cutscenes/transitions
      if (isVictoryPhase || prev === GameStatus.BOSS_TRANSITION || prev === GameStatus.BOSS_INTRO || prev === GameStatus.BOSS_VICTORY_SPEECH || prev === GameStatus.LEVEL_INTRO || prev === GameStatus.VICTORY) return prev;
      if (prev === GameStatus.PLAYING) { 
        // When pausing, set menu cursor to current weapon
        setSelectedIndex(availableWeaponsRef.current.indexOf(currentWeapon));
        return GameStatus.PAUSED; 
      }
      if (prev === GameStatus.PAUSED) return GameStatus.PLAYING;
      return prev;
    });
  }, [isVictoryPhase, currentWeapon]);

  // Handles logic for "Press Start" or "Confirm" actions based on current state.
  const handleStart = useCallback(() => {
    if (overlayActiveTime < 2000) return; // Debounce

    // Returning from Death/Victory to Menu or Stage Select
    if (status === GameStatus.VICTORY || status === GameStatus.GAME_OVER) {
      if ('speechSynthesis' in window) window.speechSynthesis.cancel();
      // Auto-progress to Set 1 if Set 0 is cleared
      if (progressionRank === 0 && defeatedStages.length >= 4) {
        setProgressionRank(1); 
        setDefeatedStages([]); 
        setAvailableWeapons(SET0_WEAPONS.sort((a,b) => WEAPON_ORDER.indexOf(a) - WEAPON_ORDER.indexOf(b))); 
        setCurrentWeapon('GUN'); 
        setStatus(GameStatus.STAGE_SELECT);
      } else {
        // Reset to Title
        setDefeatedStages([]); 
        const weaponsToStart: WeaponType[] = (cheatEnabled && SHOW_CHEATS) ? ALL_WEAPONS_CHEAT : (progressionRank === 1 ? SET0_WEAPONS : ['GUN'] as WeaponType[]); 
        setAvailableWeapons([...weaponsToStart].sort((a,b) => WEAPON_ORDER.indexOf(a) - WEAPON_ORDER.indexOf(b))); 
        setCurrentWeapon('GUN'); 
        setWeaponAmmo(resetAmmo()); 
        setSelectedIndex(0); 
        setIsVictoryPhase(false); 
        setStatus(GameStatus.START);
      }
    } else if (status === GameStatus.START) {
      // Title -> Stage Select
      const weaponsToStart: WeaponType[] = (cheatEnabled && SHOW_CHEATS) ? ALL_WEAPONS_CHEAT : (progressionRank === 1 ? SET0_WEAPONS : ['GUN'] as WeaponType[]); 
      setAvailableWeapons([...weaponsToStart].sort((a,b) => WEAPON_ORDER.indexOf(a) - WEAPON_ORDER.indexOf(b))); 
      setCurrentWeapon('GUN'); 
      setWeaponAmmo(resetAmmo()); 
      setStatus(GameStatus.STAGE_SELECT);
    } else if (status === GameStatus.BOSS_INTRO) {
      // Boss Intro -> Gameplay
      setStatus(GameStatus.PLAYING);
    } else if (status === GameStatus.BOSS_VICTORY_SPEECH) {
      // Boss Dead -> Stage Select or Victory Screen
      if ('speechSynthesis' in window) window.speechSynthesis.cancel();
      setIsVictoryPhase(false);
      if (defeatedStages.length >= 4) { setStatus(GameStatus.VICTORY); } 
      else { 
        setStatus(GameStatus.STAGE_SELECT); 
        setSelectedStage(null); 
        setSelectedIndex(0); 
        setCurrentWeapon('GUN'); 
        setWeaponAmmo(resetAmmo()); 
      }
    }
  }, [status, defeatedStages, overlayActiveTime, cheatEnabled, progressionRank, resetAmmo]);

  const handleResume = useCallback(() => { setStatus(GameStatus.PLAYING); }, []);

  const handleBossSelect = useCallback(() => {
    if ('speechSynthesis' in window) window.speechSynthesis.cancel();
    setSelectedStage(null); setSelectedIndex(0); setIsVictoryPhase(false); setCurrentWeapon('GUN'); setStatus(GameStatus.STAGE_SELECT); setWeaponAmmo(resetAmmo());
  }, [resetAmmo]);

  const handleQuitToMenu = useCallback(() => { 
    if ('speechSynthesis' in window) window.speechSynthesis.cancel();
    setSelectedStage(null); setSelectedIndex(0); setIsVictoryPhase(false); setDefeatedStages([]); setCurrentWeapon('GUN'); setProgressionRank(0); setStatus(GameStatus.START); 
  }, []);

  const handleSelectStage = useCallback((stage: string) => {
    if (defeatedStages.includes(stage)) { speakRebuke(); return; }
    if ('speechSynthesis' in window) window.speechSynthesis.cancel();
    setSelectedStage(stage); 
    setHealth(INITIAL_PLAYER_HEALTH); 
    setSpecialCharges(2); 
    setSpecialChargeTimer(0); 
    setCurrentWeapon('GUN'); 
    setWeaponAmmo(resetAmmo()); 
    setIsVictoryPhase(false); 
    setStatus(GameStatus.LEVEL_INTRO);
  }, [defeatedStages, speakRebuke, resetAmmo]);

  // -- Input Listener (Keyboard/Mouse) --
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const key = e.key.toLowerCase();
      if (key === 'escape') togglePause();

      // Menu Navigation Logic
      if (status === GameStatus.PAUSED || status === GameStatus.STAGE_SELECT) {
        const numW = availableWeapons.length;
        const useTwoRows = numW > 4;
        const topRowSize = useTwoRows ? Math.ceil(numW / 2) : numW;
        const bottomRowSize = useTwoRows ? Math.floor(numW / 2) : 0;

        // Grid Navigation for Weapon Wheel / Stage Select
        if (key === 'arrowup' || key === 'w') { 
          if (status === GameStatus.PAUSED) {
            setSelectedIndex(p => {
              if (p >= numW) return p - 1; 
              if (useTwoRows && p >= topRowSize) return p - topRowSize; 
              return p;
            });
          }
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p - 2 + 4) % 4); 
        } 
        else if (key === 'arrowdown' || key === 's') { 
          if (status === GameStatus.PAUSED) {
            setSelectedIndex(p => {
              if (useTwoRows && p < topRowSize && p + topRowSize < numW) return p + topRowSize; 
              if (p < numW) return numW; 
              if (p < numW + 2) return p + 1; 
              return p;
            });
          }
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p + 2) % 4); 
        } 
        else if (key === 'arrowleft' || key === 'a') { 
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p % 2 === 0 ? p + 1 : p - 1));
          if (status === GameStatus.PAUSED && selectedIndex < numW) {
            setSelectedIndex(p => p > 0 ? p - 1 : p);
          }
        } 
        else if (key === 'arrowright' || key === 'd') { 
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p % 2 === 0 ? p + 1 : p - 1));
          if (status === GameStatus.PAUSED && selectedIndex < numW) {
            setSelectedIndex(p => p < numW - 1 ? p + 1 : p);
          }
        } 
        else if (key === 'enter' || key === ' ') { 
          if (status === GameStatus.PAUSED) {
            if (selectedIndex < numW) {
              selectWeaponByIndex(selectedIndex);
            } else if (selectedIndex === numW) {
              handleResume();
            } else if (selectedIndex === numW + 1) {
              handleBossSelect();
            } else if (selectedIndex === numW + 2) {
              handleQuitToMenu();
            }
          } else if (status === GameStatus.STAGE_SELECT) { handleSelectStage(STAGES(progressionRank)[selectedIndex].id); } 
        }
      } else if (status === GameStatus.PLAYING) { 
        if (key === 'q') cycleWeapon(-1); if (key === 'e') cycleWeapon(1); 
      } 
      else if (status === GameStatus.START || status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH || status === GameStatus.VICTORY) { if (key === 'enter' || key === ' ') handleStart(); }
    };
    const handleWheel = (e: WheelEvent) => { if (status === GameStatus.PLAYING) cycleWeapon(e.deltaY > 0 ? 1 : -1); };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('wheel', handleWheel);
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('wheel', handleWheel); };
  }, [togglePause, status, cycleWeapon, selectWeaponByIndex, availableWeapons, currentWeapon, selectedIndex, handleResume, handleBossSelect, handleQuitToMenu, handleSelectStage, handleStart, progressionRank]);

  // -- Debug/Cheat Handlers --
  const handleToggleCheat = useCallback(() => {
    setCheatEnabled(prev => { 
      const newState = !prev; 
      if (newState) setAvailableWeapons([...ALL_WEAPONS_CHEAT].sort((a,b) => WEAPON_ORDER.indexOf(a) - WEAPON_ORDER.indexOf(b))); 
      else {
        const resetWpns = progressionRank === 1 ? SET0_WEAPONS : ['GUN'] as WeaponType[];
        setAvailableWeapons([...resetWpns].sort((a,b) => WEAPON_ORDER.indexOf(a) - WEAPON_ORDER.indexOf(b))); 
        setCurrentWeapon('GUN'); 
      } 
      return newState; 
    });
  }, [progressionRank]);

  const handleToggleInvincibility = useCallback(() => setInvincibilityEnabled(prev => !prev), []);
  const handleToggleInfiniteAmmo = useCallback(() => setInfiniteAmmoEnabled(prev => !prev), []);
  const handleToggleInfinitePower = useCallback(() => setInfinitePowerEnabled(prev => !prev), []);
  const handleToggleJumpToBoss = useCallback(() => setJumpToBossEnabled(prev => !prev), []);

  const handleIncrementRank = useCallback(() => { 
    setProgressionRank(r => { 
      const next = Math.min(r + 1, 1); 
      if (next === 1 && !cheatEnabled) setAvailableWeapons([...SET0_WEAPONS].sort((a,b) => WEAPON_ORDER.indexOf(a) - WEAPON_ORDER.indexOf(b))); 
      return next; 
    }); 
  }, [cheatEnabled]);

  const handleDecrementRank = useCallback(() => { 
    setProgressionRank(r => { 
      const next = Math.max(r - 1, 0); 
      if (next === 0 && !cheatEnabled) setAvailableWeapons(['GUN'] as WeaponType[]); 
      return next; 
    }); 
  }, [cheatEnabled]);

  // -- Canvas Callbacks --
  // These are passed down to GameCanvas to signal state changes back to App.
  const handleBossTransition = useCallback(() => setStatus(GameStatus.BOSS_TRANSITION), []);
  const handleBossDeath = useCallback(() => setIsVictoryPhase(true), []);
  const handleBossEncounter = useCallback(() => { setStatus(GameStatus.BOSS_INTRO); const pool = BOSS_DIALOGUE.INTRO_QUOTES[selectedStage || ''] || BOSS_DIALOGUE.INTRO_QUOTES['default']; const taunt = pool[1] || pool[0]; setBossTaunt(taunt); }, [selectedStage]);

  const handleBossDefeated = useCallback((stageId: string) => {
    // Unlock weapon
    const newWeapon = BOSS_WEAPON_MAP[stageId];
    if (newWeapon) {
      setAvailableWeapons(prev => {
        const next = prev.includes(newWeapon) ? prev : [...prev, newWeapon];
        return [...next].sort((a, b) => WEAPON_ORDER.indexOf(a) - WEAPON_ORDER.indexOf(b));
      });
    }
    setDefeatedStages(prev => [...prev, stageId]);
    const speech = VULGARITIES.LOCAL_VICTORY[Math.floor(Math.random() * VULGARITIES.LOCAL_VICTORY.length)];
    setVictorySpeech(speech); setStatus(GameStatus.BOSS_VICTORY_SPEECH);
  }, []);

  const handleGameOver = useCallback((victory: boolean) => { 
    if ('speechSynthesis' in window) window.speechSynthesis.cancel();
    if (!victory) { setIsVictoryPhase(false); setStatus(GameStatus.GAME_OVER); } 
  }, []);

  // Syncs player HP/Ammo from Canvas physics loop to React UI.
  const handlePlayerUpdate = useCallback((h: number, sc: number, st: number, ammo?: Record<WeaponType, number>, forcedWeapon?: WeaponType) => { setHealth(h); setSpecialCharges(sc); setSpecialChargeTimer(st); if (ammo) setWeaponAmmo(ammo); if (forcedWeapon) setCurrentWeapon(forcedWeapon); }, []);
  const handleIntroComplete = useCallback(() => setStatus(GameStatus.PLAYING), []);

  // -- Gamepad Polling Loop --
  // Note: We poll inside App.tsx for menu navigation. GameCanvas.tsx polls separately for gameplay.
  useEffect(() => {
    let frameId: number;
    const poll = () => {
      const gamepads = navigator.getGamepads();
      const gp = gamepads[0];
      if (gp) {
        const now = Date.now();
        const currentStatus = statusRef.current;
        const currentIdx = selectedIndexRef.current;
        const numW = availableWeaponsRef.current.length;
        const useTwoRows = numW > 4;
        const topRowSize = useTwoRows ? Math.ceil(numW / 2) : numW;

        // Stick Deadzone Check + Timed Input (to prevent super fast scrolling)
        if (now - lastPadInputRef.current > 200) {
            let dx = 0, dy = 0;
            if (gp.axes[0] < -0.5 || gp.buttons[14]?.pressed) dx = -1;
            if (gp.axes[0] > 0.5 || gp.buttons[15]?.pressed) dx = 1;
            if (gp.axes[1] < -0.5 || gp.buttons[12]?.pressed) dy = -1;
            if (gp.axes[1] > 0.5 || gp.buttons[13]?.pressed) dy = 1;

            if (currentStatus === GameStatus.STAGE_SELECT) {
              if (dx !== 0) { setSelectedIndex(prev => (prev % 2 === 0 ? prev + 1 : prev - 1)); lastPadInputRef.current = now; }
              if (dy !== 0) { setSelectedIndex(prev => (prev < 2 ? prev + 2 : prev - 2)); lastPadInputRef.current = now; }
            } else if (currentStatus === GameStatus.PAUSED) {
              // Pause Menu Grid Navigation
              if (dy < -0.3) { 
                setSelectedIndex(p => {
                  if (p >= numW) return p - 1;
                  if (useTwoRows && p >= topRowSize) return p - topRowSize;
                  return p;
                });
                lastPadInputRef.current = now; 
              } 
              else if (dy > 0.3) { 
                setSelectedIndex(p => {
                  if (useTwoRows && p < topRowSize && p + topRowSize < numW) return p + topRowSize;
                  if (p < numW) return numW;
                  if (p < numW + 2) return p + 1;
                  return p;
                });
                lastPadInputRef.current = now; 
              }
              else if (dx < -0.3 && currentIdx < numW) {
                setSelectedIndex(p => p > 0 ? p - 1 : p);
                lastPadInputRef.current = now;
              }
              else if (dx > 0.3 && currentIdx < numW) {
                setSelectedIndex(p => p < numW - 1 ? p + 1 : p);
                lastPadInputRef.current = now;
              }
            }
        }

        const aPressed = gp.buttons[0]?.pressed; 
        const bPressed = gp.buttons[1]?.pressed; 
        const startPressed = gp.buttons[9]?.pressed;
        const lbPressed = gp.buttons[4]?.pressed;
        const rbPressed = gp.buttons[5]?.pressed;

        // Button Press Logic (Edge detection)
        if (aPressed && !lastAStateRef.current) {
            if (currentStatus === GameStatus.START || currentStatus === GameStatus.VICTORY || currentStatus === GameStatus.GAME_OVER || currentStatus === GameStatus.BOSS_INTRO || currentStatus === GameStatus.BOSS_VICTORY_SPEECH) {
              handleStart();
            } else if (currentStatus === GameStatus.STAGE_SELECT) {
              handleSelectStage(STAGES(progressionRankRef.current)[currentIdx].id);
            } else if (currentStatus === GameStatus.PAUSED) {
              if (currentIdx < numW) {
                selectWeaponByIndex(currentIdx);
              } else if (currentIdx === numW) {
                handleResume();
              } else if (currentIdx === numW + 1) {
                handleBossSelect();
              } else if (currentIdx === numW + 2) {
                handleQuitToMenu();
              }
            }
        }
        if (bPressed && !lastBStateRef.current) { 
          if (currentStatus === GameStatus.PAUSED) handleResume(); 
          else if (currentStatus === GameStatus.STAGE_SELECT) setStatus(GameStatus.START); 
        }
        if (startPressed && !lastStartStateRef.current) { if (currentStatus === GameStatus.START) handleStart(); else if (currentStatus === GameStatus.PLAYING || currentStatus === GameStatus.PAUSED) togglePause(); }
        if (currentStatus === GameStatus.PLAYING) { if (lbPressed && !lastLBStateRef.current) cycleWeapon(-1); if (rbPressed && !lastRBStateRef.current) cycleWeapon(1); }

        lastAStateRef.current = !!aPressed; lastBStateRef.current = !!bPressed; lastStartStateRef.current = !!startPressed; lastLBStateRef.current = !!lbPressed; lastRBStateRef.current = !!rbPressed;
      }
      frameId = requestAnimationFrame(poll);
    };
    frameId = requestAnimationFrame(poll);
    return () => cancelAnimationFrame(frameId);
  }, [handleStart, handleSelectStage, handleResume, handleBossSelect, handleQuitToMenu, togglePause, cycleWeapon, selectWeaponByIndex]);

  return (
    <div className="relative w-screen h-screen flex items-center justify-center bg-black overflow-hidden">
      <div className="relative shadow-2xl border-4 border-gray-800 bg-[#121212]" style={{ width: 800, height: 600 }}>
        {/* Render HUD only during gameplay/boss scenes */}
        {(status === GameStatus.LEVEL_INTRO || status === GameStatus.PLAYING || status === GameStatus.BOSS_TRANSITION || status === GameStatus.PAUSED || status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH) && (
          <HUD health={health} maxHealth={INITIAL_PLAYER_HEALTH} specialCharges={specialCharges} specialChargeTimer={specialChargeTimer} maxChargeTimer={SPECIAL_CHARGE_REGEN_FRAMES} currentWeapon={currentWeapon} ammo={weaponAmmo[currentWeapon]} maxAmmo={MAX_AMMO[currentWeapon]} />
        )}

        {/* Overlay handles Start Screen, Pause Menu, Stage Select, etc. */}
        <Overlay 
          status={status} 
          onStart={handleStart} 
          onResume={handleResume} 
          onBossSelect={handleBossSelect} 
          onQuitToMenu={handleQuitToMenu} 
          onSelectStage={handleSelectStage} 
          onIconClick={handleIconClick}
          onCheatAllWeapons={handleToggleCheat} 
          onToggleInvincibility={handleToggleInvincibility} 
          onToggleInfiniteAmmo={handleToggleInfiniteAmmo} 
          onToggleInfinitePower={handleToggleInfinitePower} 
          onToggleJumpToBoss={handleToggleJumpToBoss} 
          onIncrementRank={handleIncrementRank} 
          onDecrementRank={handleDecrementRank} 
          progressionRank={progressionRank} 
          cheatEnabled={cheatEnabled} 
          invincibilityEnabled={invincibilityEnabled} 
          infiniteAmmoEnabled={infiniteAmmoEnabled} 
          infinitePowerEnabled={infinitePowerEnabled} 
          jumpToBossEnabled={jumpToBossEnabled} 
          showCheats={SHOW_CHEATS} 
          bossTaunt={bossTaunt} 
          victorySpeech={victorySpeech} 
          briefing={briefing} 
          defeatedStages={defeatedStages} 
          selectedIndex={selectedIndex} 
          overlayActiveTime={overlayActiveTime} 
          stageId={selectedStage} 
          availableWeapons={availableWeapons}
          currentWeapon={currentWeapon}
        />

        {/* Main Game Logic & Rendering Canvas */}
        <GameCanvas status={status} stageId={selectedStage} onPlayerUpdate={handlePlayerUpdate} onBossEncounter={handleBossEncounter} onBossTransition={handleBossTransition} onBossDefeated={handleBossDefeated} onBossDeath={handleBossDeath} onBossSelect={handleBossSelect} onGameOver={handleGameOver} onIntroComplete={handleIntroComplete} onTogglePause={togglePause} currentWeapon={currentWeapon} initialAmmo={weaponAmmo} invincibilityEnabled={invincibilityEnabled && (SHOW_CHEATS)} infiniteAmmoEnabled={infiniteAmmoEnabled && (SHOW_CHEATS)} infinitePowerEnabled={infinitePowerEnabled && (SHOW_CHEATS)} jumpToBossEnabled={jumpToBossEnabled && (SHOW_CHEATS)} bossTauntText={bossTaunt} />
      </div>
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useCallback } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, Vector2, Pickup, PickupType, WeaponType, DamageNumber, Volcano, SteamExplosion, VulgarityType 
} from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, GRAVITY, 
  PLAYER_SPEED, PLAYER_JUMP_FORCE, CHARGE_SPEED, CHARGE_DURATION, 
  SPECIAL_CHARGE_REGEN_FRAMES, MAX_SPECIAL_CHARGES, INITIAL_PLAYER_HEALTH, JUMP_PREP_FRAMES,
  STAGE_COLORS, UPPERCUT_FORCE, BULLET_DAMAGE, BOULDER_DAMAGE, BOULDER_SPEED, BOULDER_BOUNCE_DAMPING,
  SHOTGUN_DAMAGE, SHOTGUN_COOLDOWN, SHOTGUN_FREEZE_TIME, FLAMETHROWER_DAMAGE, FLAMETHROWER_RANGE, FLAMETHROWER_SPEED_MULT,
  TSUNAMI_COOLDOWN, TSUNAMI_WAVE_SPEED, BOSS_CHARGE_DAMAGE, BOSS_UPPERCUT_DAMAGE, ENEMY_UPPERCUT_DAMAGE, MAX_AMMO, AMMO_PICKUP_PCT,
  BOSS_DOOR_X, DOOR_WIDTH, VULGARITIES, BOSS_DIALOGUE, PARTICLE_PALETTES, STAGES_SET_0, STAGES_SET_1,
  DALE_TRUCK_SPEED, METH_BARREL_DAMAGE, TASER_RANGE, TASER_DOT_DAMAGE, TASER_FIRE_THRESHOLD, FIRE_DOT_DAMAGE, FIRE_DOT_DAMAGE_HEAVY,
  FRICTION_DEFAULT, FRICTION_ICE_STAGE, FRICTION_ICE_STOP, DOOR_OPEN_SPEED, VULGARITY_TEXT_DURATION, BOSS_VULGARITY_DURATION,
  VOICE_LINE_COOLDOWN_FRAMES, PLAYER_INVINCIBILITY_FRAMES, PLAYER_STUN_INVINCIBILITY, PLAYER_PUSHBACK_DURATION,
  UPPERCUT_AIR_SPEED, UPPERCUT_AIR_ACCEL, FIRE_TICK_RATE, TASER_TICK_RATE, TASER_AMMO_CONSUMPTION_RATE,
  BOULDER_SHRAPNEL_COUNT, HEALTH_PICKUP_SMALL, HEALTH_PICKUP_LARGE,
  BOULDER_SHRAPNEL_DAMAGE, TSUNAMI_DAMAGE_BOSS, TSUNAMI_DAMAGE_WEAKNESS, ENEMY_HIT_COOLDOWN,
  NEEDLE_DOT_TICK_RATE, NEEDLE_DOT_DAMAGE_PER_STACK, NEEDLE_OVERDOSE_THRESHOLD,
  PLAYER_PUSHBACK_VEL_X, PLAYER_PUSHBACK_VEL_Y, PLAYER_STUN_DURATION, ERNIE_STOMP_VIBRATION_DURATION,
  SLUDGE_DAMAGE, SLUDGE_DOT_DAMAGE, SLUDGE_DOT_TICK, SLUDGE_LINGER_DURATION, FILTH_SHIELD_CONTACT_DAMAGE,
  HECTOR_PULL_STRENGTH_ULT, SCREEN_SHAKE_MAX,
  SLUDGE_PROJ_SIZE_MIN, SLUDGE_PROJ_SIZE_RAND, SLUDGE_POOL_W_MIN, SLUDGE_POOL_W_RAND,
  SLUDGE_POOL_H_MIN, SLUDGE_POOL_H_RAND, SLUDGE_BUBBLE_SIZE_MIN, SLUDGE_BUBBLE_SIZE_RAND,
  OIL_SPLASH_COUNT, OILED_DURATION, OIL_ROCKET_SPLASH_RADIUS, OIL_ROCKET_SPLASH_DAMAGE,
  OILED_KNOCKBACK_SPEED, OILED_KNOCKBACK_IMPACT_DAMAGE
} from '../constants';
import * as BossLogic from '../boss';
import * as WeaponLogic from '../weapons';

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, specialCharges: number, specialChargeTimer: number, ammo?: Record<WeaponType, number>, forcedWeapon?: WeaponType) => void;
  onBossEncounter: () => void;
  onBossTransition: () => void;
  onBossDefeated: (stageId: string) => void;
  onBossDeath: () => void;
  onBossSelect: () => void;
  onGameOver: (victory: boolean) => void;
  onIntroComplete: () => void;
  onTogglePause: () => void;
  currentWeapon: WeaponType;
  initialAmmo: Record<WeaponType, number>;
  invincibilityEnabled: boolean;
  infiniteAmmoEnabled: boolean;
  infinitePowerEnabled: boolean;
  jumpToBossEnabled: boolean;
  bossTauntText: string;
}

// The core Game Engine component. 
// Uses a requestAnimationFrame loop to handle physics, AI, and rendering on a single HTML5 Canvas.
const GameCanvas: React.FC<GameCanvasProps> = ({ 
  status, stageId, onPlayerUpdate, onBossEncounter, onBossTransition, 
  onBossDefeated, onBossDeath, onBossSelect, onGameOver, onIntroComplete, onTogglePause, 
  currentWeapon, initialAmmo, invincibilityEnabled, infiniteAmmoEnabled, infinitePowerEnabled, jumpToBossEnabled,
  bossTauntText
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  // -- Mutable Game State (Refs) --
  // This object holds the entire simulation state. It is mutated directly in the loop 
  // to avoid React render overhead. In GameMaker, these would be instance variables.
  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 150, y: 100 },
      vel: { x: 0, y: 0 },
      width: 44,
      height: 64,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      // -- Combat Flags --
      isCharging: false,
      isUppercutting: false,
      isDucking: false,
      specialCharges: MAX_SPECIAL_CHARGES,
      specialChargeTimer: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1, // 1 = right, -1 = left
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0,
      invincibilityTimer: 0,
      pushbackTimer: 0,
      killSatisfactionTimer: 0, // Delay before control returns after a cinematic kill
      bossKillSatisfactionTimer: 0,
      hasUsedAirMove: false,
      jumpInputReleased: true,
      chargeInputReleased: true,
      currentWeapon: 'GUN',
      availableWeapons: ['GUN'],
      weaponAmmo: { ...initialAmmo },
      // -- Status Effects --
      isTasing: false,
      taserTargetId: null,
      taserTimer: 0,
      flameTimer: 0,
      flameAngle: 0,
      filthShieldTimer: 0,
      barfTimer: 0,
      questionMarkTimer: 0
    } as Player & { killSatisfactionTimer: number, bossKillSatisfactionTimer: number },

    // -- Entity Lists --
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    pickups: [] as Pickup[],
    particles: [] as (Particle & { isWater?: boolean })[],
    damageNumbers: [] as DamageNumber[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],

    // -- Environment --
    camera: { x: 0, y: 0 },
    bossSpawned: false,
    arenaLocked: false,
    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,

    // -- UI/Cinematic --
    playerLastVulgarity: "",
    playerVulgarityTimer: 0,
    bossLastVulgarity: "",
    bossVulgarityTimer: 0,
    voiceLineCooldown: 0,
    victoryString: "",
    deathString: "",
    deathTimer: 0,
    postVictoryTimer: 0,
    introTimer: 0,

    // -- Boss Specific Globals --
    bossExplosionTimer: 0,
    bossExplosionPos: { x: 0, y: 0 },
    tsunamiX: -1,
    tsunamiStartX: 0,
    tsunamiActive: false,
    tsunamiDir: 1,
    bossVolcanoes: [] as Volcano[],
    bossVolcanoTelegraphs: [] as Volcano[],
    bossPoopTelegraphs: [] as { pos: Vector2, life: number, spawnX: number }[],
    bossSteamExplosions: [] as SteamExplosion[],
    bossTsunamiSide: 0 as number,
    bossTsunamiTimer: 0,
    victorWallSide: 0 as number, 
    ernieVibrationTimer: 0,
    playerStunTimer: 0,
    screenShakeTimer: 0,
    shouldSyncWeapon: false,
    totalPullForceX: 0, // Wind physics
    stageId: stageId
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  // Sync props to Ref state
  useEffect(() => { gameStateRef.current.player.currentWeapon = currentWeapon; }, [currentWeapon]);
  useEffect(() => { gameStateRef.current.stageId = stageId; }, [stageId]);
  useEffect(() => { if (gameStateRef.current.deathTimer <= 0) gameStateRef.current.player.weaponAmmo = { ...initialAmmo }; }, [initialAmmo]);

  // Input Listeners
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const k = e.key.toLowerCase(); const c = e.code.toLowerCase(); keys.current[k] = true; keys.current[c] = true;
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      const k = e.key.toLowerCase(); const c = e.code.toLowerCase(); keys.current[k] = false; keys.current[c] = false;
    };
    const handleMouseDown = () => mouse.current.down = true;
    const handleMouseUp = () => mouse.current.down = false;
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', handleMouseDown); window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousedown', handleMouseDown); window.removeEventListener('mouseup', handleMouseUp);
      if (audioCtxRef.current) { audioCtxRef.current.close(); audioCtxRef.current = null; }
    };
  }, []);

  // -- Helper Functions (Spawn, Sound, VFX) --
  // These are passed into the weapon/boss logic modules.

  const spawnDamageNumber = useCallback((pos: Vector2, value: number | string, isCritical: boolean = false) => {
    const state = gameStateRef.current;
    state.damageNumbers.push({
      id: `dmg-${Date.now()}-${Math.random()}`,
      value: typeof value === 'number' ? Math.floor(value) : value,
      pos: { ...pos },
      vel: { x: (Math.random() - 0.5) * 4, y: -4 - Math.random() * 2 },
      life: 60,
      maxLife: 60,
      isCritical
    });
  }, []);

  const spawnExplosion = useCallback((pos: Vector2, color: string, count: number, baseVelX: number = 0, spread: number = 15, isGlass: boolean = false, isBossGore: boolean = false) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      if (state.particles.length > 2500) break; // Performance cap
      state.particles.push({
        pos: { ...pos },
        vel: { x: baseVelX + (Math.random() - 0.5) * spread, y: (Math.random() - 0.5) * spread },
        life: isGlass ? 150 + Math.random() * 200 : (isBossGore ? 180 + Math.random() * 120 : 20 + Math.random() * 80),
        color: color,
        size: i % 3 === 0 ? 1 + Math.random() * 4 : 2 + Math.random() * 12,
        isGlass,
        isBossGore
      });
    }
  }, []);

  // [Sound and other spawn helpers omitted for brevity, logic remains same as previous]
  // ... spawnSteamExplosionParticles, spawnPoopExplosion, spawnPowderExplosion, spawnMethExplosion, spawnOilSplash, spawnBoulderShrapnel, spawnRockShatter ...
  const spawnSteamExplosionParticles = useCallback((pos: Vector2, count: number = 30) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      state.particles.push({
        pos: { ...pos },
        vel: { x: (Math.random() - 0.5) * 12, y: (Math.random() - 0.5) * 12 - 4 },
        life: 35 + Math.random() * 25,
        color: PARTICLE_PALETTES.STEAM[Math.floor(PARTICLE_PALETTES.STEAM.length * Math.random())],
        size: 10 + Math.random() * 18
      });
    }
  }, []);

  const spawnPoopExplosion = useCallback((pos: Vector2, count: number = 20) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      const isCorn = Math.random() < 0.35;
      const color = isCorn ? '#FFEB3B' : PARTICLE_PALETTES.POOP[Math.floor(PARTICLE_PALETTES.POOP.length * Math.random())];
      state.particles.push({
        pos: { x: pos.x, y: pos.y },
        vel: { x: (Math.random() - 0.5) * 16, y: (Math.random() - 0.5) * 16 },
        life: 50 + Math.random() * 60,
        color: color,
        size: i % 3 === 0 ? 4 + Math.random() * 3 : 6 + Math.random() * 8
      });
    }
  }, []);

  const spawnPowderExplosion = useCallback((pos: Vector2, count: number = 25) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
        state.particles.push({
            pos: { ...pos },
            vel: { x: (Math.random() - 0.5) * 8, y: (Math.random() - 0.5) * 8 },
            life: 40 + Math.random() * 40,
            color: PARTICLE_PALETTES.POWDER[Math.floor(PARTICLE_PALETTES.POWDER.length * Math.random())],
            size: 4 + Math.random() * 12
        });
    }
  }, []);

  const spawnMethExplosion = useCallback((pos: Vector2, count: number = 40) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
        state.particles.push({
            pos: { ...pos },
            vel: { x: (Math.random() - 0.5) * 15, y: (Math.random() - 0.5) * 15 },
            life: 60 + Math.random() * 60,
            color: PARTICLE_PALETTES.METH[Math.floor(PARTICLE_PALETTES.METH.length * Math.random())],
            size: 6 + Math.random() * 10
        });
    }
  }, []);

  const spawnOilSplash = (pos: Vector2) => {
    const state = gameStateRef.current;
    const count = OIL_SPLASH_COUNT * 1.5; 
    for (let i = 0; i < count; i++) {
      const ang = (Math.random() - 0.5) * Math.PI * 2;
      const speed = 10 + Math.random() * 22;
      state.projectiles.push({
        id: `oil-splash-${Date.now()}-${i}`,
        pos: { ...pos },
        vel: { x: Math.cos(ang) * speed, y: Math.sin(ang) * speed },
        width: 6, height: 6, 
        health: 1, maxHealth: 1, type: 'projectile',
        damage: 0, owner: 'player', life: 60, isOilSplash: true
      });
    }
  };

  const spawnBoulderShrapnel = (pos: Vector2, count: number, direction: number) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      const ang = (Math.random() - 0.5) * Math.PI;
      const speed = 12 + Math.random() * 18; 
      state.projectiles.push({
        id: `shrap-${Date.now()}-${i}`,
        pos: { ...pos },
        vel: { x: (direction * -1) * Math.cos(ang) * speed, y: Math.sin(ang) * speed - 8 },
        width: 12, height: 12, health: 1, maxHealth: 1, type: 'projectile',
        damage: BOULDER_SHRAPNEL_DAMAGE, owner: 'player', life: 45, isShrapnel: true
      });
    }
  };

  const spawnRockShatter = (pos: Vector2) => {
    PARTICLE_PALETTES.ROCK.forEach(c => spawnExplosion(pos, c, 8, 0, 20));
  };

  const spawnDeathShower = useCallback((pos: Vector2, facing: number = 0, multiplier: number = 1, isBossDeath: boolean = false, spreadOverride?: number) => {
    const spread = spreadOverride !== undefined ? spreadOverride : (isBossDeath ? 45 : 35);
    PARTICLE_PALETTES.FLESH.forEach(c => spawnExplosion(pos, c, Math.ceil(8 * multiplier), facing * 18, spread, false, isBossDeath));
    PARTICLE_PALETTES.GORE.forEach(c => spawnExplosion(pos, c, Math.ceil(12 * multiplier), facing * 22, spread + 10, false, isBossDeath));
    if (!isBossDeath) {
      spawnExplosion(pos, '#FF4500', Math.ceil(10 * multiplier), facing * 12, 40);
      spawnExplosion(pos, '#FFFF00', Math.ceil(5 * multiplier), facing * 8, 30);
    }
  }, [spawnExplosion]);

  const playGlassShatterSound = useCallback(() => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      for(let i=0; i<12; i++) {
        const osc = ctx.createOscillator(); const gain = ctx.createGain();
        osc.type = i % 2 === 0 ? 'sine' : 'sawtooth';
        osc.frequency.setValueAtTime(1200 + Math.random() * 5000, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.3);
        gain.gain.setValueAtTime(0.1, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.3);
        osc.connect(gain); gain.connect(ctx.destination);
        osc.start(); osc.stop(ctx.currentTime + 0.3);
      }
    } catch (e) {}
  }, []);

  const spawnGlassShatter = useCallback((pos: Vector2) => {
    PARTICLE_PALETTES.GLASS.forEach(c => spawnExplosion(pos, c, 5, 0, 25, true));
    playGlassShatterSound();
  }, [spawnExplosion, playGlassShatterSound]);

  const speakVulgarity = useCallback((category: VulgarityType) => {
    const state = gameStateRef.current;
    if (!('speechSynthesis' in window)) return;
    if (category === 'death') { window.speechSynthesis.cancel(); state.voiceLineCooldown = 0; } 
    else { if (window.speechSynthesis.speaking) return; if (state.voiceLineCooldown > 0) return; }
    let pool = VULGARITIES.GUN_KILL;
    if (category === 'hurt') {
      if (state.arenaLocked && stageId && BOSS_DIALOGUE.HURT[stageId as keyof typeof BOSS_DIALOGUE.HURT]) pool = BOSS_DIALOGUE.HURT[stageId as keyof typeof BOSS_DIALOGUE.HURT];
      else pool = VULGARITIES.HURT;
    }
    if (category === 'death') pool = VULGARITIES.DEATH;
    if (category === 'charge_kill') pool = VULGARITIES.CHARGE_KILL;
    if (category === 'uppercut_kill') pool = VULGARITIES.UPPERCUT_KILL;
    if (category === 'boulder_kill') pool = VULGARITIES.BOULDER_KILL;
    if (category === 'shotgun_kill') pool = VULGARITIES.SHOTGUN_KILL;
    if (category === 'flamethrower_kill') pool = VULGARITIES.FLAMETHROWER_KILL;
    if (category === 'tsunami_kill') pool = VULGARITIES.TSUNAMI_KILL;
    if (category === 'dart_kill') pool = VULGARITIES.DART_KILL;
    if (category === 'taser_kill') pool = VULGARITIES.TASER_KILL;
    if (category === 'sludge_kill') pool = VULGARITIES.SLUDGE_KILL;
    if (category === 'oil_rocket_kill') pool = VULGARITIES.OIL_ROCKET_KILL;
    const text = pool[Math.floor(Math.random() * pool.length)];
    state.playerLastVulgarity = text; state.playerVulgarityTimer = VULGARITY_TEXT_DURATION;
    const utterance = new SpeechSynthesisUtterance(text); utterance.pitch = 0.1; utterance.rate = 1.2; utterance.volume = 1.0;
    utterance.onend = () => { state.voiceLineCooldown = VOICE_LINE_COOLDOWN_FRAMES; };
    utterance.onerror = () => { state.voiceLineCooldown = VOICE_LINE_COOLDOWN_FRAMES; };
    window.speechSynthesis.speak(utterance);
  }, [stageId]);

  const playGunSound = useCallback((type: 'gun' | 'ice' | 'flame' | 'tsunami' | 'dart' | 'horn' | 'ignite' | 'barf' = 'gun') => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator(); const gain = ctx.createGain();
      if (type === 'gun') {
        osc.type = 'sawtooth'; osc.frequency.setValueAtTime(150, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.1);
        gain.gain.setValueAtTime(0.05, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);
      } else if (type === 'ice') {
        osc.type = 'sine'; osc.frequency.setValueAtTime(800, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(1200, ctx.currentTime + 0.1);
        gain.gain.setValueAtTime(0.08, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.15);
      } else if (type === 'flame') {
        osc.type = 'triangle'; osc.frequency.setValueAtTime(40 + Math.random() * 40, ctx.currentTime);
        osc.frequency.linearRampToValueAtTime(120, ctx.currentTime + 0.05);
        gain.gain.setValueAtTime(0.03, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.05);
      } else if (type === 'barf') {
        osc.type = 'sawtooth'; 
        osc.frequency.setValueAtTime(160, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.4);
        gain.gain.setValueAtTime(0.1, ctx.currentTime); 
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.4);
      } else if (type === 'dart') {
        osc.type = 'square'; osc.frequency.setValueAtTime(2200, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(800, ctx.currentTime + 0.05);
        gain.gain.setValueAtTime(0.04, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.05);
      } else if (type === 'ignite') {
        osc.type = 'sawtooth'; osc.frequency.setValueAtTime(50, ctx.currentTime);
        osc.frequency.linearRampToValueAtTime(350, ctx.currentTime + 0.5);
        gain.gain.setValueAtTime(0.3, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.6);
      } else if (type === 'horn') {
          osc.type = 'sawtooth'; osc.frequency.setValueAtTime(220, ctx.currentTime);
          const osc2 = ctx.createOscillator(); osc2.type = 'sawtooth'; osc2.frequency.setValueAtTime(277, ctx.currentTime);
          gain.gain.setValueAtTime(0.1, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.8);
          osc.connect(gain); osc2.connect(gain); gain.connect(ctx.destination);
          osc.start(); osc2.start(); osc.stop(ctx.currentTime + 0.8); osc2.stop(ctx.currentTime + 0.8);
          return;
      } else if (type === 'tsunami') {
          const bufferSize = ctx.sampleRate * 0.5; 
          const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
          const data = buffer.getChannelData(0);
          for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;
          const noise = ctx.createBufferSource();
          noise.buffer = buffer;
          const filter = ctx.createBiquadFilter();
          filter.type = 'lowpass'; filter.frequency.setValueAtTime(1000, ctx.currentTime); filter.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.5);
          noise.connect(filter); filter.connect(ctx.destination);
          noise.start();
          return;
      }
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(); osc.stop(ctx.currentTime + 0.1);
    } catch (e) {}
  }, []);

  const spawnPickup = (pos: Vector2) => {
    const r = Math.random();
    if (r < 0.6) {
        const pr = Math.random();
        let type: PickupType;
        if (pr < 0.25) type = 'small_health';
        else if (pr < 0.35) type = 'large_health';
        else if (pr < 0.8) type = 'small_ammo';
        else type = 'large_ammo';
        gameStateRef.current.pickups.push({ id: `pickup-${Date.now()}-${Math.random()}`, pos: { ...pos }, vel: { x: (Math.random() - 0.5) * 4, y: -5 }, width: 20, height: 20, type, life: 600 });
    }
  };

  // Level Generation Logic
  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    const stageWidth = 8000; const doorX = BOSS_DOOR_X;

    state.playerLastVulgarity = "";
    state.playerVulgarityTimer = 0;
    state.bossLastVulgarity = "";
    state.bossVulgarityTimer = 0;
    if ('speechSynthesis' in window) window.speechSynthesis.cancel();

