    // Arms
    const armY = bodyY + player.height * 0.15;
    ctx.fillStyle = COLORS.MEATHEAD_SKIN;
    ctx.fillRect(player.width * 0.2, armY, 12, 24); // Back arm

    // Weapon rendering
    ctx.fillStyle = COLORS.GUN;
    if (player.currentWeapon === 'BOULDER') ctx.fillStyle = '#5D4037';
    else if (player.currentWeapon === 'SHOTGUN') ctx.fillStyle = '#00FFFF';
    else if (player.currentWeapon === 'FLAMETHROWER') ctx.fillStyle = '#FF4500';
    // ... other weapon colors

    ctx.save();
    if (player.currentWeapon === 'FLAMETHROWER' && player.flameAngle) {
       ctx.translate(player.width * 0.6, armY + 10);
       ctx.rotate(player.flameAngle);
       ctx.translate(-(player.width * 0.6), -(armY + 10));
    }
    ctx.fillRect(player.width * 0.4, armY + 5, 30, 10);
    ctx.restore();

    ctx.fillStyle = COLORS.MEATHEAD_SKIN;
    ctx.fillRect(player.width * 0.4, armY, 12, 24); // Front arm

    // Effects
    if (player.isCharging) {
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(player.width/2, player.height/2, player.width, 0, Math.PI*2);
      ctx.stroke();
    }

    if (player.filthShieldTimer && player.filthShieldTimer > 0) {
      ctx.fillStyle = 'rgba(46, 125, 50, 0.4)';
      ctx.beginPath();
      ctx.arc(player.width/2, player.height/2, player.width * 0.8 + (Math.sin(state.frame * 0.2) * 5), 0, Math.PI*2);
      ctx.fill();
    }

    ctx.restore();

    // Text Bubbles
    if (state.playerVulgarityTimer > 0 && state.playerLastVulgarity) {
        ctx.font = 'bold 10px monospace';
        const textWidth = ctx.measureText(state.playerLastVulgarity).width;
        const bubbleX = player.pos.x + player.width/2 - textWidth/2;
        const bubbleY = player.pos.y - 30;

        ctx.fillStyle = 'white';
        ctx.fillRect(bubbleX - 4, bubbleY - 12, textWidth + 8, 16);
        ctx.strokeStyle = 'black';
        ctx.strokeRect(bubbleX - 4, bubbleY - 12, textWidth + 8, 16);
        ctx.fillStyle = 'black';
        ctx.fillText(state.playerLastVulgarity, bubbleX, bubbleY);
    }
  }, []);

  const draw = useCallback(() => {
    if (!canvasRef.current) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;
    const state = gameStateRef.current;

    // -- Background --
    const stageColor = stageId ? STAGE_COLORS[stageId] : null;
    ctx.fillStyle = stageColor ? stageColor.bg : COLORS.BG_DARK;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    ctx.save();

    // -- Camera Shake --
    if (state.screenShakeTimer > 0) {
      const mag = Math.min(SCREEN_SHAKE_MAX, state.screenShakeTimer);
      ctx.translate((Math.random() - 0.5) * mag, (Math.random() - 0.5) * mag);
    }

    // -- Camera Translation --
    ctx.translate(-state.camera.x, -state.camera.y);

    // -- Draw Blocks --
    state.blocks.forEach(b => {
      if (b.type === 'pit') return;
      if (b.type === 'door') {
         ctx.fillStyle = '#333';
         ctx.fillRect(b.x, b.y, b.w, b.h);
         const doorOpen = state.doorOpenAmount || 0;
         ctx.fillStyle = '#555';
         ctx.fillRect(b.x, b.y - doorOpen, b.w, b.h / 2);
         ctx.fillRect(b.x, b.y + b.h / 2 + doorOpen, b.w, b.h / 2);
         return;
      }
      ctx.fillStyle = stageColor ? (b.type === 'ground' || b.type === 'platform' ? stageColor.ground : '#444') : '#555';
      if (b.type === 'wall') ctx.fillStyle = '#222';
      ctx.fillRect(b.x, b.y, b.w, b.h);
      ctx.strokeStyle = '#000'; ctx.lineWidth = 2; ctx.strokeRect(b.x, b.y, b.w, b.h);
    });

    // -- Draw Pickups --
    state.pickups.forEach(p => {
       ctx.fillStyle = p.type.includes('health') ? '#ef4444' : '#eab308'; 
       ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2);
       const scale = 1.0 + Math.sin(state.frame * 0.1) * 0.1;
       ctx.scale(scale, scale);
       ctx.fillRect(-p.width/2, -p.height/2, p.width, p.height);
       ctx.restore();
    });

    // -- Draw Particles --
    state.particles.forEach(p => {
      if (p.isWater) return; 
      ctx.fillStyle = p.color; ctx.globalAlpha = Math.min(1.0, p.life / 20);
      ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); ctx.globalAlpha = 1.0;
    });

    // -- Draw Enemies --
    state.enemies.forEach(e => {
       if (e.health <= 0 && !e.isBlownAway) return;
       ctx.save();
       if (e.type === 'boss') {
          BossLogic.drawBoss(ctx, e, stageId, state.frame);
          if (stageId === 'Drug Trade Dale') BossLogic.drawDaleDrugs(ctx, e);
       } else {
          // Standard Enemy Rendering
          ctx.translate(e.pos.x, e.pos.y);
          if (e.isBlownAway) ctx.rotate(e.rotation || 0);
          ctx.fillStyle = COLORS.ENEMY_TANK;
          ctx.fillRect(0, 0, e.width, e.height);
       }

       if (e.isTased) { ctx.strokeStyle = '#00FFFF'; ctx.strokeRect(e.pos.x, e.pos.y, e.width, e.height); }

       // Boss Health Bar (Above head)
       if (e.type === 'boss' && e.health > 0) {
         ctx.fillStyle = 'black'; ctx.fillRect(e.pos.x, e.pos.y - 15, e.width, 5);
         ctx.fillStyle = 'red'; ctx.fillRect(e.pos.x, e.pos.y - 15, e.width * (e.health / e.maxHealth), 5);
       }
       ctx.restore();
    });

    // -- Draw Player --
    drawPlayer(ctx);

    // -- Draw Projectiles --
    state.projectiles.forEach(p => {
       ctx.save(); ctx.translate(p.pos.x, p.pos.y);
       if (p.rotation) { ctx.translate(p.width/2, p.height/2); ctx.rotate(p.rotation); ctx.translate(-p.width/2, -p.height/2); }
       ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY;
       ctx.fillRect(0, 0, p.width, p.height);
       ctx.restore();
    });

    // -- Draw Damage Numbers --
    state.damageNumbers.forEach(d => {
       ctx.fillStyle = d.isCritical ? '#FFD700' : 'white';
       ctx.font = `bold ${d.isCritical ? '24px' : '16px'} Arial`;
       ctx.strokeStyle = 'black'; ctx.lineWidth = 3;
       ctx.strokeText(d.value.toString(), d.pos.x, d.pos.y);
       ctx.fillText(d.value.toString(), d.pos.x, d.pos.y);
    });

    ctx.restore();
  }, [stageId, drawPlayer]);

  // -- Main Loop Trigger --
  useEffect(() => {
    let frameId: number; 
    const loop = () => { update(); draw(); frameId = window.requestAnimationFrame(loop); };
    const state = gameStateRef.current;
    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) { 
      if (state.frame === 0 && status === GameStatus.LEVEL_INTRO) { 
        state.frame = 1;
        createLevel(); 
      }
      frameId = window.requestAnimationFrame(loop); 
    } else { 
      // Reset state on Menu
      state.victoryString = ""; state.postVictoryTimer = 0; state.bossExplosionTimer = 0; state.introTimer = 0; state.enemies = []; state.particles = []; state.projectiles = []; state.blocks = []; state.camera = { x: 0, y: 0 }; state.frame = 0; draw(); 
    }
    return () => window.cancelAnimationFrame(frameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

import React from 'react';
import { WeaponType } from '../types';

interface HUDProps {
  health: number;
  maxHealth: number;
  specialCharges: number;      // Current number of available dash/uppercut charges
  specialChargeTimer: number;  // Frames accrued towards next charge
  maxChargeTimer: number;      // Frames needed for full charge (60 = 1 sec)
  currentWeapon: WeaponType;
  ammo: number;
  maxAmmo: number;
}

// React component for the Heads-Up Display.
// This is overlayed on top of the Canvas using absolute positioning.
const HUD: React.FC<HUDProps> = ({ health, maxHealth, specialCharges, specialChargeTimer, maxChargeTimer, currentWeapon, ammo, maxAmmo }) => {
  const healthPercent = Math.max(0, (health / maxHealth) * 100);

  // Calculate recharge progress of the current pending charge
  const rechargePercent = (specialChargeTimer / maxChargeTimer) * 100;

  const hasLimitedAmmo = maxAmmo !== Infinity;
  const ammoPercent = hasLimitedAmmo ? Math.max(0, (ammo / maxAmmo) * 100) : 100;

  const getDisplayName = (w: WeaponType) => {
    if (w === 'OIL_ROCKET') return 'ROCKET';
    if (w === 'FLAMETHROWER') return 'FLAME';
    return w;
  };

  return (
    <div className="absolute inset-0 pt-10 px-8 pb-6 pointer-events-none select-none z-10 flex flex-col justify-between">
      {/* Top Section */}
      <div className="flex justify-between items-start w-full">
        <div className="flex flex-col gap-2">
          {/* HP Bar */}
          <div className="flex items-center gap-4">
            <span className="text-white text-[10px] font-black italic">HP</span>
            <div className="w-48 h-5 bg-black border-2 border-white overflow-hidden shadow-[2px_2px_0px_white]">
              <div 
                className="h-full bg-red-600 transition-all duration-150" 
                style={{ width: `${healthPercent}%` }}
              />
            </div>
          </div>

          {/* Combined Special Move Charges */}
          <div className="flex items-center gap-4">
            <span className="text-white text-[10px] font-black italic">PWR</span>
            <div className="flex gap-1 items-center h-5">
              {[...Array(2)].map((_, i) => {
                const isFull = i < specialCharges;
                const isRecharging = i === specialCharges;
                return (
                  <div key={i} className="w-8 h-4 bg-black border-2 border-white relative shadow-[1px_1px_0px_white]">
                    {isFull && <div className="absolute inset-0 bg-yellow-500" />}
                    {isRecharging && (
                      <div 
                        className="absolute inset-y-0 left-0 bg-yellow-500/50" 
                        style={{ width: `${rechargePercent}%` }}
                      />
                    )}
                  </div>
                );
              })}
            </div>
          </div>

          {/* Weapon Status */}
          <div className="mt-2 flex items-center gap-4">
            <span className="text-white text-[10px] font-black italic">WPN</span>
            <div className="flex flex-col gap-1 items-start">
              <div className="w-fit px-2 py-1 bg-red-800 border-2 border-white text-white text-[9px] font-black italic shadow-[2px_2px_0px_white] whitespace-nowrap">
                {getDisplayName(currentWeapon)}
              </div>

              {hasLimitedAmmo && (
                <div className="flex items-center gap-2 mt-1">
                   <div className="w-24 h-2 bg-black border border-white overflow-hidden">
                     <div 
                        className="h-full bg-yellow-400" 
                        style={{ width: `${ammoPercent}%` }}
                      />
                   </div>
                   <span className="text-white text-[8px] font-black">{Math.floor(ammo)}</span>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

