	uppercutKey = _upHeld && (keyboard_check(vk_shift) || gamepad_button_check(0, gp_face2));
	uppercutKey = clamp(uppercutKey,0,1);

	//jump key buffering
	if jumpKeyPressed
	{
		jumpKeyBufferTimer = jumpBufferTime;
	}

	if jumpKeyBufferTimer > 0
	{
		jumpKeyBuffered = true;
		jumpKeyBufferTimer--;
	} else {
		jumpKeyBuffered = false;
	}
}

//custom functions for player
function setOnGround(_val)
{
	if _val == true
	{
		onGround = true;
		coyoteAirTimer = coyoteAirFrames;
	} else { 
		onGround = false;
		coyoteAirTimer = 0;
	}
}

function InitiateCooldowns()
{
	if(chargeCooldown > 0)
		chargeCooldown--;
	if(uppercutCooldown > 0)
		uppercutCooldown--;
}

