getControls();

//x movement
	//direction

	//charging and uppercutting initializations
	InitiateCooldowns();

	// Reset air usage if on ground
	if (onGround) {
		airChargeUsed = false;
		airUppercutUsed = false;
	}

	// UPPERCUT CHECK (Priority over Charge because inputs overlap)
	// Requires: Input, Not Crouching, Not Busy, Cooldown Ready, AND (On Ground OR Hasn't used air uppercut)
	if(uppercutKeyPressed && !isCrouching && !isUppercutting && uppercutCooldown == 0 && (onGround || !airUppercutUsed))
	{
		isUppercutting = true;
		uppercutTimer = uppercutDuration;
		isCharging = false; // Override charge if it happened
		if (!onGround) airUppercutUsed = true;
	}
	// CHARGE CHECK
	// Requires: Input, Not Crouching, Not Busy, Cooldown Ready, AND (On Ground OR Hasn't used air charge)
	else if(chargeKeyPressed && !isCrouching && !isCharging && chargeCooldown == 0 && (onGround || !airChargeUsed))
	{
		isCharging = true;
		chargeTimer = chargeDuration;
		isUppercutting = false;
		if (!onGround) airChargeUsed = true;
	}

	movDir = rightKey - leftKey;

	if(isCharging)
	{
		xVel = face * chargeSpd;
		chargeTimer--;
		if(!onGround) { yVel = 0; }
		if(chargeTimer <= 0 || !chargeKey)
		{
			isCharging = false;
			xVel = 0;
			chargeCooldown = COOLDOWN_CHARGE;
		}
	} 
	if(isUppercutting)
	{
		yVel = uppercutSpd * -1;
		uppercutTimer--;
		if(uppercutTimer <= 0 || !uppercutKey)
		{
			isUppercutting = false;
			yVel = 0;
			uppercutCooldown = COOLDOWN_UPPERCUT;
		}
	}

	//get my face
	if movDir != 0 { face = movDir  };

	//plain ol' walkin!
	if (!isCrouching && !isCharging){	xVel = movDir * movSpd };

	//x collision
	var _subPixel = 0.5;
	if place_meeting(x + xVel, y, oWall)
	{
		//scoot up to wall precisely
		var _pixelCheck = _subPixel * sign(xVel);

		while !place_meeting(x + _pixelCheck, y, oWall)
		{
			x += _pixelCheck;
		}

		isCharging = false;	
		//set xvel to zero to 'collide'
