	{
		//scoot up to the wall precisely
		var _pixelCheck	= _subPixel * sign(yVel);
		while !place_meeting(x, y + _pixelCheck, oWall)
		{
			y += _pixelCheck;
		}

		//BONK
		if (yVel < 0)
		{
			jumpHoldTimer = 0;
			isUppercutting = false; // Bonking head stops uppercut
		}

		//set yvel to 0 to collide
		yVel = 0;
	}

	//set if I'm on the ground
	if yVel >= 0 && place_meeting(x, y+1, oWall)
	{
		setOnGround(true);
	}

	//move
	y += yVel;

//sprite control
